SELECT 'moj-all-verified-judgments-review-002-chunk-081' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c1b94a0c-8a84-5564-a2be-d657f443d27e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -اصطحاب امرأتن أجنبيتن -كبر الكمية املضبوطة -اإلقرار بالتعاطي - التعزير للشبهة .","document_number":"3438665","case_number":"3476029","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/17","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -اصطحاب امرأتن أجنبيتن -كبر الكمية املضبوطة -اإلقرار بالتعاطي - التعزير للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3438665 :‬تاريخه ‪1434/2/17:‬هـ‬\n                    ‫رقم القضية‪3476029 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3456395‬تاريخه‪1434/03/07:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬اصطحــاب‬\n‫امرأتــن أجنبيتــن ‪ -‬كبــر الكميــة املضبوطــة ‪ -‬اإلقــرار بالتعاطــي ‪-‬‬\n                                                     ‫التعزيــر للشــبهة ‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة الرابعة من القرار الوزاري رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n                      ‫‪ -2‬قرار وزير الداخلية رقم (‪ )2057‬لعام ‪1404‬هـ ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد الترويــج‬\n‫والتعاطــي واصطحابــه المرأتــن ال متتــان لــه بصلــة شــرعية وطلــب‬\n‫إثبــات مــا أســند إليــه ومعاقبتــه تعزيــر ًا ومنعــه مــن الســفر وفــق األنظمــة‬\n‫والتعليمــات‪ ،‬أثنــاء قيــام الدوريــة األمنيــة بواجبهــا أتــت ســيارة يقودهــا‬\n‫املدعــى عليــه ويرافقــه امرتــان ال متتــان لــه بصلــة شــرعية وبتفتيــش‬\n‫الســيارة عثــر بداخلهــا علــى نبــات القــات وأثبــت التقريــر الكيميائــي‬\n‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى‬\n‫عليــه علــى الدعــوى ماعــدا الترويــج فأنكــره ‪ ،‬وبينــة املدعــي العــام‬\n‫كبــر الكميــة املضبوطــة ومت إثبــات إدانــة املدعــى عليــه بحيــازة‬\n‫القــات بقصــد االســتعمال الشــخصي ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n\n                                                                                        ‫‪176‬‬\n\f      ‫احملكمــة بســجنه تعزيــر ًا وصــرف النظــر عــن طلــب املدعــي العــام لعــدم‬\n      ‫ثبــوت اإلدانــة بالترويــج وتعزيــره لشــبهة الترويــج والصطحابــه احملــرم‬\n      ‫شــرع ًا ولتعــدد ســوابقه بجلــده مائــة وخمســن جلــدة مفرقــة علــى ثــاث‬\n      ‫فتــرات وصــرف النظــر عــن طلــب املدعــي العــام منعــه مــن الســفر و قنــع‬\n      ‫‪،‬وصــدق احلكــم مــن‬‫املدعــى عليــه واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 3476029‬وتاريــخ ‪ 1434/02/16‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 34382111‬وتاريخ ‪ 1434/02/16‬هـ ففي يوم األحد‬\n      ‫املوافق‪ 1434/02/17‬هـ افتتحت اجللسة األولى الساعة ‪ 08 : 30‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم ‪ 9882‬يف ‪1433/3/22‬ه ـ‬\n      ‫وادعــى علــى احلاضــر معــه الســجني ‪(..... /‬ســعودي ) اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪).....‬حيــث إنــه بتاريــخ ‪1433/1/4‬ه ـ وأثنــاء قيــام‬\n      ‫إحــدى دوريــات املجاهديــن بواجبهــا يف املوقــع املســمى ‪ .............‬أتــت‬\n      ‫ســيارة مــن نــوع ‪ ...‬حتمــل اللوحــة رقــم (‪( ).....‬مســتأجره مــن قبــل مؤسســة‬\n      ‫‪.....‬للمقــاوالت) (مضبوطــة حلــن مراجعــة مالكهــا) بقيــادة املدعــي عليــه‬\n      ‫ويرافقــه كل مــن املدعوة‪(...../‬إثيوبيــة اجلنســية) ( لــم يوجــه لهــا االتهــام‬\n      ‫مــع إحالتهــا إلــى جهــة القبــض للنظــر يف قضيــة اخللــوة ) واملدعــوة ‪..... /‬‬\n      ‫(إثيوبيــة اجلنســية) ( لــم يوجــه لهــا االتهــام مــع إحالتهــا إلــى جهــة القبــض‬\n      ‫للنظــر يف قضيــة اخللــوة )(فــرزت أوراق وأحيلــت جلهــة االختصــاص‬\n\n‫‪177‬‬\n\f‫للمدعــي عليــه لقــاء أركابــه مخالفــي نظــام اإلقامــة) وباســتيقاف‬\n‫الســيارة وتفتيشــها عثــر بداخلهــا علــى كميــة مــن نبــات القــات باألمــام‬\n‫وباخللــف وبلــغ وزنهــا (‪ 26‬كجــم) ســتة وعشــرون كيلــو جرام ـ ًا مــن‬\n‫نبــات القــات احملظــور‪ ،‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/1/12‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة والشــرعية بجــازان إيجابيــة العينــة املرســلة منــه‬\n‫لنبــات القــات احملظــور املدرجــة باجلــدول رقــم(‪ )4‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة املرفقــة بالتعميــم البرقــي لصاحــب الســمو‬\n‫امللكــي وزيــر الداخليــة (‪ )89400/19‬يف ‪1426/10/25‬ه ـ والصــادر‬\n‫باملرســوم امللكــي رقــم( م ‪) 39/‬وتاريــخ ‪1426/7/8‬ه ـ أوقــف اســتنادا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪ 1428/7/9‬ه ـ كــون جرميتــه‬\n‫مــن اجلرائــم املوجبــة للتوقيــف‪ .‬وباســتجواب املدعــي عليــه ومواجهتــه‬\n‫بالتهــم املنســوبة إليــه أقــر بحيازتــه للكميــة املضبوطــة وأن غرضــه‬\n‫منهــا االســتخدام الشــخصي وأنــه قــام بشــرائها مــن محافظــة ‪ ........‬مــن‬\n‫شــخص يدعــى‪ .....‬مببلــغ وقــدرة (‪1000‬ريال)وأنــه ينــوي إيصالهــا إلــى‬\n‫منزلــه بقريــة ‪.....‬التابعــة حملافظــة صبيــا وأنــه قــام بــإركاب مرافقتيــه‬\n‫مــن محافظــة ‪ ........‬وينــوي إيصالهمــا حملافظــة صبيــا مببلــغ وقــدرة‬\n   ‫(‪ 500‬ريــال) وأن ليــس لهمــا أي علــم أو عالقــة بالكميــة املضبوطــة‪.‬‬\n‫وقــد أســفر التحقيــق مــع املدعــي عليــه عــن توجيــه االتهــام لــه بحيازتــه‬\n‫مــا وزنــه (‪ 26‬كجــم) ســتة وعشــرون كيلــو جرام ـ ًا مــن نبــات القــات‬\n‫احملظــور بقصــد الترويــج والتعاطــي‪ ،‬واملجــرم مبوجــب الفقــرة الثانيــة‬\n‫مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وقيامــه‬\n\n\n                                                                                    ‫‪178‬‬\n\f                                 ‫باصطحــاب المرأتــن ال متتــان لــه بصلــة شــرعية‪.‬‬\n                                                       ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n               ‫‪ -1‬ما جاء يف إقراره املصدق حتقيق ًا املنوه عنه واملدون لفه (‪)19‬‬\n      ‫‪ -2‬مــا ورد مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n                                                                             ‫رقــم (‪. )5.6‬‬\n                        ‫‪ -3‬ما جاء يف سماع أقواله املنوه عنها واملدونة لفه (‪. )9‬‬\n         ‫‪ -4‬ما ورد بالتقرير الكيميائي الشرعي املنوه عنه املرفق لفه (‪. )25‬‬\n      ‫وبالبحــث عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى ‪ /‬دخــول‬\n      ‫منــازل لغــرض ســيء والثانيــة‪ /‬اســتعمال قــات والثالثــة ‪ /‬نقــل قــات‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــي عليــه فعــل محــرم شــرع ًا و معاقــب‬\n      ‫عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا‬\n                                                                ‫حلــق بــه مــن تعديــات‪.‬‬\n                                ‫لذا اطلب‪/‬إثبات إدانته مبا أسند إليه واحلكم بـ‪:‬‬\n      ‫‪.1‬تعزيــره يف ضــوء املــادة (الثالثــة والرابعــة) مــن القــرار الــوزاري املشــار‬\n      ‫إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n                           ‫‪1432/12/9‬هـ‪.‬والتشــديد عليــه لقــاء تعــدد ســوابقه‬\n                            ‫‪.2‬احلكم مبنعه من السفر بعد انقضاء محكوميته‪.‬‬\n                                              ‫‪.3‬تعزيرة لقاء اصطحابه احملرم شرعاً‪.‬‬\n      ‫وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه صــدق علــى‬\n      ‫صحــة مــا جــاء فيهــا و أقــر بحيازتــه للكميــة املضبوطــة وأن غرضــه‬\n      ‫منهــا االســتخدام الشــخصي وأنــه قــام بشــرائها مــن محافظــة الدائــر مــن‬\n      ‫شــخص يدعــى ‪ .....‬مببلــغ وقــدرة (‪1000‬ريــال) وأنــه ينــوي إيصالهــا إلــى‬\n      ‫منزلــه بقريــة ‪.....‬التابعــة حملافظــة صبيــا وأنــه قــام بــإركاب مرافقتيــه‬\n\n\n‫‪179‬‬\n\f‫مــن محافظــة ‪ ............ ....‬وينــوي إيصالهمــا حملافظــة صبيــا مببلــغ وقدرة‬\n‫(‪ 500‬ريــال) وأن ليــس لهمــا أي علــم أو عالقــة بالكمية املضبوطة كما‬\n‫أقــر بالســوابق املذكــورة يف الئحــة الدعــوى وأنــه نــال العقوبــة املقــررة‬\n‫عليهــا هكــذا أجــاب وقــد جــرى ســؤال املدعــي العــام عــن بينتــه علــى أن‬\n‫الكميــة معــدة للترويــج قــال بينتــي كبــر حجــم الكميــه املضبوطــة‬\n‫وال ميكــن أن تكــون لالســتعمال الشــخصي وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال الصحيــح مــا ذكــرت وأنهــا لالســتعمال الشــخصي هكــذا‬\n‫أجــاب وباالطــاع علــى محضــر القبــض والتحقيــق وجــد مطابــق ملــا جــاء‬\n‫يف الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي الشــرعي لفــة‬\n‫رقــم (‪ )25‬وجــد إيجابيــة العينــة املرســلة لنبــات القــات وباالطــاع علــى‬\n‫صحيفــة الســوابق عثــر لــه علــى ثــاث ســوابق األولــى ‪ /‬دخــول منــازل‬\n‫ـاء علــى‬\n        ‫لغــرض ســيء والثانيــة‪ /‬اســتعمال قــات والثالثــة ‪ /‬نقــل قــات فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بحيازتــه‬\n‫للكميــة املرصــودة أعــاه لغــرض االســتعمال الشــخصي وحيــث أنكــر‬\n‫قصــد الترويــج وال بينــة للمدعــي العــام ســوى كبــر حجــم الكميــه‬\n‫املضبوطــة وحيــث اعتــرف بخلوتــه ونقلــه للمرأتــن وهمــا ال متتــان لــه‬\n‫بصلــة وحيــث إن مــا أقــدم عليــه فعــل محــرم فقــد ثبــت لــدى إدانــة املدعــى‬\n‫عليــه بحيازتــه ملــا وزنــه (‪ 26‬كجــم) ســتة وعشــرون كيلــو جــرام مــن‬\n‫نبــات القــات لغــرض االســتعمال الشــخصي وحكمــت عليــه تعزيــر ًا‬\n‫بالســجن ملــدة ســنة اعتبــارا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‬\n‫اســتنادا للمــادة الرابعــة مــن القــرار الــوزاري رقــم(‪ )11‬لعام‪1374‬ه ـ‬\n‫واملعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعام‪1404‬ه ـ ورقم(‪)3818‬‬\n‫لعام‪1410‬ه ـ وصرفــت النظــر عــن طلــب املدعــي العــام لعــدم وجــود مــا‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫يؤيــد الترويــج ونظــر ًا لكبــر حجــم الكميــة ولوجــود شــبهة الترويــج‬\n      ‫والصطحابــه احملــرم شــرع ًا ولتعــدد ســوابقه فهــو يســتحق التعزيــر‬\n      ‫علــى ذلــك بجلــده ألجــل ذلــك مائــة و خمســون جلــدة مفرقــة علــى ثــاث‬\n      ‫فتــرات بــن كل فتــرة واألخــرى ال يقــل عــن أســبوع وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي العــام منعــه مــن الســفر لعــدم اشــتمال القــرار رقــم ‪ 11‬لعــام‬\n      ‫‪1374‬ه ـ ومــا تبعــه مــن تعديــات علــى منــع ‪ -‬مــن حــاز كميــة مــن القــات‬\n      ‫لالســتعمال ‪ -‬مــن الســفر إذا كان ســعودي ًا ومبــا ســبق حكمــت وبهــذا‬\n      ‫انتهــت هــذه الدعــوى وبعــرض مــا حكمنــا بــه املدعــى عليــه قنــع بــه وقرر‬\n      ‫املدعــي العــام عــدم القناعــة وطلــب رفعهــا إلــى محكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34382111‬‬\n      ‫وتاريــخ ‪1434/2/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪.....‬برقم ‪ 3438665‬وتاريــخ ‪1434/2/17‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .....‬يف قضيــة (قــات) علــى الصفــة املوضحــة‬\n      ‫يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":176,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"42c9066ac207b556d8d30adfbda7b284c8b4103f72b6f9d4c24ebf9b8e08525c","normalized_text_hash":"406ecd1dd2e120565cde5c6f0c557d84e6670e297b4222145400d111a089d4b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p176-3438665"},{"id":"3959d477-bc69-5103-a71b-acdaffea66b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -شرب مسكر وحيازته بقصد االستعمال -محاولة الهرب من رجال األمن -إقرار -بينة غير موصلة -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة بقصد التعاطي -حد املسكر -تعزير باجللد والسجن واملنع من السفر.","document_number":"342030072","case_number":"3477434","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/04","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -شرب مسكر وحيازته بقصد االستعمال -محاولة الهرب من رجال األمن -إقرار -بينة غير موصلة -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة بقصد التعاطي -حد املسكر -تعزير باجللد والسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 342030072:‬تاريخه‪1434/06/04 :‬هـ‬\n                       ‫رقم الدعوى‪3477434:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35112419‬تاريخه‪1434/01/11:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي والترويــج‬\n  ‫وتعاطيهــا‪ -‬شــرب مســكر وحيازتــه بقصــد االســتعمال‪ -‬محاولــة الهــرب‬\n  ‫مــن رجــال األمــن‪ -‬إقــرار‪ -‬بينــة غيــر موصلــة‪ -‬عــدم التقيــد بالوصــف‬\n  ‫الــوارد يف الئحــة الدعــوى‪ -‬إدانــة باحليــازة بقصــد التعاطــي ‪ -‬حــد‬\n                  ‫املســكر ‪ -‬تعزيــر باجللــد والســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n             ‫‪ -1‬قول اهلل تعالى‪(( :‬إمنا اخلمر وامليسر‪ ..‬اآلية)) املائدة‪90:‬‬\n  ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                          ‫حــرام)‪ .‬رواه مســلم‬\n  ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬إن اهلل لعــن اخلمــر وعاصرهــا‪..‬‬\n                                                   ‫احلديــث)‪ .‬رواه احلاكــم‪.‬‬\n                  ‫‪ -4‬قرار هيئة كبار العلماء رقم (‪ )53‬يف ‪1397/4/4‬هـ ‪.‬‬\n           ‫‪ -5‬املواد (‪ )128‬و (‪ )131‬و(‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n  ‫‪ -6‬املــواد (‪ )3‬و(‪ )41‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n                                                                                  ‫‪182‬‬\n\f      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهــم تتضمــن طلــب إثبــات إدانــة‬\n      ‫الثانــي بحيــازة حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي والترويــج‬\n      ‫وتعاطيــه لهــا وإدانــة الثالــث بحيــازة املســكر بقصــد االســتعمال وشــربه‬\n      ‫لــه وإدانــة األول مبحاولــة الهــرب مــن رجــال األمــن ومحاولــة مقاومتهــم‬\n      ‫وشــرب املســكر‪ ،‬واحلكم على الثاني بعقوبة الســجن واجللد والغرامة‬\n      ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وبعقوبــة تعزيريــة لــأول والثالــث لقــاء مــا نســب إليهمــا‪ ،‬قبــض عليهــم‬\n      ‫يف مزرعــة بعــد ورود معلومــات عــن اتخاذهــا وكــرا ملروجــي املخــدرات‬\n      ‫فحــاول األول الهــرب مــن رجــال األمــن ومقاومتهــم‪ ،‬وبتفتيــش املزرعــة‬\n      ‫عثــر حتــت ســيارة متوقفــة بجوارهــم مباشــرة علــى حقيبــة بهــا كميــة‬\n      ‫مــن احلبــوب احملظــورة وإثبــات هويــة الثانــي وعثــر بداخــل املزرعــة علــى‬\n      ‫قــارورة مســكر‪ ،‬أثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة‬\n      ‫املرســلة لإلمفيتامــن وللكحــول‪ ،‬أقــر الثانــي أمــام احملكمــة بحيازتــه‬\n      ‫للحبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهــا وأنكــر قصــد‬\n      ‫الترويــج وأقــر األول والثالــث بالتهــم املنســوبة لهمــا ســوى محاولــة األول‬\n      ‫مقاومــة رجــال األمــن‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه‬\n      ‫وقــررت ســماع شــهادة شــهود محضــر القبــض فلــم جتــد فيهــا مــا يثبــت‬\n      ‫مــا أنكــره املدعــى عليهــم ممــا جــاء يف الدعــوى‪ ،‬قضــت احملكمــة‬\n      ‫بإدانــة املدعــى عليــه الثانــي بتعاطــي احلبــوب احملظــورة وحيازتهــا بقصــد‬\n      ‫التعاطــي وقــررت جلــده ســتني جلــدة دفعــة واحــدة وســجنه ملــدة عشــرة‬\n      ‫أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬كمــا قضــت‬\n\n‫‪183‬‬\n\f‫بإدانــة املدعــى عليهمــا األول والثالــث بشــرب املســكر وقــررت جلــد‬\n‫كل واحــد منهمــا حــد شــرب املســكر ثمانــن جلــدة دفعــة واحــدة علنــا‬\n‫وقضــت بإدانــة املدعــى عليــه الثالــث بحيــازة قــارورة مســكر بقصــد‬\n‫االســتعمال وقــررت ســجنه أربــع وعشــرين ســاعة كمــا قضــت ببــراءة‬\n‫املدعــى عليهمــا األول والثانــي مــن باقــي التهــم املنســوبة إليهمــا لعــدم‬\n‫كفايــة األدلــة‪ ،‬قنــع املدعــى عليهمــا األول والثالــث باحلكــم وعــارض‬\n‫املدعــى عليــه الثانــي واملدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n                              ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬رئيــس احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪3477434‬‬\n‫وتاريــخ ‪1434/02/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34390233‬وتاريــخ‬\n‫‪1434/02/17‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/03/17‬ه ـ حضــر‬\n‫ال مــن‪ ........-1 :‬ســعودي‬‫املدعــي العــام كمــا حضــر املدعــى عليهــم ك ً‬\n‫رقــم ســجله املدنــي (‪ ).....‬البالــغ مــن العمــر (‪)30‬عامـ ًا ‪ ،‬غيــر محصــن ‪،‬‬\n‫عاطــل عــن العمــل ‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ ‪ ،‬وأفــرج عنــه‬\n‫بتاريــخ ‪1433/11/24‬هــ‪ ........ -2 .‬ســعودي رقــم ســجله املدنــي (‪).....‬‬\n‫البالــغ مــن العمــر (‪)34‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬عاطــل عــن العمــل ‪،‬‬\n‫قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة‬\n‫القطيــف اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪.‬‬\n‫‪ ........-3‬ســعودي رقــم ســجله املدنــي (‪ ).....‬البالــغ مــن العمــر (‪)48‬عامـاً‪،‬‬\n‫محصــن ‪ ،‬عاطــل عــن العمــل ‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬هــ‪،‬‬\n\n                                                                                     ‫‪184‬‬\n\f      ‫وافــرج عنــه بتاريــخ ‪1433/11/23‬هــ‪ .‬وقــدم األول الئحــة دعــوى تتضمــن‬\n      ‫بــأن املدعــى عليهــم أنــه بتاريــخ ‪1433/11/19‬ه ـ ورد بــاغ للمديريــة‬\n      ‫العامــة ملكافحــة املخــدرات املتضمــن وجــود مزرعة بـ ـ ‪ ........‬يف القطيف‬\n      ‫يتواجــد بهــا العديــد مــن مروجــي املخــدرات ويتخذونهــا وكــرا لهــم‬\n      ‫وبحوزتهــم أســلحة‪ .‬وباالنتقــال للموقــع والدخــول بطريقــة تكتيكيــة‬\n      ‫والســيطرة علــى جميــع املوجوديــن وهــم خمســة اشــخاص كالتالــي‪:‬‬\n      ‫‪(.........-2 .........-1‬جــرى حفــظ االتهــام بحقــه مبوجــب أمــر احلفــظ رقــم‬\n      ‫‪ 54977‬وتاريــخ ‪1433/11/22‬هــ) ‪(.-3‬جــرى حفــظ االتهــام بحقــه‬\n      ‫مبوجــب أمــر احلفــظ رقــم ‪ 54976‬وتاريــخ ‪1433/11/22‬هــ) ‪.........-4‬‬\n      ‫‪ .........-5‬عندهــا حــاول املدعــو املقاومــة والهــرب فتــم الســيطرة عليــه‬\n      ‫ووجــد داخــل أحــد الســيارات التــي كانــت بجوارهــم مباشــرة علــى‬\n      ‫ســاح رشــاش كالشــنكوف يحمــل الرقــم (‪ ).....‬وبــه عــدد (‪)285‬‬\n      ‫مئتــن وخمســة وثمانــن طلقــة (مت بعثــه مــن قبــل مكافحــة املخــدرات‬\n      ‫لألدلــة اجلنائيــة إلكمــال الــازم) كمــا عثــر حتــت نفــس الســيارة علــى‬\n      ‫حقيبــة علــى شــكل حــزام للبطــن حتتــوي علــى عــدد (‪ )150‬مئــة‬\n      ‫وخمســن مــن حبــوب اإلمفيتامــن احملظــورة وعــدد (‪ )4‬أربــع حبــات‬\n      ‫زرقــاء اللــون مجهولــة كمــا عثــر بداخــل احلقيبــة علــى إثبــات ومحفظــة‬\n      ‫للمدعــو‪ ........‬كانــت داخــل نفــس احلقيبــة وعلــى قــارورة خمــر بنفــس‬\n      ‫املزرعــة مســتورده نــوع ‪ ........‬مملــوءة وجــرى التحفــظ علــى األشــخاص‬\n      ‫ونقلهــم ملكافحــة املخــدرات ‪ ،‬اثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم ‪4143‬وتاريخ‪1433/11/28‬ه ـ املتضمــن ثبــوت إيجابيــة العينــات‬\n      ‫املضبوطــة ملــادة اإلمفيتامــن املنبهــة واحملظــورة واملدرجــة يف اجلــدول‬\n      ‫الثانــي فئــة (ب) واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n\n\n‫‪185‬‬\n\f‫كمــا اثبــت التقريــر ذاتــه إيجابيــة قــارورة املســكر املضبوطــة ملــادة‬\n‫الكحــول اإليثيلــي وبنســبة مســكرة‪ .‬وبســماع أقــوال املدعــى عليــه‬\n‫األوليــة أقــر بحيازتــه للحبــوب احملظــورة بقصد االســتعمال وأنــه يتعاطى‬\n‫احلبــوب احملظــورة وأنــه ال عالقــة لباقــي املدعــى عليهــم‪ .‬وبســماع أقــوال‬\n‫املدعــى عليــه األوليــة أقــر بحيازتــه للمســكر املضبــوط وأفــاد بــأن‬\n‫الســاح املضبــوط يعــود لشــقيقه‪ .‬وبســماع أقــوال املدعــى عليــه أقــر‬\n‫بشــربه املســكر‪ .‬وباســتجواب املدعــى عليــه أقــر بحيازتــه حلبــوب‬\n‫اإلمفيتامــن املنبهــة واحملظــورة بقصــد التعاطــي وتعاطــي نوعهــا‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بحيازتــه لقــارورة املســكر بقصــد‬\n‫الشــرب وشــرب املســكر‪ .‬وباســتجواب املدعــى عليــه أقــر بشــربه‬\n‫املســكر ومحاولتــه الهــرب خوفــا مــن رجــال الضبــط عنــد القبــض‬\n‫عليهــم كونــه ال يعلــم أنهــم رجــال أمــن وأنــه لــم يتعــد مــن املــكان ســوى‬\n‫املتريــن فقــط‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫الثاني (‪ )........‬بحيازة عدد (‪ )150‬مئة وخمســن من حبوب اإلمفيتامني‬\n‫احملظــورة بقصــد التعاطــي والترويــج وتعاطــي نوعهــا واتهــام املدعــى‬\n‫عليــه الثالــث (‪ )........‬بحيــازة قــارورة مســكر مــن نــوع ‪ ........‬بقصــد‬\n‫الشــرب وشــربه لــه واتهــام املدعــى عليــه األول (‪ )........‬مبحاولــة الهــروب‬\n‫مــن رجــال الضبــط اجلنائــي ومحاولتــه مقاومتهــم وشــرب املســكر ‪،‬‬\n‫وذلــك لألدلــة والقرائــن املوضحــة بالالئحــة وبالبحــث عــن ســوابقهم لــم‬\n‫يعثــر للمدعــى عليــه األول (‪ )........‬علــى ســوابق جنائيــة مســجلة وعثــر‬\n‫للمدعــى عليــه الثانــي (‪ )........‬ســابقة واحــدة وهــي اعتــداء وعثــر للمدعى‬\n‫عليــه الثالــث (‪ )........‬ســابقة واحــدة وهــي مضاربــة‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املذكــوران وهــم بكامــل أهليتهــم املعتبــرة شــرعا فعــل محــرم‬\n\n\n                                                                                      ‫‪186‬‬\n\f      ‫ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب مــا يلــي‪ :‬أوال‪ :‬بإثبــات مــا أســند‬\n      ‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬‫إلــى املدعــى عليــه ً‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )38‬مــن النظــام مــع مراعــاة مقتضــى املــادة ‪ 62‬مــن ذات النظــام‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إعمــاال ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )56‬مــن النظــام‪ .‬ثانيــا‪ :‬احلكــم علــى املدعــى عليــه (‪ ).....‬واملدعــى عليــه‬\n      ‫(‪ ).....‬بحــد شــرب املســكر لقــاء إقرارهمــا بشــرب املســكر‪ .‬ثالثــا‪:‬‬\n      ‫احلكــم علــى املدعــى عليهمــا (بعقوبــة تعزيرية تزجرهما وتــردع غيرهما‬\n      ‫لقــاء حيــازة املدعــى عليــه (‪ ).....‬للمســكر بقصــد الشــرب ولقــاء محاولة‬\n      ‫املدعــى عليــه الهــرب مــن رجــال الضبــط ومحاولتــه مقاومتهــم‪ .‬هــذه‬\n      ‫ا‬\n      ‫دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب املدعــى عليــه (‪ ).....‬قائ ـ ً‬\n      ‫مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ املذكــور داخــل‬\n      ‫مزرعــة يف (‪ ).....‬وإقــراري بشــرب املســكر ومحاولــة الهــرب مــن رجــال‬\n      ‫الضبــط اجلنائــي كل ذلــك صحيــح وحاولــت الهــرب لتفاجئــي بدخولهــم‬\n      ‫أمــا مــا ذكــره مــن محاولــة مقاومتهــم فغيــر صحيــح هكــذا أجــاب‬\n      ‫ا مــا ذكــره املدعــي العــام مــن القبــض‬     ‫كمــا أجــاب املدعــى عليــه قائـ ً‬\n      ‫علــي يف التاريــخ املذكــور داخــل مزرعــة يف (‪ ).....‬وأنــه عثــر بحوزتــي‬\n      ‫علــى (‪ )150‬مئــة وخمســن حبــة مــن حبــوب اإلمفيتامــن احملظــورة وأن‬\n      ‫قصــدي مــن حيازتهــا التعاطــي وأننــي أتعاطــى هــذه احلبــوب صحيــح أمــا‬\n      ‫قصــد الترويــج فإنــه غيــر صحيــح هكــذا أجــاب كمــا أجــاب املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ‬             ‫عليــه قائ ـ ً‬\n      ‫املذكــور داخــل مزرعــة يف (‪ ).....‬وأنــه عثــر بحوزتــي علــى قــارورة‬\n\n\n‫‪187‬‬\n\f‫مســكر مــن نــوع ســكواتش بقصــد الشــرب وشــربي لــه كل ذلــك‬\n‫صحيــح هكــذا أجــاب فجــرى ســؤال املدعــي العــام عــن حقيقــة محاولــة‬\n‫املدعــى عليــه مقاومــة رجــال الضبــط اجلنائــي وهــل شــرع يف ذلــك قــال‬\n‫أطلــب ســماع شــهادة رجــال الضبــط اجلنائــي فجــرى ســؤاله عــن بينتــه‬\n‫علــى وجــود قصــد الترويــج لــدى املدعــى عليــه قــال بينتي هي مــا تضمنته‬\n‫الالئحــة وهــو اآلتــي‪-1 :‬إقرارهــم حتقيقــا املنــوه عنــه واملــدون علــى‬\n‫الصفحــة رقم‪1.2‬واملرفــق لفــات رقــم (‪-2 )26-21‬إقــرار املدعــى عليــه‬\n‫مبحضــر ســماع األقــوال األوليــة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقم‪21‬واملرفــق لفــة رقــم (‪-3 )2‬إقــرار املدعــى عليــه مبحضــر ســماع‬\n‫األقــوال األوليــة املنــوه عنــه واملــدون علــى الصفحــة رقم‪23‬واملرفــق لفــة‬\n‫رقــم(‪-4 )3‬إقــرار املدعــى عليــه مبحضــر ســماع األقــوال األوليــة املنــوه‬\n‫عنــه واملــدون علــى الصفحــة رقم‪6‬واملرفــق لفــة رقــم(‪-5 )1‬مــا ورد يف‬\n‫محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى الصفحــة‬\n‫رقم‪2‬واملرفــق لفــة رقــم(‪-6 )2‬مــا ورد يف محضــر القبــض مــن وقائع املنوه‬\n‫عنهــا واملدونــة علــى الصفحــة رقم‪12‬واملرفقــة لفــة رقــم(‪-7 )1‬مــا ورد يف‬\n‫التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪-8 )49‬مــا‬\n‫ورد يف محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى‬\n‫الصفحــة رقم(‪)2‬واملرفــق لفــة رقــم(‪-9 )2‬مــا ورد يف محضــر القبــض مــن‬\n‫وقائــع املنــوه عنهــا واملدونــة علــى الصفحــة رقــم(‪ )12‬واملرفقــة لفــة‬\n‫رقــم(‪ )1‬فأفهمــت املدعــي العــام بإبــاغ معــدي محضــر القبــض باحلضــور‬\n‫يف اجللســة القادمــة لــإدالء بشــهادتهم ويف جلســة أخــرى‬\n‫بتاريخ‪1434/05/20‬ه ـ حضــر املدعــي العــام واملدعــى عليهــم و كمــا‬\n‫حضــر للشــهادة ‪ ........‬وباستشــهاده قــال أشــهد بــاهلل أننــي حضــرت رفــق‬\n\n\n                                                                                   ‫‪188‬‬\n\f      ‫أعضــاء الفرقــة وقمنــا مبداهمــة مزرعــة يف (‪ ).....‬وقــد باغتنــا املدعــى‬\n      ‫عليهــم احلاضريــن وهــم جلــوس رفــق شــخص أو اثنــن آخريــن وفــور‬\n      ‫مشــاهدتنا قــام املدعــى عليــه وأشــار إلــى متحفــز ًا للمقاومــة وفــور علمــه‬\n      ‫بأننــا رجــال أمــن لــم يبــد أي مقاومــة ومتــت الســيطرة علــى املوجوديــن‬\n      ‫وبتفتيــش املوقــع عثــر علــى ســاح رشــاش داخــل ســيارة قدميــة كمــا عثــر‬\n      ‫علــى حقيبــة بهــا كميــة مــن احلبــوب واثبــات حتــت الســيارة وعثــر علــى‬\n      ‫قــارورة مســكر يف مســتودع هــذه شــهادتي فجــرى ســؤاله هــل قــام أي‬\n      ‫مــن املدعــى عليهــم مبحاولــة املقاومــة قــال ال واضــاف بــأن بقيــة زمالئــي‬\n      ‫أعضــاء الفرقــة ال تخــرج شــهادتهم عمــا ذكــرت وقــد انتقــل اثنــان منهــم‬\n      ‫خــارج املنطقــة وتعــذر حضــور البقيــة لظــروف العمــل وبعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليهــم قــال كل واحــد منهــم بأننــي ال أقــول يف‬\n      ‫الشــاهد والشــهادة شــيئا واضــاف املدعــى عليــه بأننــي يف البدايــة لــم‬\n      ‫أكــن أعلــم أنهــم رجــال أمــن ويف جلســة أخــرى بتاريــخ ‪1434/06/04‬ه ـ‬\n      ‫حضــر املدعــي العــام وحضــر املدعــى عليهــم ‪ ........‬و ‪ ........‬و ‪........‬‬\n      ‫وبدراســة املعاملــة جــرى االطــاع علــى محضــر بــاغ يتضمــن وجــود‬\n      ‫مزرعــة بالــ(‪ ).....‬يتواجــد بهــا العديــد مــن مروجــي املخــدرات‬\n      ‫ويســتخدمونها وكــر ًا لهــم كمــا جــرى االطــاع علــى محضــر القبــض‬\n      ‫املــدون علــى صفحة(‪)12‬ملــف مرفــق لفــة (‪)1‬فوجدتــه موافقـ ًا ملــا جــاء يف‬\n      ‫دعــوى املدعــي العــام‪ .‬كمــا جــرى االطــاع علــى محضــر حتريــز مــدون‬\n      ‫علــى صحيفــة(‪ )13‬ملــف مرفــق لفــة (‪ )2‬واملتضمن ضبط مائة وخمســن‬\n      ‫حبــة وزجاجــة خمــر خارجــي كمــا جــرى االطــاع علــى محضــر ســماع‬\n      ‫أقــوال املدعــى عليــه (‪ ).....‬املــدون علــى صفحــة (‪ )21‬مــن ذات امللــف‬\n      ‫فوجدتهــا تتضمــن أن قصــده مــن احليــازة االســتعمال‪ ،‬كمــا جــرى‬\n\n\n‫‪189‬‬\n\f‫االطــاع علــى محاضــر ســماع أقــوال املدعــى عليهمــا األوليــة فلــم أجــد‬\n‫بهــا مــا يديــن املدعــى عليــه (‪ ).....‬باملقاومــة وال مــا يــدل علــى قصــد‬\n‫الترويــج لــدى املدعــى عليــه عمــاد ‪،‬كمــا جــرى االطــاع علــى محاضــر‬\n‫اســتجواب املدعــى عليهــم أمــام هيئــة التحقيــق املرفقــة علــى‬\n‫اللفات(‪)26-21‬فلــم أجــد يف اســتجواب املدعــى عليــه (‪ ).....‬مــا يفيــد‬\n‫اإلقــرار مبحاولــة املقاومــة كمــا تضمنــت إجابــة املدعــى عليــه (‪ ).....‬أن‬\n‫غرضــه مــن حيــازة احلبــوب االســتعمال الشــخصي ‪،‬كمــا جــرى االطالع‬\n‫علــى التقريــر الكيمــاوي الشــرعي املشــار لــه يف الئحــة الدعــوى العامــة‬\n‫فوجدتهــا كمــا ذكــر املدعــي العــام‪ .‬وبعــرض ذلــك علــى اجلميــع قــرر‬\n‫املدعــي العــام اكتفــاءه مبــا قــدم كمــا قــرر املدعــى عليهــم أنهــم ليــس‬\n‫لديهــم مــا يضيفــون‪ .‬فبنــاء علــى مــا تقــدم وحيــث تتلخــص دعــوى املدعــي‬\n‫العــام يف اتهــام املدعــى عليــه األول (‪ )........‬بشــرب املســكر ومحاولــة‬\n‫الهــروب مــن رجــال الضبــط اجلنائــي ومحاولــة مقاومتهــم‪ ،‬واتهــام املدعى‬\n‫عليــه الثانــي (‪ )........‬بحيــازة (‪ )150‬مئــة وخمســن حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي والترويــج وتعاطــي نوعهــا‪،‬‬\n‫واتهــام املدعــى عليــه الثالــث (‪ )........‬بشــرب املســكر وحيــازة قــارورة‬\n‫مســكر بقصــد الشــرب ‪،‬ويطلــب إثبــات مــا أســند إليهــم ومعاقبتهــم‬\n‫عليــه‪ .‬وألن هــذه احملكمــة مختصــة بنظــر الدعــوى بنــاء علــى املــواد‬\n‫(‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار املدعــى عليــه (‪).....‬‬\n‫بشــرب املســكر ومحاولــة الهــروب مــن رجــال الضبــط اجلنائــي ‪،‬وإلقرار‬\n‫املدعــى عليــه (‪ ).....‬بتعاطــي حبــوب اإلمفيتامــن احملظــورة وحيــازة‬\n‫(‪ )150‬مئــة وخمســن حبــة منهــا بقصــد التعاطــي ‪،‬وإلقــرار املدعــى عليه‬\n‫علــي بشــرب املســكر وحيــازة قــارورة مســكر بقصــد الشــرب ‪،‬وألن‬\n\n\n                                                                                   ‫‪190‬‬\n\f      ‫مــا أقدمــوا عليــه أفعــال محرمــة شــرع ًا لقولــه تعالــى (( يــا أيهــا الذيــن‬\n      ‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n      ‫فاجتنبــوه )) املائــدة‪ 90 :‬ولقولــه صلــى اهلل عليــه وســلم ((كل مس ــكر‬\n      ‫خمــر وكل خمــر حــرام )) رواه مســلم ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫((إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرها وشــاربها وحاملها واحملمولة‬\n      ‫إليــه )) رواه احلاكــم ‪،‬كمــا أن حيــازة وتعاطــي حبــوب اإلمفيتامــن‬\n      ‫احملظــورة أفعــال مجرمــة نظام ـ ًا وفق ـ ًا للفقــرة ( ‪ ) 2‬مــن املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وإلنــكار املدعــى عليــه‬\n      ‫(‪ ).....‬تهمــة محاولــة مقاومــة رجــال الضبــط اجلنائــي ولعــدم إقامــة املدعي‬\n      ‫العــام بينــة موصلــة علــى شــروع املدعــى عليــه يف الهــرب مــن رجــال‬\n      ‫ا‬\n      ‫الضبــط اجلنائــي أو مقاومتهــم وألن مجــرد محاولــة الهــرب ال يعــد فعـ ً‬\n      ‫موجبــا للتجــرمي خاصــة واملدعــى عليــه دفــع بأنــه لــم يكــن يعلــم أنهــم مــن‬\n      ‫رجــال األمــن بــل إن شــهادة رجــل الضبــط تضمنــت أن املدعــى عليــه فــور‬\n      ‫علمــه أننــا رجــال أمــن لــم يبــد أي مقاومــة ‪،‬وإلنــكار املدعــى عليــه أن‬\n      ‫قصــده مــن حيــازة احلبــوب احملظــورة الترويــج ولعــدم إقامــة املدعــي العــام‬\n      ‫بينــة موصلــة علــى قصــد االجتــار ‪ ،‬و الكميــة املضبوطــة مــن احلبــوب‬\n      ‫وإن كانــت كبيــرة إلــى حــد مــا لكنهــا تبقــى قرينــة لــم يوجــد مــا‬\n      ‫يســندها مــن شــهادة شــهود أو قبــض املدعــى عليــه وهــو يف حالــة تنبــئ‬\n      ‫بالترويــج أو العثــور علــى احلبــوب وهــي يف وضــع مهيــأ للبيــع أو العثــور‬\n      ‫علــى مبالــغ نقديــة ملفتــة مــع املدعــى عليــه وملــا لــم يحصــل شــيء مــن ذلــك‬\n      ‫وألن األصــل بــراءة املتهــم حتــى تثبــت إدانتــه وملــا تضمنتــه املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة مــن أنــه ال يجــوز توقيــع‬\n      ‫عقوبــة جزائيــة علــى أي شــخص إال بعــد ثبــوت إدانتــه ‪ ،‬ممــا يــدل علــى‬\n\n\n‫‪191‬‬\n\f‫أنــه ال مســوغ للعقوبــة ملجــرد وجــود التهمــة ‪ ،‬و ملــا نصــت عليــه املــادة‬\n‫(‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة مــن أن احملكمــة ال تتقيــد‬\n‫بالوصــف الــوارد يف الئحــة الدعــوى و أن عليهــا أن تعطــي الفعــل الوصــف‬\n‫الــذي يســتحقه لهــذا كلــه وبعــد االطــاع علــى املــواد (‪ )56،41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة و ملــا قــرره جماهيــر أهــل‬\n‫العلــم مــن أن حــد شــرب املســكر ثمانــن جلــدة وهــو مــا انتهــى إليــه‬\n‫قــرار هيئــة كبــار العلمــاء باململكــة ذي الرقــم ‪ 53‬يف ‪1397/4/4‬ه ـ‬\n‫فقــد حكمــت باآلتــي ‪ :‬أو ًال ‪ :‬إدانــة املدعــى عليــه‪ ........‬بشــرب املســكر‬\n‫ومعاقبتــه علــى ذلــك بجلــده حــد شــرب املســكر ثمانــن جلــدة دفعــة‬\n‫واحــدة علن ـاً‪ .‬ثاني ـاً‪ :‬إدانــة املدعــى عليــه‪ ........‬بتعاطــي احلبــوب املنبهــة‬\n‫احملظــورة وحيــازة (‪ )150‬مئــة وخمســن حبــة مــن حبــوب اإلمفيتامــن‬\n‫احملظــورة بقصــد التعاطــي ومعاقبتــه علــى ذلــك بســجنه ســتة أشــهر‬\n‫وجلــده ســتني جلــدة دفعــة واحــدة ومنعــه مــن الســفر خــارج اململكــة مــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن‪ .‬ثالثـاً‪ :‬إدانــة املدعــى عليــه‬\n‫‪ ........‬بشــرب املســكر وحيازة قارورة مســكر بقصد الشــرب ومعاقبته‬\n‫علــى ذلــك بجلــده حــد شــرب املســكر ثمانــن جلــدة دفعــة واحــدة علنـ ًا‬\n‫و وســجنه أربعــة وعشــرين ســاعة حتتســب مــن مــدة إيقافــه تعزيــر ًا علــى‬\n‫احليــازة‪ .‬رابع ـاً‪ :‬بــراءة املدعــى عليــه ‪:‬مــن تهمــة محاولــة مقاومــة رجــال‬\n‫األمــن وبــراءة املدعــى عليــه مــن تهمــة حيــازة حبــوب اإلمفيتامــن‬\n‫احملظــورة بقصــد الترويــج لعــدم كفايــة األدلــة وبإعــان احلكــم قنــع بــه‬\n‫املدعــى عليهــم وقــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة‬\n‫حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n\n\n                                                                                          ‫‪192‬‬\n\f      ‫الســبت املوافــق ‪1434/07/15‬ه ـ حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫وبرفقهــا القــرار رقــم‪ 34252410‬يف‪1434/6/26‬ه ـ واملتضمــن‪ :‬لوحــظ‬\n      ‫أوالً‪ :‬أن املدعــى عليــه ‪ ........‬لديــه حيــازة مائــة وخمســن حبــة مــن حبــوب‬\n      ‫الكبتاجــون ومــا حكــم بــه فضيلتــه لقــاء ذلــك قليــل لكثــرة الكميــة‪.‬‬\n      ‫ثاني ـاً‪ :‬ورد ثالث ـ ًا يف احلكــم إدانــة املدعــى عليــه ‪ ........‬ولعــل صحتهــا‬\n      ‫التعديــل ذلــك يف موقعــة يف الضبــط والقــرار أ‪.‬ه ـ واســتجابة ملــا ذكــره‬\n      ‫أصحــاب الفضيلــة فقــد رجعــت عمــا حكمــت بــه يف الفقــرة ثاني ـ ًا مــن‬\n      ‫عقوبــة الســجن بحــق املدعــى عليــه وحكمــت بســجنه ســبعة أشــهر مــع‬\n      ‫بقــاء عقوبتــي اجللــد واملنــع مــن الســفر كمــا هــي‪ ،‬كمــا روعــي مــا جــاء‬\n      ‫يف املالحظــة الثانيــة وبإعــان احلكــم قنــع بــه املدعــى عليه وقــرر املدعي‬\n      ‫العــام أنــه ال يــزال علــى اعتراضــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫آله وصحبه وسلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/09/22‬ه ـ‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار رقــم ‪ 34288189‬يف‬\n      ‫‪1434/8/6‬ه ـ املتضمــن لوحــظ اوال‪ :‬ان مــا حكــم بــه فضيلتــه لقــاء‬\n      ‫احليــازة ال يــزال قليــل جــدا ثانيــا‪ :‬املالحظــة الثانيــة لــم يتــم التصحيــح‬\n      ‫كمــا اشــار فضيلتــه يف صــورة الضبــط أ‪.‬هــ‪ .‬واســتجابة ملــا ذكــره‬\n      ‫أصحــاب الفضيلــة يف املالحظــة األولــى فقــد رجعــت عمــا حكمــت‬\n      ‫بــه يف الفقــرة ثاني ـ ًا مــن عقوبــة الســجن بحــق املدعــى عليــه وحكمــت‬\n      ‫بســجنه عشــرة أشــهر مــع بقــاء عقوبتــي اجللــد واملنــع مــن الســفر كمــا‬\n      ‫هــي‪ ،‬كمــا روعــي مــا جــاء يف املالحظــة الثانيــة وبإعــان احلكــم قــرر‬\n\n\n‫‪193‬‬\n\f‫املدعــى عليــه اعتراضــه وطلــب رفــع املعاملــة دون تقــدمي الئحــة اعتراضية‬\n‫كمــا قــرر املدعــي العــام أنــه ال يــزال علــى اعتراضــه ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد‬\n‫فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف فقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫رقــم ‪ 35112419‬يف ‪1435/1/11‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n                                        ‫وللبيــان أحلــق يف ‪1435/1/18‬هــ‪.‬‬\n\n\n\n\n                                                                                 ‫‪194‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":182,"source_page_end":194,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1d6a28ee0733120ff017be3d200db5bda841566e726f99c2f01fba1b8e29c3ad","normalized_text_hash":"cf1786215cb5e3b13091145277f074ff16483da65e38f67f0e4f7fae1a3e2cbb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p182-342030072"},{"id":"12811dde-df4c-5738-82ff-30cbe841f8aa","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -قيادة السيارة حتت تأثير املخدر -مقاومة رجال األمن والهروب منهم -إدانة -تطبيق حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر .","document_number":"34252576","case_number":"3481135","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -قيادة السيارة حتت تأثير املخدر -مقاومة رجال األمن والهروب منهم -إدانة -تطبيق حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34252576 :‬تاريخه‪1434/06/26 :‬هـ‬\n                            ‫رقم الدعوى‪3481135:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34272982‬تاريخه‪1435/07/18:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬قيــادة الســيارة‬\n       ‫حتــت تأثيــر املخــدر ‪ -‬مقاومــة رجــال األمــن والهــروب منهــم ‪ -‬إدانــة‬\n       ‫‪ -‬تطبيــق حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن‬\n                                                     ‫واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول رســول اهلل صلــى اهلل عليــه وســلم‪( :‬كل مســكر خمــر وكل‬\n                                                                        ‫خمــر حــرام)‪.‬‬\n       ‫‪ -2‬جــاء يف مجمــوع الفتــاوى( ‪« :)358/23‬الــذي عليــه جمهــور األئمــة‬\n                     ‫أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا يحــد»‪.‬‬\n                                       ‫‪ -3‬اإلقرار حجة على صاحبه ومؤاخذ به‪.‬‬\n       ‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                          ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه وقيادتــه الســيارة‬\n       ‫حتــت تأثيــره ومقاومتــه لرجــال األمــن وهروبــه مــن الفرقــة القابضــة‪،‬‬\n       ‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحة‬\n\n‫‪195‬‬\n\f‫املخــدرات واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبته لقاء قيادة الســيارة‬\n‫حتــت تأثيــر املخــدر تقــرر مــن اجلهــة املختصــة واحلكــم عليــه بعقوبــة‬\n‫تعزيريــة لقــاء باقــي التهــم‪ ،‬حيــث إنــه مت اســتيقاف املدعــى عليــه بعــد‬\n‫مالحظتــه يخفــي شــيئ ًا حتــت مقعــد الســائق فعثــر علــى عقــب ســيجارة‬\n‫مخلــوط باحلشــيش املخــدر وبتفتيشــه شــخصيا عثــر علــى قطعــة مــن‬\n‫ا فتمــت الســيطرة عليــه‬    ‫احلشــيش املخــدر بعدهــا قــام بالهــرب مترج ـ ً‬\n‫وأثنــاء ذلــك قــام باالشــتباك مــع أفــراد الفرقــة ومقاومتهــم‪ ،‬وأثبــت‬\n‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة للحشــيش املخــدر‪ ،‬كمــا‬\n‫أقــر أمــام احملكمــة بتعاطــي احلشــيش وحيازة القطعــة املضبوطة بقصد‬\n‫التعاطي وبالهرب من الفرقة القابضة وأنكر حيازة ســيجارة احلشــيش‬\n‫والتعاطــي منهــا ‪ ،‬مــن املقــرر شــرع ًا أن اإلقــرار حجــة علــى صاحبــه‬\n‫ومؤاخــذ بــه والقرائــن القويــة ال تتــرك مجــاال لعــدم إثبــات إدانتــه بحيــازة‬\n‫ســيجارة احلشــيش لقصــد التعاطــي باإلضافــة إلــى شــهادة الشــهود التــي‬\n‫أكــدت اإلدانــة مبــا هــو مدعــى عليــه بــه‪ ،‬وحيــث إن املدعــى عليــه مــن‬\n‫أربــاب الســوابق‪ ،‬فقضــت احملكمــة بجلــده حــد املســكر ثمانــن جلــدة‬\n‫دفعــة واحــدة وســجنه ملــدة اثنــي عشــر شــهر ًا ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني كمــا قــررت تعزيــره لقــاء باقــي التهــم بســجنه‬\n‫ســبعة أشــهر وجلــده ثالثــن جلــدة تكــرر عليــه ثــاث مــرات وأفهمــت‬\n‫املدعــى عليــه بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر املخــدر تقــرر‬\n‫مــن اجلهــة املختصــة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n             ‫عليــه وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                       ‫‪196‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك بنــاء علــى قــرار النــدب الصــادر مــن املجلــس األعلــى للقضــاء‬\n      ‫برقــم ‪ 34/3863‬وتاريــخ ‪ 1434 / 3 / 8‬ه ـ ـ وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبوك‪/‬املكلــف برقــم‬\n      ‫‪ 3481135‬وتاريــخ ‪ 1434/02/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 34409273‬وتاريــخ ‪ 1434/02/18‬ه ـ ففــي يــوم االثنــن املوافــق‬\n      ‫‪ 1434/03/23‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا‬\n      ‫حضــر املدعــي العــام ‪ ........‬املكلــف باالدعــاء العــام مــن قبــل فــرع هيئــة‬\n      ‫التحقيــق واالدعــاء العــام مبنطقــة تبــوك مبوجــب اخلطــاب رقــم ‪........‬‬\n      ‫بتاريــخ ‪ 1433 / 9/ 5‬هـ ـ وحضــر حلضــوره املدعــى عليــه ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬فادعــى قائــا يف حتريــر‬\n      ‫دعــواه‪ :‬أنــه بتاريــخ ‪1434/01/ 8‬ه ـ توافــرت معلومــات لديهــم مــن أحــد‬\n      ‫املصــادر الســرية عــن املدعــى عليــه أنــه يحتــاز علــى مواد مخدرة ويســتقل‬\n      ‫ســيارة مــن نــوع (‪ ).....‬حتمــل لوحــة رقــم (‪ )............‬ومت مشــاهدته بجــوار‬\n      ‫محطــة (‪ )........‬علــى طريــق عمــان وبتوجــه الدوريــة الرســمية اتضــح أن‬\n      ‫الشــخص الــذي بداخــل الســيارة هــو املدعى عليه ولوحــظ عليه االرتباك‬\n      ‫ونــزل مــن الســيارة وقــام بإخفــاء شــيء مــا حتــت مقعــد الســائق وبالتقــاط‬\n      ‫مــا قــام برميــه اتضــح أنــه عبــارة عــن عقــب ســيجارة يشــتبه أن يكــون‬\n      ‫مخلــوط باحلشــيش املخــدر بلــغ وزنه (‪ )420‬أربعمائة وعشــرين مليجرام ًا‬\n      ‫وبطلــب الهويــة الوطنيــة ذكــر أنــه ال يحملهــا وذكــر أنــه وبتفتيشــه‬\n      ‫شــخصيا عثــر بداخــل جيــب جاكيتــه علــى قطعــة صغيــره يشــتبه أن‬\n\n‫‪197‬‬\n\f‫تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ 30‬ملــج) ثالثــن مليجرام ـ ًا‬\n‫بعدهــا أبــدى املذكــور النــدم واســتعد بالتعــاون للقبــض علــى أحــد‬\n‫ا‬ ‫مروجــي املخــدرات وأثنــاء حديثــه بالهاتــف النقــال قــام بالهــرب مترجـ ً‬\n‫ومت مالحقتــه مــن قبــل الفرقــة وبعــد حوالــي مائــة متــر مــن موقــع القبــض‬\n‫مت الســيطرة عليــه وأثنــاء ذلــك قــام باالشــتباك مــع أفــراد الفرقــة‬\n‫ومقاومتهــم بدفعهــم باأليــدي ونتــج عنهــا إصابــة الفــرد رقــم (‪ )........‬ومت‬\n‫نقلــه للمستشــفى فتــم إحالــة املذكــور ملقــر إدارة مكافحــة املخــدرات‬\n‫بتبــوك جــرى ضبــط إفــادة أفــراد الفرقــة القابضــة الســتيضاح بعــض‬\n‫النقــاط الــواردة يف احملضــر املعــد مــن قبلهــم وأفــادوا أن املذكــور‬\n‫شــاهده الفــرد ‪ ........‬و ‪ .........‬رقيــب رقــم (‪ .)........‬وهــو يقــوم بإطفــاء‬\n‫الســيجارة ورميهــا حتــت مقعــد الســائق وكان يتعاطــى منهــا قبــل‬\n‫القبــض عليــه ورائحتهــا متــأ املركبــة ‪ ،‬وأن ســبب هروبــه هــو ادعــاؤه‬\n‫التعــاون معهــم لكــن غافــل الفرقــة وقــام بالهــرب جــرى إيقــاف املدعــى‬\n‫عليــه اســتناد ًا للفقــرة (‪ )11‬مــن القــرار الــوزاري رقم (‪ ، )1900‬واســتناد ًا‬\n‫لتعميــم وزيــر الداخليــة رقــم (‪ )45781‬وتاريــخ ‪1431/7/22‬ه ـ لوجــود‬\n‫ســابقة مخــدرات وباســتجواب املدعــى عليــه ‪ /‬أقــر بأنــه قــام بالهــرب مــن‬\n‫الفرقــة القابضــة وذلــك بعــد محادثتــه لوالدتــه‪ .‬صــدر بحــق رجــل األمــن‬\n‫اجلنــدي رقــم (‪ )........‬التقريــر الطبــي النهائــي الصــادر مــن مستشــفى ‪.....‬‬\n‫بتبــوك املتضمــن (ادعــاء مضاربــة ‪ ،‬وجــود ســحجات علــى اليــد اليمنــى‬\n‫و القــدم اليمنــى واليســرى والركبــة اليســرى وباجلانــب األميــن يف البطــن‬\n‫‪ ،‬واألداة املســتخدمة صلبــة غيــر حــادة ‪ ،‬ومــدة الشــفاء أربعــة أيــام مــا لــم‬\n‫حتــدث مضاعفــات)‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‬\n‫‪ )........‬الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n\n\n                                                                                       ‫‪198‬‬\n\f      ‫الشــرعية بصحــة تبــوك إيجابيــة مســتخلص العينــة لعقــب ســيجارة‬\n      ‫للحشــيش املخــدر ‪ ،‬وايجابيــة العينــة للحشــيش املخــدر كمــا أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم ‪ ........‬الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بصحــة تبــوك ‪ ،‬إيجابيــة عينــة‬\n      ‫الــدم للمتهــم أليــض املــادة الفعالــة للحشــيش املخــدر وهــو مــن املــواد‬\n      ‫احملظــورة اخلاضعــة للرقابــة واملنــوه عنهــا باجلــداول امللحقــة بالنظــام يف‬\n      ‫تعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء‬\n      ‫وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريــخ ‪1426/10/25‬ه ـ وقــد أســفر‬\n      ‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بحيــازة عقــب ســيجارة‬\n      ‫مخلــوط باحلشــيش املخــدر بلــغ وزنهــا (‪ )420‬أربعمائــة وعشــرون جرامـ ًا‬\n      ‫وقطعــة مــن احلشــيش املخــدر بلــغ وزنهمــا اإلجمالــي (‪ )30‬ثالثــون‬\n      ‫مليجــرام بقصــد التعاطــي ‪ ،‬وتعاطيــه مــن ذات الكميــة ‪،‬ولنوعهــا يف‬\n      ‫الســابق ‪ ،‬ومقاومتــه رجــال األمــن أثنــاء تأديــة مهــام وظيفتهــم ‪ ،‬وهروبــه‬\n      ‫مــن الفرقــة القابضــة ‪ ،‬وقيادتــه للســيارة حتــت تأثيــر املخــدر وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -.1 :‬اعترافــه بالهــرب مــن الفرقــة القابضــة ‪،‬‬\n      ‫املنــوه عنــه‪ -‬املرفقــة برقــم( ‪ - 2 )16-15-14‬مــا ورد مبحضــر البــاغ‬\n      ‫والقبــض والتفتيــش املرفــق بالصفحــة رقــم(‪ )1‬مــن ملــف االســتدالل‬\n      ‫املرفــق برقــم(‪ -3 )1‬مــا ورد يف محضــر االســتيضاح الــوارد علــى محضــر‬\n      ‫القبــض ‪ -‬املنــوه‪ -‬عنــه املرفــق لفة رقم (‪ -4 )19‬التقريرين الكيميائيني‬\n      ‫الشــرعيني املرفقــن لفــة رقــم(‪ -5 .)31-30‬التقريــر الطبــي النهائــي‬\n      ‫الصــادر بحــق رجــل األمــن املرفــق لفــة رقــم (‪ )20‬وحيــث أن مــا أقــدم‬\n      ‫عليــه املذكــور فعــل محــرم شــرع ًا ومجــرم ومعاقــب عليــه نظام ـ ًا ‪،‬‬\n      ‫اســتناد ًا للفقــرة (الثانيــة) مــن املــادة( الثالثــة) مــن نظــام مكافحــة‬\n\n\n‫‪199‬‬\n\f‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم ( م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلب‪-1:‬إثبــات مــا أســند إليه‪-2.‬احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء مقاومتــه رجــال األمــن وهروبــه مــن الفرقــة‬\n‫القابضة‪-3.‬احلكــم عليــه بالســجن‪ ،‬لقــاء مــا أســند إليــه اســتناد ًا للفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليه‪-4.‬احلكــم عليــه مبنعــه مــن الســفر خارج اململكة ‪ ،‬اســتناد ًا‬\n‫للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املشــار إليــه أعــاه‪ -5.‬تشــديد العقوبــة بحقــه ‪ ،‬اســتناد ًا لتعميــم‬\n‫وزيــر الداخليــة رقــم (‪ )36717/2/5/1‬وتاريخ ‪1431/6/11‬هـ العتدائه‬\n‫علــى رجــل أمــن أثنــاء تأديــة عملــه‪ -6.‬إفهــام املذكــور بــأن عقوبتــه لقــاء‬\n‫قيادتــه الســيارة حتــت تأثيــر املســكر عائــد للجهــة املختصــة هــذه‬\n‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح كلــه جملــة وتفصيــا‬\n‫هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــك بينــه علــى دعــواك‬\n‫اجــاب بقولــه نعــم لــدي واطلــب مهلــة إلحضارهــا هكــذا أجــاب ويف‬\n‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام‬\n‫عــن البينــة التــي وعــد بإحضارهــا أجــاب بقولــه لقــد أحضــرت للشــهادة‬\n‫أطلــب ســماع مــا لديــه هكــذا أجــاب ويف هــذه اجللســة حضــر ‪........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬واملولــود عــام‬\n‫‪1405‬هـ ـ ويعمــل لــدى إدارة مكافحــة املخــدرات مبنطقــة تبــوك وليــس‬\n‫بينــه وبــن املدعــى عليــه أي عالقــة كمــا أفــاد وبســؤاله عمــا لديــه مــن‬\n‫شــهادة أجــاب بقولــه أشــهد هلل تعالــى أنــه جــاءت لــإدارة إخباريــة عــن‬\n‫وجــود ســيارة لونهــا أبيــض وأنــه يوجــد بهــا شــخص يحــوز مــواد مخــدرة‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫ومتجــه إلــى طريــق عمــان وحيــث أنــي كنــت ضمــن الفرقــة القابضــة‬\n      ‫املكلفــة يف امليــدان جاءنــا البــاغ عنهــا فتوجهنــا لطريــق ‪ ........‬فوجدنــا‬\n      ‫الســيارة متوقفــة يف محطــة ‪........‬ويقــوم ســائقها بتعبئــة الســيارة بالوقــود‬\n      ‫طبعــا البــاغ يأتــي بلــون الســيارة ونوعهــا ورقــم لوحتهــا والــذي يتلقــى‬\n      ‫البــاغ رئيــس الفرقــة كذلــك لــم أعــرف نــوع الســيارة ألنــه ليــس لــدي‬\n      ‫معرفــة باألنــواع اجلديــدة مــن الســيارات وعنــد توقفــه لتعبئــة الوقــود‬\n      ‫ذهبــت أنــا والرقيــب ‪ .....‬للســيارة وعنــد اقترابنــا منــه قــام بإخفــاء شــيء‬\n      ‫حتــت مقعــده الــذي يجلــس عليــه وقــد رأيــت ذلــك ألننــي أتيــت مــن جهــة‬\n      ‫الراكــب ثــم أتينــا لــه مــن جهــة بــاب الســائق وطلبنــا منــه النــزول فنــزل‬\n      ‫وقــام زميلــي الرقيــب ‪........‬بإخــراج مــا قــام بإخفائــه حتت مقعــده فوجدنا‬\n      ‫أنــه عقــب ســيجارة ويشــتبه أنهــا مخلوطــة باحلشــيش وهــي ســيجارة‬\n      ‫ملفوفــة بــورق اللــف املســتخدم يف تعاطــي احلشــيش وقــام أحــد الزمــاء‬\n      ‫من الدورية األخرى بتفتيشــه تفتيشــا شــخصيا وعثر يف جيب اجلاكيت‬\n      ‫علــى قطعــة ســوداء صغيــرة يشــتبه أنهــا مــن احلشــيش وعندمــا اجتمــع‬\n      ‫النــاس قمنــا بأخــذه لــإدارة وعندمــا كنــا يف احلــوش التابــع لــإدارة قــال‬\n      ‫إن جميــع مــا ضبــط معــي عائــد لــي وأنــا نــادم علــى مــا فعلــت وأريــد أن‬\n      ‫أتعــاون معكــم لإلطاحــة بأحــد املروجــن وقمنــا بفــك القيــود عنــه‬\n      ‫وطلــب منــا أن يواعــد املــروج داخــل حــي ‪........‬لكننــا رفضنــا وطلبنــا منــه‬\n      ‫أن يواعــده عنــد مــكان عــام كأن يكــون بجانــب محطــة أو مــا شــابه‬\n      ‫ذلــك فقــام باالتصــال وأثنــاء اتصالــه اســتغفلنا وهــرب وقمنــا باللحــاق بــه‬\n      ‫وهــرب ملســافة بعيــدة ونحــن جنــري خلفــه وحلــق بــه زميلنــا ‪ .....‬وقــام‬\n      ‫املدعــى عليــه بالتشــابك معــه باأليــدي وعلــى أثــر ذلك حصلــت اإلصابات‬\n      ‫بزميلــي ‪ ........‬واســتطعنا بعــد ذلــك القبــض عليــه وإيداعــه التوقيــف‬\n\n\n‫‪201‬‬\n\f‫هكــذا أشــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه أجــاب‬\n‫بقولــه الشــاهد ال أعرفــه وال أقــدح فيــه ومــا ذكــره مــن أنهــم عثــروا علــى‬\n‫عقــب ســيجارة مخلوطــة باحلشــيش حتــت مقعــد الســائق الــذي أجلــس‬\n‫عليــه صحيــح لكنهــا ليســت لــي ألن الســيارة مــن مكتــب تأجيــر ومــا‬\n‫ذكــره مــن أنهــم عثــروا علــى قطعــة ســوداء داخــل اجلاكيــت فصحيــح‬\n‫أيضــا واجلاكيــت يعــود لــي وال أعلــم هــل هــي حشــيش أم ال واجلاكيــت‬\n‫لــه ثــاث ســنوات عنــدي وصحيــح أننــي هربــت منهــم عنــد اإلدارة وقامــوا‬\n‫باللحــاق بــي ولــم أتشــابك باأليــدي مــع العســكري الــذي حلــق بــي بــل هــو‬\n‫مســكني وســقط علــي ولــم أقــم مبقاومتــه هكــذا أجــاب وبســؤال‬\n‫املدعــي العــام هــل لديــك مزيــد بينــة أجــاب بقولــه نعــم أطلــب مهلــة ثانيــة‬\n‫إلحضارهــا هكــذا أجــاب وبســؤاله عــن املعدلــن للشــاهد أســتعد‬\n‫بإحضارهــم يف اجللســة القادمــة ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة التــي وعــد بهــا أجــاب‬\n‫بقولــه أحضــرت للشــهادة أطلــب ســماع مــا لديــه هكــذا أجــاب ويف هــذه‬\n‫اجللســة حضــر الشــاهد ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم ‪ ........‬واملولــود عــام ‪ 1408‬هـ ـ ويســكن حــي ‪ .......‬بتبــوك ويعمــل‬\n‫لــدى إدارة مكافحــة املخــدرات مبنطقــة تبــوك وليــس بينــه وبــن املدعــى‬\n‫عليــه أي عالقــة كمــا أفــاد وبســؤاله عمــا لديــه من شــهادة أجــاب بقوله‪:‬‬\n‫أشــهد هلل تعالــى أننــا قبضنــا علــى املدعــى عليــه يف محطــة علــى طريــق‬\n‫‪ ........‬وكان بحوزتــه مؤثــرات عقليــة ال أعــرف مــا هــي لكونــي لــم‬\n‫أشــاهدها وكان دوري هــو أخــذ املدعــى عليــه مــع بقيــه الفرقــة ملقــر‬\n‫اإلدارة وهنــاك يف احلــوش التابــع لــإدارة قــام املدعــى عليــه بالبــكاء‬\n‫ويقــول أنــه نــادم علــى مــا فعــل وتائــب هلل وأن والدتــه مريضــة ويطلــب أن‬\n\n\n                                                                                        ‫‪202‬‬\n\f      ‫يكــون متعاونــا معنــا لإلطاحــة باملروجــن وبنــاء علــى ذلــك جــرى فــك‬\n      ‫قيــوده وقــال لنــا أنــا مســتعد لإلطاحــة باملــروج والــذي يســكن حــي ‪........‬‬\n      ‫وطلــب أن يذهــب معــه أحــد أعضــاء الفرقــة فرفضنــا لكــون املــكان‬\n      ‫داخــل اإلحيــاء وهــذا قــد يعرضنــا للخطــر فطلبنــا منــه أن يواعــده خــارج‬\n      ‫احلــي عنــد مــكان عــام إمــا محطــة أو أنــه يف شــارع رئيســي واســتغفلنا‬\n      ‫وهــو يكلــم باجلــوال وهــرب وحلقتــه أنــا ومســكته عنــد شــارع ‪........‬‬\n      ‫وكان يقاومنــي كل مــا حاولــت اإلمســاك بــه حتــى أمســكته فتشــابك‬\n      ‫معــي باأليــدي ليفلــت منــي لكنــي متكنــت مــن اإلمســاك بــه وحصلــت‬\n      ‫بــي إصابــة عنــد محاولــة اإلمســاك بــه حيــث ســقطت علــى االزفلــت‬\n      ‫وحصــل بــي كشــط يف يــدي والســقوط كان منــي أنــا ولــم يقــم هــو‬\n      ‫بدفعــي هــذا مــا لــدي هكــذا شــهد وبعــرض الشــاهد وشــهادته علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه الشــاهد ال أعرفــه وال أقــدح فيــه ومــا ذكــره‬\n      ‫أنــه ضبــط معــي مؤثــرات عقليــة فقــد أجبــت عــن صحــة ذلــك يف جوابــي‬\n      ‫علــى شــهادة الشــاهد األول ولكنهــا ليســت لــي والســيارة باســم وهــو‬\n      ‫جــاري يف ‪........‬أخذتهــا منــه ألقــوم بإيصــال أهلــي حلــي ‪........‬وضبطــت يف‬\n      ‫الســيارة عقــب ســيجارة ذكــروا أنهــا مخلوطــة باحلشــيش كمــا عثــروا‬\n      ‫يف جيــب اجلاكيــت علــى قطعــة صغيــرة و فعــا هــذه القطعــة الصغيــرة‬\n      ‫عائــدة لــي بقصــد التعاطــي وصحيــح أننــي هربــت منهــم وأمســك بــي‬\n      ‫هــذا الشــاهد ولكنــي لــم أتشــابك معــه يف األيــدي وهــم مــن قالــوا لــي‬\n      ‫نريــد أن تطيــح لنــا بــ‪ ........‬ألنهــم وجــدوا أن الســيارة مســجلة باســمه‬\n      ‫والــذي أعرفــه أنــه شــخص ليــس لــه يف هــذه األمــور ولــم أقتــرح عليهــم أن‬\n      ‫أتعــاون معهــم لإلطاحــة باملروجــن ولــم يحصــل منــي بــكاء أو أنــي قلــت‬\n      ‫لهــم نــادم وإمنــا قلــت لهــم فكونــي وأن الســيارة ليســت لــي وصحيــح أننــي‬\n\n\n‫‪203‬‬\n\f‫كنــت أتعاطــى احلشــيش املخــدر يف الســابق ولــم أتعاطــى ممــا ضبــط‬\n‫بحوزتــي ألنــي تركــت تعاطــي احلشــيش منــذ زمــن هكــذا أجــاب‬\n‫وبســؤال املدعــي العــام هــل لديــك مزيــد بينــة أجــاب بقولــه ليــس لــدي‬\n‫ســوى مــا قدمــت هكــذا أجــاب وبســؤاله عــن املعدلــن لبينتــه أجــاب‬\n‫بقولــه أن الشــاهد أفادنــي بأنهــم ال يســتطيعون احلضــور لهــذا اليــوم‬\n‫لكونهــم يف مهمــة ميدانيــة وأطلــب مهلــة أخيــرة إلحضــار املعدلــن‬\n‫للبينــة هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبســؤال املدعــي العــام عــن املعدلــن للبينــه أجــاب بقولــه أحضــرت‬\n‫ألجــل ذلــك كال مــن ‪........‬ســعودي مبوجــب الهويــة الوطنيــة رقــم ‪........‬‬\n‫و‪ ........‬ســعودي مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬أطلــب ســماع مــا‬\n‫لديهــم هكــذا أجــاب وحضــر يف هــذه اجللســة و املبينــة بياناتهمــا بعاليــه‬\n‫والتــي تأكــدت منهــا وبســؤالهما عــن عدالــة الشــاهدين أجابــا بقولهمــا‬\n‫أنهمــا زمــاء يف العمــل وهمــا أهــل ثقــة وعدالــة هكــذا أجابــا فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أقــر بــه املدعــى عليــه مــن حيازتــه‬\n‫لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا اإلجمالــي ( ‪ ) 30‬ثالثــن‬\n‫مليجرامــا بقصــد التعاطــي كمــا أقــر باســتخدامه للحشــيش املخــدر‬\n‫وحيــث إن اإلقــرار حجــة علــى صاحبــه ومؤاخــذ بــه وحيــث أنكــر‬\n‫حيازتــه عقــب ســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا ( ‪) 420‬‬\n‫أربعمائــة وعشــرين مليجرام ـ ًا وحيــث أقــر بوجودهــا بالســيارة وأقــام‬\n‫املدعــي العــام البينــة علــى وجودهــا بالســيارة التــي كان يركبهــا إال أنــه‬\n‫لــم يــأت بهــذه البينــة أنــه قــام برميهــا حتــت مقعدتــه إال مــا جــاء يف شــهادة‬\n‫أنــه رأى املدعــى عليــه وهــو يرمــي بشــيء حتــت مقعده وأنه عنــد التفتيش‬\n‫حتــت مقعــده وجــدوا عقــب الســيجارة وأنــه أقــر لديهــم بــأن مــا ضبــط‬\n\n\n                                                                                           ‫‪204‬‬\n\f      ‫كان لــه وهــذه قرينــة قويــة جــدا ويقويهــا مــا شــهد بــه مــن بــكاءه وندمــه‬\n      ‫وإبــداءه الرغبــة بالتعــاون معهــم يف اإلطاحــة باملروجــن كمــا يقويهــا‬\n      ‫هروبــه مــن رجــال األمــن بــل إن مــن أقــوى القرائــن التحليــل الــذي عمــل‬\n      ‫لعينــة مــن البــول للمدعــى عليــه وثبــت إيجابيتهــا أليــض املــادة الفاعلــة‬\n      ‫للحشــيش املخــدر واملرصــود علــى اللفــة (‪ )28‬مــن لفــات املعاملــة كمــا‬\n      ‫أنــه يزيــد مــن قوتهــا ذكــره أن الســيارة وعنــد هيئــة التحقيــق كمــا يف‬\n      ‫اللفــة (‪ )15‬مــن املعاملــة ذكــر أن الســيارة باســم ‪........‬ومجمــوع هــذه‬\n      ‫القرائــن مــع مــا عليــه مــن ســابقة مــن جنــس هــذه الدعوى وإقــراره بحيازة‬\n      ‫نوعهــا وتعاطيــه لنوعهــا كل ذلــك ال يتــرك مجــاال لعــدم إثبــات إدانتــه‬\n      ‫بحيــازة عقــب الســيجارة املوصوفــة بعاليــه بقصــد التعاطــي ألن هــذه‬\n      ‫الكميــة القليلــة وكونهــا عقــب ســيجارة دل علــى أن حيازتهــا للتعاطــي‬\n      ‫ليــس إال ويــدل عليــه أيضــا التحليــل الــذي أشــير إليــه بعاليــه ممــا يــدل‬\n      ‫علــى قيادتــه أيضــا للســيارة حتــت تأثيــر املخــدر وملــا روى ابــن عمــر رضــي‬\n      ‫اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم قــال (كل مســكر‬\n      ‫خمــر وكل خمــر حــرام) قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف‬\n      ‫احلشيشــة (الــذي عليــه جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل‬\n      ‫ـاء علــى‬‫الصــواب أن آكلهــا يحــد) مجمــوع الفتــاوى ‪ 358/23‬وبنـ ً‬\n      ‫املــادة(‪ )41‬الفقــرة (‪ )1‬واملــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة و لوجــود ســابقة مخــدرات علــى املدعــى‬\n      ‫عليــه بتاريــخ ‪ 1433 / 4 / 6‬هـ ـ كمــا هــو مرصــود بــأوراق املعاملــة وهــذا‬\n      ‫ممــا يوجــب التشــديد عليــه يف العقوبــة وألن هروبــه مــن رجــال األمــن فيــه‬\n      ‫تأمــن الســبل وحتفــظ احلقــوق‬  ‫متــرد علــى قــوة الســلطان وهيبتــه التــي بهــا ّ‬\n      ‫ويعــم االســتقرار وألن مــن هيبــة الســلطان هيبــة نوابه وعســكره فهروبه‬\n\n\n‫‪205‬‬\n\f‫هــذا يســتحق بــه التعزيــر ردعــا لــه وزجــرا لغيــره مــن التجــرؤ علــى رجــال‬\n‫ـدي إدانــة‬\n         ‫األمــن بعــدم االنصيــاع لهــم والهــروب منهــم لــذا فقــد ثبــت لـ َّ‬\n‫املدعــى عليــه بحيازتــه قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا اإلجمالــي‬\n‫( ‪ ) 30‬ثالثــون مليجــرام وحيازتــه لعقــب ســيجارة مخلوطــة باحلشــيش‬\n‫املخــدر بلــغ وزنهــا ( ‪ ) 420‬أربعمائــة وعشــرون جرام ـ ًا بقصــد التعاطــي‬\n‫وتعاطيــه للحشــيش املخــدر كمــا ثبــت لــدي إدانتــه مبقاومتــه لرجــال‬\n‫األمــن وهروبــه منهــم وقيادتــه للســيارة حتــت تأثيــر املخــدر وقــررت مايلي‬\n‫أوال‪ :‬جلــد املدعــى عليــه احلــد ثمانــن جلــدة دفعــة واحــدة لقــاء تعاطــي‬\n‫احلشــيش املخــدر ثانيــا‪ :‬تعزيــر املدعــى عليــه بســجنه مــدة اثنــي عشــر‬\n‫شــهرا يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة لقــاء حيازتــه‬\n‫ملــا أشــير إليــه بعاليــه مــن احلشــيش املخــدر ثالثــا‪ :‬منــع املدعــى عليــه مــن‬\n‫الســفر خــارج اململكــة مــدة ســنتني رابعــا‪ :‬تعزيــر املدعــى عليــه بســجنه‬\n‫ســبعة أشــهر تبــدأ بعــد ماحكــم بــه ثانيــا لقــاء مقاومتــه لرجــال األمــن‬\n‫وهروبــه منهــم خامســا‪ :‬تعزيــر املدعــى عليــه بجلــده ثالثني جلــدة تتكرر‬\n‫عليــه ثــاث مــرات بــن كل إيقــاع واآلخــر خمســة عشــر يومــا لقــاء‬\n‫هروبــه مــن رجــال األمــن ومقاومتهــم وأفهمــت املدعــى عليــه بــأن عقوبتــه‬\n‫لقــاء مخالفتــه نظــام املــرور عائــد للجهــة املختصــة وبذلــك حكمــت‬\n‫وبعــرض حكمــي هــذا علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫باحلكــم وأمــا املدعــي العــام فقــد قــرر اعتراضــه مكتفيـ ًا مبــا جــاء يف‬\n‫أوراق املعاملــة عــن تقــدمي الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                   ‫على نبينا و آله وصحبه وسلم‪ .‬حرر يف ‪ 1434/06/20‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة‬\n‫يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة مــن‬\n\n\n                                                                                          ‫‪206‬‬\n\f      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪ 34409273‬وتاريــخ‬\n      ‫‪1434/07/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫يف احملكمــة الشــيخ ‪ ....‬برقــم ‪ 34252576‬وتاريــخ ‪1434/06/26‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد املدعــي يف قضيــة مخــدرات‬\n      ‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬قررنــا املصادقــة علــى احلكــم‬\n      ‫مــع تنبيــه فضيلتــه علــى تعديــل وزن عقــب الســيجارة يف احلكــم إلــى‬\n      ‫مليجــرام بــد ًال مــن جــرام ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                             ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":195,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ba2c07b31084e20f27f0109d1f0d577addb5152454fa1992f87cac36043fc67","normalized_text_hash":"c59861343d1365f6e73cb97c4f9fe6e481683975f5aa73f3acc3782c566fd51e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p195-34252576"},{"id":"3515b73d-5b4d-502b-bb62-8e546e4f5847","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -قيادة السيارة حتت تأثيرها -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"34167139","case_number":"3483974","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/21","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -قيادة السيارة حتت تأثيرها -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34167139 :‬تاريخه‪1434/03/21 :‬هـ‬\n                       ‫رقم الدعوى‪3483974:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34254934‬تاريخه‪1434/6/28:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا ‪ -‬قيــادة‬\n  ‫الســيارة حتــت تأثيرهــا‪ -‬إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‬\n                            ‫‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n      ‫‪ -1‬قول اهلل تعالى‪ (( :‬وال تلقوا بأيديكم إلى التهلكة )) البقرة‪195:‬‬\n                                              ‫‪ -2‬اإلقرار حجة على املقر‪.‬‬\n                   ‫‪ -3‬املواد (‪ )128‬و (‪ )131‬من نظام اإلجراءات اجلزائية‪.‬‬\n  ‫‪ -4‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬واملــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام‬\n                                ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n        ‫‪ -5‬الفقرة (‪ )8‬من جدول املخالفات رقم (‪ )1‬امللحق بنظام املرور‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة حبــوب‬\n  ‫اإلمفيتامــن بقصــد التعاطــي وتعاطيــه لهــا وقيادتــه الســيارة حتــت‬\n  ‫تأثيرهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقـ ًا لنظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبتــه لقــاء‬\n  ‫القيــادة حتــت تأثيــر احلبــوب احملظــورة تقــرر مــن اجلهــة املختصة‪،‬وحيــث‬\n  ‫إنــه مت تفتيــش منــزل املدعــى عليــه بعــد ورود بــاغ مفاده أنــه يقوم بحيازة‬\n\n                                                                                       ‫‪208‬‬\n\f      ‫وتعاطــي املخــدرات داخــل املنــزل فعثــر فيــه علــى حبــوب اإلمفيتامــن‪،‬‬\n      ‫وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة‬\n      ‫لإلمفيتامــن‪ ،‬كمــا أقــر املدعــي العــام أمــام احملكمــة مبــا أســنده إليــه‬\n      ‫املدعــي العــام‪ ،‬وكمــا كان مــا تقــدم فــإن اإلقــرار حجــة علــى املقــر‪،‬‬\n      ‫وحيــث إن املدعــى عليــه أبــدى التوبــة وال يوجــد لــه ســوابق والكميــة‬\n      ‫احملــازة قليلــة‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب‬\n      ‫إليــه وقــررت جلــده ســتني جلــدة دفعــة واحــدة وســجنه مــدة ســتني يوم ـ ًا‬\n      ‫ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني وأفهمــت املدعــى عليــه‬\n      ‫بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة تقــرر‬\n      ‫مــن اجلهــة املختصــة‪ -‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                 ‫عليــه‪ -‬وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 3483974‬وتاريــخ‬\n      ‫‪1434/02/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34424915‬وتاريــخ‬\n      ‫‪1434/02/19‬ه ـ ففــي يــوم الســبت املوافق‪1434/03/21‬ه ـ حضــر‬\n      ‫املدعــي العــام كمــا حضــر املدعــى عليــه‪ ........ ،‬ســعودي رقــم ســجله‬\n      ‫املدنــي (‪ ).................‬وقــدم األول الئحــة دعــوى تتضمــن بــأن املدعــى‬\n      ‫عليــه البالــغ مــن العمــر (‪ )24‬ســنة غيــر محصــن ‪ ،‬موظــف أهلــي ‪،‬‬\n      ‫أوقــف بتاريــخ ‪1433/12/27‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/12/28‬هــ‪.‬‬\n      ‫وأنــه بتاريــخ ‪1433/12/25‬ه ـ تقــدم أحــد األشــخاص ببــاغ ملكافحــة‬\n      ‫املخــدرات مفــاده أن أخــاه يقــوم بحيــازة وتعاطــي املخــدرات داخــل‬\n\n‫‪209‬‬\n\f‫املنــزل وباالنتقــال إلــى املنــزل مت القبــض علــى املدعــى عليــه وبتفتيــش‬\n‫املنــزل عثــر علــى شــنطة تعــود للمدعــى عليــه بهــا إثباتــه ومحفظتــه‬\n‫وهواتفــه النقالــة وعثــر علــى عــدد (‪ )25‬خمســة وعشــرين حبــة أثبــت‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬لعــام ‪1433‬ه ـ الصــادر مــن‬\n‫املركــز االقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة العينــة‬\n‫املرســلة ملــادة اإلمفيتامــن‪ .‬وبســماع أقــوال املدعــى عليــه أقــر بحيازتــه‬\n‫للكميــة املضبوطــة مــن حبــوب الكبتاجــون وأنهــا تعــود لــه وغرضــه‬\n‫منهــا االســتخدام الشــخصي وأنــه يقــود الســيارة أثنــاء تعاطيــه احلبــوب‪.‬‬\n‫وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام إليــه بحيازتــه مــا عــدده‬\n‫(‪ )25‬خمســة وعشــرين حبــة مــن حبــوب اإلمفيتامــن بقصــد التعاطــي‬\n‫وتعاطيــه لهــا وقيادتــه الســيارة حتــت تأثيرهــا ‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫املوضحــة بالالئحــة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n‫علــى أي ســوابق جنائيــة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫ونظامــا لــذا أطلب‪-:‬إثبــات مــا أســند إليــه وفــق الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪ -1‬بعقوبــة الســجن وفــق الفقــرة (‪)1‬مــن املــادة (‪)41‬مــن النظــام‪2 .‬ـ منعــه‬\n‫مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املادة(‪)56‬مــن النظــام ‪-3‬إثبــات‬\n‫قيادتــه للســيارة حتــت تأثيــر احلبــوب احملظــورة وفقــا للفقــرة رقــم (‪)8‬‬\n‫مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة‬\n‫املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف‬\n‫‪1429/10/24‬هــ‪ .‬هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n\n\n                                                                                        ‫‪210‬‬\n\f      ‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ املذكــور‬     ‫قائ ـ ً‬\n      ‫وأنــه عثــر بحوزتــي علــى عــدده (‪ )25‬خمســة وعشــرين حبــة مــن حبــوب‬\n      ‫اإلمفيتامــن احملظــورة وأن قصــدي مــن حيازتهــا التعاطــي وأننــي‬\n      ‫أتعاطــى هــذه احلبــوب وقــدت الســيارة حتــت تأثيرهــا كل ذلــك صحيــح‬\n      ‫لكننــي تبــت عــن هــذا العمــل هكــذا أجــاب وبدراســة املعاملــة جــرى‬\n      ‫االطــاع علــى التقريــر الكيمــاوي وصحيفــة الســوابق املشــار لهمــا‬\n      ‫ـاء علــى مــا تقــدم وحيــث‬‫أعــاه فوجدتهــا كمــا ذكــر املدعــي العــام فبنـ ً‬\n      ‫تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى عليــه بتعاطــي حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة وقيــادة الســيارة حتــت تأثيرهــا وحيــازة‬\n      ‫(‪ )25‬خمســة وعشــرين حبــة مــن حبــوب اإلمفيتامــن بقصــد التعاطــي‬\n      ‫ويطلــب معاقبتــه علــى ذلــك وألن هــذه احملكمــة مختصــة بنظــر الدعــوى‬\n      ‫بنــاء علــى املــواد (‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار‬\n      ‫املدعــى عليــه وهــو بكامــل أهليتــه بجميــع مــا جــاء يف دعــوى املدعــي‬\n      ‫العــام وألن اإلقــرار حجــة علــى املقــر وألن مــا أقــدم عليــه أفعــال محرمــة‬\n      ‫شــرع ًا ملــا يف تعاطــي هــذه احلبــوب مــن أضــرار صحيــة بالغــة واهلل تعالــى‬\n      ‫يقــول (( وال تلقــوا بأيديكــم إلــى التهلكــة )) البقــرة‪ 195:‬كمــا أن‬\n      ‫حيــازة وتعاطــي احلبــوب املنبهــة احملظــورة مجــرم نظامـ ًا وفقـ ًا للفقــرة (‪)2‬‬\n      ‫مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات كمــا أن قيــادة الســيارة‬\n      ‫حتــت تأثيــر املؤثــرات العقليــة فعــل مجــرم نظام ـ ًا وفق ـ ًا للفقرة(‪)8‬مــن‬\n      ‫جــدول املخالفــات رقــم (‪)1‬امللحــق بنظــام املــرور‪ .‬لهــذا كلــه فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه احلاضــر ‪........‬باآلتــي‪ :‬أوالً‪ :‬تعاطــي حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة‪ .‬ثاني ـاً‪ :‬حيــازة (‪ )25‬خمســة وعشــرين‬\n      ‫حبــة مــن حبــوب اإلمفيتامــن املنبهــة واحملظــورة بقصــد التعاطــي‪ .‬ثالثـاً‪:‬‬\n\n\n‫‪211‬‬\n\f‫قيــادة الســيارة حتــت تأثيــر احلبــوب املنبهــة احملظــورة‪ .‬وبعــد االطــاع‬\n‫علــى املــواد(‪ )60،56،41‬مــن نظــام مكافحــة املخــدرات ونظــر ًا لقلــة‬\n‫الكميــة احملــازة وعــدم وجــود ســوابق علــى املدعــى عليــه وملــا أبــداه مــن‬\n‫التوبــة فقــد حكمــت بتعزيــر املدعــى عليــه للحــق العــام بجلــده ســتني‬\n‫جلــدة دفعــة واحــدة و ســجنه مــدة ثالثــن يومـ ًا ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن وبإعــان‬\n‫احلكــم قنــع بــه املدعــى عليــه وقــرر املدعــي العــام اعتراضــه وطلــب رفــع‬\n‫املعاملــة حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي‬\n‫هــذا اليــوم األربعاء‪1434/6/7‬ه ـ حضــر املدعــي العــام واملدعــى عليــه‬\n‫‪........‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫وبرفقهــا القــرار برقــم ‪ 34210844‬يف ‪1434/5/11‬ه ـ املتضمــن‪ :‬لوحظ‬\n‫أوالً‪ :‬أن مــا حكــم بــه فضيلتــه مــن ســجن علــى املدعــى عليــه قليــل جــداً‪.‬‬\n‫ثاني ـاً‪ :‬لــم ُيفهــم فضيلتــه بعــد ثبــوت إدانــة املدعــى عليــه بقيــادة الســيارة‬\n‫حتــت تأثيــر احلبــوب احملظــورة أن تقريــر اجلــزاء راجــع للجهــة املختصــة‬\n‫أ‪.‬هــ‪ .‬واســتجابة لوجهــة نظــر أصحــاب الفضيلــة فقــد قــررت الرجــوع عما‬\n‫حكمــت بــه مــن عقوبــة الســجن فقــط وحكمــت بتعزيــر املدعــى عليــه‬\n‫بســجنه ســتني يوم ـ ًا إضافــة لعقوبــة اجللــد واملنــع مــن الســفر الســابقتني‬\n‫كمــا أفهمتــه بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر احلبــوب‬\n‫املنبهــة احملظــورة تقــرر مــن اجلهــة املختصــة وبإعــان احلكــم قنــع بــه‬\n‫املدعــى عليــه وقــرر املدعــي العــام أنــه ال يــزال علــى اعتراضــه احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا رئيس احملكمة اجلزائيــة مبحافظة القطيف فقد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n\n\n                                                                                          ‫‪212‬‬\n\f      ‫القــرار رقــم ‪ 34254934‬يف ‪1434/6/28‬ه ـ املتضمــن املصادقــة علــى‬\n            ‫احلكــم بعــد اإلجــراء األخيــر و للبيــان أحلــق يف ‪1434/7/10‬هــ‪.‬‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e3875c0f1eca56d78114f56fb041934e33ad1665782a45ed0ada39e144e4188e","normalized_text_hash":"d98a4adfbe1beecddd778579d07d215b2a90cd14bcaca17a877f32d309d9c221","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p208-34167139"},{"id":"c5984374-e7ab-5b0b-a1d8-b8fe7f075555","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازه احلشيش املخدر -تستر على الغير -إنكار املدعى عليه -اخلطأ يف العفو خير من اخلطأ يف العقوبة -توجه الشبهة (تهمة ) املوجبة للتعزير -عدم وجود سوابق قضائية -التعزير بالسجن واجللد.","document_number":"34184286","case_number":"3485847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية اخلامسة مبحكمة اإلستئناف يف منطقة مكة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/20","year":"1434","subject":"مخدرات -حيازه احلشيش املخدر -تستر على الغير -إنكار املدعى عليه -اخلطأ يف العفو خير من اخلطأ يف العقوبة -توجه الشبهة (تهمة ) املوجبة للتعزير -عدم وجود سوابق قضائية -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34184286:‬تاريخه‪1434/02/20 :‬هـ‬\n                      ‫رقم الدعوى‪3485847:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34246391‬تاريخه‪1434/06/20:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازه احلشــيش املخــدر ‪ -‬تســتر علــى الغيــر ‪ -‬إنــكار املدعــى‬\n ‫عليــه ‪ -‬اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة ‪ -‬توجــه الشــبهة‬\n ‫(تهمــة ) املوجبــة للتعزيــر ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬التعزيــر‬\n                                                            ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n                                             ‫ما أشير له يف تسبيب احلكم ‪.‬‬\n\n\n\n ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالتســتر علــى‬\n ‫حائــز مخــدرات وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n ‫تعزيريــة ‪ ،‬الحظــت الدوريــات األمنيــة شــخصا يقــود دراجــة ناريــة‬\n ‫بــدون لوحــة فجــرى محاولــة إيقافــه إال أنــه الذ بالفــرار وبالقبــض عليــه‬\n ‫وتفتيــش الدراجــة وجــد بهــا مــادة أثبــت التقريــر الكيميائــي إيجابيتهــا‬\n ‫للحشــيش املخــدر‪ ،‬بالرجــوع للنهايــة الطرفيــة تبــن أنهــا تعــود لشــخص‬\n ‫وباســتجوابه أجــاب بأنــه بــاع الدراجــة للمدعــى عليــه ‪ ،‬وبعرضهمــا علــى‬\n ‫أفــراد الدوريــة القابضــة قــررا بــأن قائــد الدراجــة لــم يكــن أحدهمــا ‪،‬‬\n ‫أنكــر املدعــى عليــه التهمــة فطلــب مــن املدعــي العــام البينــة ‪ ،‬أحضــر‬\n ‫املدعــي العــام شــاهدين شــهدا بقيــام املدعــى عليــه بشــراء الدراجــة مــن‬\n\n                                                                                   ‫‪214‬‬\n\f      ‫املســجلة باســمه ‪ ،‬بعــرض شــهادتهما علــى املدعــى عليــه أنكرهــا ‪،‬‬\n      ‫أحضــر املدعــي العــام البينــة علــى عدالــة الشــاهدين ‪ ،‬طلــب مــن املدعــي‬\n      ‫العــام البينــة علــى وجــود املــادة املخــدرة يف الدراجــة فأحضــر رجلــي‬\n      ‫الدوريــة وشــهدا بذلــك وجــرى تعديلهمــا شــرعا ‪ ،‬وإلنــكار املدعــى‬\n      ‫عليــه وبنــاء علــى شــهادة الشــاهدين املعدلــن شــرعا وألن األمــر يــرد‬\n      ‫عليــه االحتمــال فيوجــب توجيــه الشــبهة ولعــدم وجــود ســوابق مســجلة ‪،‬‬\n      ‫وألن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة ‪ ،‬لذلــك كلــه قــررت‬\n      ‫احملكمــة توجــه التهمــة عليــه بالتســتر علــى حائــز مخــدرات وحكمــت‬\n      ‫عليــه بســجنه أســبوعا ابتــداء مــن إيقافــه وجلــده عشــرين جلــدة دفعــة‬\n      ‫واحــدة ‪ ،‬قــرر املدعــي العــام واملدعــى عليــه عــدم القناعــة فأفهمــا‬\n           ‫بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ ‪1434/02/20‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/02/20‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/02/26‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 15‬وفيهــا‬\n      ‫حضــر املدعــي العام‪..........‬ســعودي اجلنســية املكلــف برقــم ‪..........‬يف‬\n      ‫ا أدعــي علــى ‪.......... :‬ســعودي اجلنســية‬   ‫‪1433 / 1/1‬ه ـ وادعــى قائ ـ ً‬\n      ‫مبوجــب الســجل رقــم‪ ..........‬بتاريــخ ‪1433/12/14‬ه ـ مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل دوريــات األمــن الســرية بعــد أن الحــظ أفــراد‬\n      ‫الدوريــة شــخص ميتطــي دراجــة ناريــة بــدون لوحــة فأشــتبه بــه وعنــد‬\n\n‫‪215‬‬\n\f‫محاولــة اســتيقافه قــام برمــي الدراجــة والذ بالفــرار وبتفتيــش الدراجــة‬\n‫وجــدت مــادة بنيــة اللــون يشــتبه بــأن تكــون مــن مــادة احلشــيش وزنهــا‬\n‫(‪ )0.50‬خمســن يف املئــة مــن اجلــرام ووجــدت اللوحــة مخبــأة وبالرجــوع‬\n‫للنهايــة الطرفيــة تبــن أن ملكيتهــا تعــود لشــخص يدعى‪..........‬وبعــرض‬\n‫املدعــو‪ ..........‬واملدعــى عليــه علــى أفــراد دوريــات األمــن الســرية ذكــروا‬\n‫بــأن الشــخص املطلــوب والــذي كان يقــود الدراجــة الناريــة ليــس‬\n‫منهمــا ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي ‪..........‬إيجابيــة املــادة‬\n‫املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر واحتوائهــا للمــادة‬\n‫الفعالــة لــه واملدرجــة بجــدول رقــم(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة‪ .‬بســماع أقــوال املدعــو ‪ :..........‬أفــاد بأنــه‬\n‫قــام ببيــع الدراجــة الناريــة علــى املدعــى عليــه منــذ بدايــة عــام ‪1433‬ه ـ‬\n‫وال يوجــد لديــه أي إثبــات وذكــر بــان لديــه شــهود علــى ذلــك ‪ .‬بســماع‬\n‫شــهادة كل مــن ‪ ،..........‬و‪ ..........‬حيــث أفــادا بــأن الدراجــة الناريــة تعــود‬\n‫ملكيتهــا لــ‪ ،..........‬وأنــه قــد قــام ببيعهــا للمدعــى عليــه مببلــغ (‪)3000‬‬\n‫ثالثــة آالف ريــال وذلــك قبــل ســنة تقريب ـ ًا وأنهمــا شــهدا املبايعــة‪ .‬وقــد‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه ‪ :‬بالتســتر علــى‬\n‫حائــز املخــدرات ‪ .‬وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرعا لــذا أطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء تســتره علــى حائــز مخــدرات ‪.‬‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه أنكــر مــا جــاء يف الدعــوى هكــذا‬\n‫أجــاب وبســؤال املدعــي العــام عــن البينــة فقــال أطلــب إمهالــي إلحظارهــا‬\n‫يــوم االثنــن ‪1434 /3 /2‬ه ـ الســاعة التاســعة صباح ـ ًا وأقفلــت اجللســة‬\n‫الســاعة الثانيــة عشــر والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                         ‫‪216‬‬\n\f                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/03/02‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي‬\n      ‫العــام واملدعــى عليــه وبســؤال املدعــي العــام عمــا طلــب االمهــال ألجلــه‬\n      ‫قــال حضــرت البينــة وأطلــب ســماعها وعليــه حضــر كل مــن ‪..........‬‬\n      ‫ســعودي اجلنســية ســجل رقــم ‪..........‬و‪ ..........‬ســعودي اجلنســية ســجل رقــم‬\n      ‫‪ ..........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫منفــردا قائــا أشــهد هلل بــأن املدعــى عليــه اشــترى دبابــا مــن ‪..........‬‬\n      ‫وحضرنــا املبايعــة بينهمــا واشــتراه مببلــغ ثالثــة آالف ريــال يف حــج‬\n      ‫عــام ‪1432‬ه ـ وكانــت املبايعــة يف اســتراحة والدنــا ب‪ ..........‬وكان‬\n      ‫ذلــك يف املســاء وذلــك بحضــور الطرفــن هكــذا شــهدا وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه أنكــر مــا جــاء يف الشــهادة هكــذا أجــاب وعليــه‬\n      ‫جــرى رفــع اجللســة إلحضــار مزكــن ورفعــت اجللســة إلــى يــوم االثنــن‬\n      ‫‪1434/3/16‬ه ـ الســاعة العاشــرة صباحــا وأقفلــت اجللســة الســاعة‬\n      ‫الثانيــة عشــر ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/02‬هــ‪.‬‬\n      ‫احلمد هلل وحده وبعد ففي يوم اإلثنني املوافق‪ 1434/03/16‬هـ افتتحت‬\n      ‫اجللســة الســاعة وفيهــا حضــر املدعــي العــام واملدعــى عليــه وحضــر‬\n      ‫املزكــن وهــم ‪..........‬و ‪..........‬وشــهدا بعدالــة الشــاهدين املذكوريــن‬\n      ‫ســابق ًا وبســؤال املدعــي العــام البينــة علــى وجــود املخــدرات يف الدراجــة‬\n      ‫الناريــة العائــدة ملكيتهــا للمدعــى عليــه فأجــاب أطلــب املهلــة لذلــك‬\n      ‫عليــه رفعــت اجللســة يف يــوم اإلثنــن ‪1434 /3 /23‬ه ـ الســاعة التاســعة‬\n      ‫صباحـ ًا وأقفلــت اجللســة الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n‫‪217‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/03/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12.30‬وفيهــا حضــر املدعــي العــام ولــم يحضــر‬\n‫املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة فقــال لــم حتضــر وأطلــب‬\n‫إمهالــي إلحضارهــا يف يــوم اإلثنــن ‪1434 / 4 /1‬ه ـ الســاعة التاســعة‬\n‫صباحـ ًا وعليــه أقفلــت اجللســة الســاعة الواحــدة ظهــر ًا وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/03/23‬ه ـ‬\n‫ا حلمــد هلل وحــده وبعــد ف ففــي يــوم اإلثنــن املوافق‪1434/04/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وبســؤال املدعــي العــام عمــا طلــب االمهــال‬\n‫ألجلــه قــال حضــرت البينــة وأطلــب ســماعها وعليــه حضــر كل مــن‬\n‫‪..........‬ســعودي اجلنســية ســجل رقــم ‪..........‬و‪ ..........‬ســعودي اجلنســية‬\n‫ســجل رقــم ‪..........‬وبســؤالهم عمــا لديهــم مــن شــهادة شــهد كل‬\n‫واحــد منهمــا قائــا أشــهد هلل بأننــا كنــا يف مهمــة ووجدنــا شــخصا‬\n‫يقــود دراجــة ناريــة فشــككنا يف أمــره وعليــه أثــر االرتبــاك ثــم قمنــا‬\n‫مبتابعتــه فرمــى الدراجــة وهــرب وقمنــا بتفتيــش الدراجــة فوجدنــا بهــا‬\n‫قطعــة مــن احلشــيش املخــدر وحــن عــرض املدعــى عليــه علينــا يف إدارة‬\n‫مكافحــة املخــدرات تبــن لنــا أنــه ليــس هــو الــذي كان يقــود الدراجــة‬\n‫وليــس البائــع األول هكــذا شــهدا وجــرى تعديــل الشــهود مــن قبــل‪..........‬‬\n‫و‪..........‬ورفعــت اجللســة إلحضــار املدعــى عليــه وأجلــت إلــى يــوم االثنــن‬\n‫‪1434/4/8‬ه ـ الســاعة التاســعة صباحــا وأقفلــت اجللســة الســاعة‬\n‫العاشــرة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                     ‫‪218‬‬\n\f      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ احلمــد‬\n      ‫هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه فبنــاء علــى مــا تقــدم وإلنــكار املدعــى عليــه مبــا جــاء يف الدعــوى‬\n      ‫ولشــهادة الشــهود املعدلــة شــرعا وألن األمــر يــرد عليــه االحتمــال فيوجب‬\n      ‫توجيــه الشــبهة ولعــدم ســوابقه وألن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف‬\n      ‫العقوبــة لذلــك كلــه فــإن الشــبهة تتوجــه بقيــام املدعــى عليــه بالتســتر‬\n      ‫علــى حائــز املخــدرات وعليــه فقــد حكمــت عليــه مبــا يلــي ‪ -1 :‬بســجنه‬\n      ‫أســبوعا ابتــداء مــن تاريــخ إيقافــه‪ -2 .‬بجلــده عشــرين جلــدة دفعــة‬\n      ‫واحــدة وبعــرض احلكــم علــى املدعــي العــام قــرر االعتــراض بالئحــة‬\n      ‫وجــرى تســليمه نســخة مــن القــرار الشــرعي وأفهــم بنظــام االســتئناف‬\n      ‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة‬\n      ‫وأفهــم بنظــام االســتئناف وأقفلــت اجللســة الســاعة العاشــرة والنصــف‬\n      ‫صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/08‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n      ‫يــوم اإلثنــن املوافــق‪ 1434/07/10‬ه ـ افتتحــت اجللســة وفيهــا عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا قرارهــا رقــم ‪34246391‬‬\n      ‫وتاريــخ ‪1434/6/20‬ه ـ املتضمــن املوافقــة علــى احلكــم الصــادر منــا‬\n      ‫برقــم ‪ 34184286‬وتاريــخ ‪1434/4/10‬ه ـ لــذا أمــرت باحلــاق ذلــك‬\n      ‫لضبطــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/10‬ه ـ احلمــد هلل وحــده والصــاة‬\n      ‫والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد جــرى منــا نحــن قضــاة‬\n      ‫الدائــرة اجلزائيــة اخلامســة مبحكمــة اإلســتئناف يف منطقــة مكــة‬\n\n\n‫‪219‬‬\n\f‫املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪34435749‬وتاريــخ ‪1434/5/25‬ه ـ‬\n‫املرفــق بهــا القــرار رقــم ‪34184286‬وتاريخ‪1434/4/10‬ه ـ الصــادر مــن‬\n‫فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ..........‬ســعودي اجلنســية املتهــم يف‬\n‫مخــدرات احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                 ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":214,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f843e726c481baffb74e0f67e2913740b69f1c549877531be7662e49b5d39138","normalized_text_hash":"7bb889d788a6a7584d5f9ae8dde25578c83f6c266a6938cf15ab29ec0b7ddc56","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p214-34184286"},{"id":"7b989df5-6d5d-5ce3-82ee-39fc6e2ff1ab","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة ألجل التداوي مبوجب تقرير طبي -رد دعوى","document_number":"34173841","case_number":"3492036","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/28","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة ألجل التداوي مبوجب تقرير طبي -رد دعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34173841 :‬تاريخه‪1434/03/28 :‬هـ‬\n                            ‫رقم الدعوى‪3492036 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3488340‬تاريخه‪1434/4/27:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n       ‫وتعاطيهــا ‪ -‬حيــازة ألجــل التــداوي مبوجــب تقريــر طبــي ‪ -‬رد دعــوى‬\n                                                             ‫‪ -‬إخــاء ســبيل‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬األصل براءة الذمة‪.‬‬\n                                 ‫‪ -2‬اخلطأ يف العفو خير من اخلطأ يف العقوبة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإثبــات إدانتــه بحيــازة احلشــيش‬\n       ‫املخــدر وحبــوب الترامــادول احملظــورة بقصــد التعاطــي وتعاطيــه لهــا‪،‬‬\n       ‫واحلكــم عليــه بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث أنــه مت تفتيــش مكتــب‬\n       ‫املدعــى عليــه بعــد ورود معلومــات عنــه فعثــر فيــه علــى حبــوب الترامادول‬\n       ‫احملظــورة وقطعــة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر الكيميائــي‬\n       ‫الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر ولعقــار الترامــادول‪،‬‬\n       ‫كمــا أنــه أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن حيــازة‬\n       ‫حبــوب الترامــادول لالســتخدام الشــخصي وتعاطيــه لهــا ودفــع بأنــه‬\n       ‫يســتخدمها كعــاج مســكن بوصفــة طبيــة وأنكــر حيازتــه وتعاطيــه‬\n\n‫‪221‬‬\n\f‫للحشــيش املخــدر بنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد دعــوى‬\n‫املدعــي العــام وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‪ ،‬وقنــع‬\n‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة‬\n                                    ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يوم األربعــاء املوافق ‪1434/3/25‬هـ لدي أنا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                            ‫‪ ........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )3492036‬وتاريــخ ‪1434/2/25‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر ‪ ........‬مصــري اجلنســية مبوجــب رخصــة‬\n‫إقامــة رقــم (‪ )........‬وقــدم املدعــي العــام ‪........‬الئحــة االدعــاء املتضمنــة‬\n‫بصفتي مدعي ًا عام ًا بدائرة االدعاء العام لفرع الهيئة باملنطقة الشرقية‬\n‫أدعــي علــى املذكــور أعــاه حيــث إنــه باالطــاع علــى محضــر البــاغ‬\n‫والضبــط والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة‬\n‫املخــدرات بالدمــام تبــن أنــه يف يــوم األحــد املوافــق ‪1434/1/17‬ه ـ ورد‬\n‫معلومــات عــن شــخص مصــري اجلنســية يدعــى‪ ........‬احلشــيش املخــدر و‬\n‫حبــوب الترامــادول احملظــورة و يعمــل بـ‪........‬بالشــارع ‪........‬بالدمــام وبنــاء‬\n‫علــى مــا ذكــر مت االنتقــال للموقــع إذ لوحــظ شــخص بجــوار احملــل‬\n‫تنطبــق عليــه نقــس املواصفــات وبعــد أخبــاره بــأن الفرقــة رجــال أمــن‬\n‫جــرى تفتيــش املذكــور شــخصيا و تفتيــش ســيارته ولــم يعثــر معــه علــى‬\n‫أي ممنوعــات وبنــاء علــى املــادة ( ‪ ) 43‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫جــرى تفتيــش مكتــب املذكــور وعثــر علــى عــدد ( ‪ ) 28‬حبــة حمــراء‬\n‫اللــون يشــتبه أن تكــون مــن حبــوب الترامــادول احملظــورة كمــا عثــر‬\n\n                                                                                        ‫‪222‬‬\n\f      ‫علــى فرطــه داخــل أدراج املكتــب يشــتبه أن تكــون ممزوجــة مبــادة‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا ( ‪ ) 0.2‬اثنــان مــن العشــرة مــن اجلــرام وقــد‬\n      ‫ورد التقريــر الكيمــاوي الشــرعي رقــم ( ‪ )........‬وتاريــخ ‪1434/2 /2‬ه ـ‬\n      ‫املتضمــن ايجابيــة احلبــوب املضبوطــة لعقــار الترامــادول و املــدرج يف‬\n      ‫اجلــدول األول فئــة (هــ) امللحــق بنظــام مكافحــة املخــدرات ومــا أثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي املشــار إليــه احتــواء التبــغ املضبــوط علــى‬\n      ‫مــادة احلشــيش املخــدر و املــدرج يف اجلــدول األول فئــة (أ) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات وبســماع أقوالــه األوليــة مــن قبــل رجــال الضبــط‬\n      ‫اجلنائــي أقــر بحيازتــه حلبــوب الترامــادول لقصــد االســتخدام الشــخصي‬\n      ‫كعــاج مســكن وأنــه تعاطــى احلبــوب احملظــورة قبــل القبــض عليــه‬\n      ‫بثالثــة أســابيع وأنكــر حيازتــه للحشــيش املخــدر وقــد انتهــى التحقيــق‬\n      ‫إلى توجيه االتهام لـ‪ ........‬باآلتي‪ -1 :‬بحيازة (‪ )28‬ثمانية وعشــرون حبة‬\n      ‫مــن حبــوب الترامــادول احملظــورة بقصــد التعاطــي ‪ -2‬تعاطــي احلبــوب‬\n      ‫احملظــورة‪ -3 .‬حيــازة تبــغ بلــغ وزنــه ( ‪ ) 0.2‬اثنــان مــن العشــرة مــن‬\n      ‫اجلــرام يحتــوي علــى مــادة احلشــيش املخــدر بقصــد التعاطي وذلــك لألدلة‬\n      ‫والقرائــن التاليــة‪ -1 :‬إقــرار املدعــى عليــه واملــدون علــى الصفحتــن رقــم‬\n      ‫(‪ )19.18‬مــن ملــف ضبــط إجــراءات االســتدالل‪ -2 .‬محضــر البــاغ‬\n      ‫والضبــط والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي واملــدون علــى‬\n      ‫الصفحــة رقــم (‪ )11‬مــن ملــف ضبــط إجــراءات االســتدالل ‪ -3‬التقريــر‬\n      ‫الكيمــاوي املشــار إليــه واملرفــق علــى اللفــة رقــم (‪ )11‬وحيــث إن مــا‬\n      ‫أقــدم عليــه املدعــى عليه‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرعا‪ -‬فعــل‬\n      ‫وفقــا‬\n         ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا أســند إليــه ً‬\n      ‫للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪223‬‬\n\f‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة الســجن الــواردة‬\n‫بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬مــن النظــام‪ -2 .‬إبعــاده عــن البــاد‬\n‫إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن النظــام وبــاهلل‬\n‫التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العام من‬\n‫حيازتــي لعــدد ثمــان وعشــرين حبــة من حبــوب الترامــادول وأنني أتعاطى‬\n‫منهــا فهــذا صحيــح وذلــك ألننــي مريــض ومصاب بــآالم يف فقرات الظهر‬\n‫وأســتخدم هــذه احلبــوب بوصفــة طبيــة لتســكني آالم الظهــر ومــا ذكــره‬\n‫مــن ضبــط فرطــة التبــغ احملتــوي علــى احلشــيش املخــدر يف مكتبي فهذا‬\n‫صحيــح ولكــن ال عالقــة لــي بهــا ألن املكتــب مفتــوح وليــس لــه بــاب‬\n‫ويوجــد فيــه أربعــة عشــر موظفــا تقريبــا وقــد تكــون الفرطــة ألحدهــم‬\n‫هــذه إجابتــي ثــم أبــرز التقريــر طبــي الصــادر مــن مستشــفى تــداوي العام‬\n‫بتاريــخ ‪1434/1/26‬ه ـ املتضمــن أنــه بالكشــف علــى املدعــى عليــه‬\n‫تبــن وجــود تغيــرات تنكســية للعمــود الفقــري القطنــي وبعــد مراجعــة‬\n‫ملــف املريــض لوحــظ وجــود عــدة زيــارات لعيــادة العظــام بعــدة تواريــخ‬\n‫آخرهــا بتاريــخ ‪2010/3/7‬م وزيارتــان أخريــان بتاريــخ ‪2008/8/26‬م‬\n‫وبتاريــخ ‪2008/1/26‬م مــع األدويــة املناســبة وإعطــاء وصفــات عقــار‬\n‫الترامــادول يف املــرات الســابقة املذكــورة وبنــاء علــى طلبــه أعطــي هــذا‬\n‫التقريــر وبتأمــل التقريــر الحظــت أنــه صــدر بعــد القبــض علــى املدعــى‬\n‫عليــه بأســبوع كمــا تضمــن أن آخــر زيــارة لــه للمستشــفى كانــت قبــل‬\n‫هــذه القضيــة بثــاث ســنوات تقريبـ ًا وعليــه قــررت الكتابــة للمستشــفى‬\n‫للتأكــد مــن صحــة هــذا التقريــر وهــل التوصيــة باســتخدام هــذه احلبــوب‬\n‫مســتمر طيلــة هــذه املــدة ورفعــت اجللســة وتأجلــت إلــى حــن ورود اإلجابــة‬\n‫ويف يــوم الســبت املوافــق ‪1434/3/28‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫املدعــى عليــه املــدون هويتــه ســابق ًا وقــد وردنــا التقريــر الطبــي الصــادر‬\n      ‫مــن مستشــفى تــداوي العــام برقــم ( ‪ )6/2/13‬وتاريــخ ‪1434/3/25‬ه ـ‬\n      ‫واملتضمــن أنــه بالكشــف علــى املدعــى عليــه تبــن وجــود تغيــرات‬\n      ‫تنكســية للعمــود الفقــري القطنــي وبعــد مراجعــه ملــف املريــض كانــت‬\n      ‫آخــر زيــارة بتاريــخ ‪2012/3/7‬م وتعــد الشــكايات التــي لــدى املريــض‬\n      ‫مزمنــة وهــي مرشــحة للتفاقــم تدريجي ـ ًا مــع الوقــت وخاصــة يف حــال‬\n      ‫اســتمرار اجلهــد والتعــب وهــي شــكايات شــديدة أحيان ـ ًا وال تســتجيب‬\n      ‫للمســكنات واألدويــة التقليديــة ممــا يســتدعي صرف األدوية املســكنة‬\n      ‫القويــة جــد ًا وغيــر التقليديــة وعــادة يتــم يف كل مــرة صــرف عشــرين‬\n      ‫قرص ـ ًا أو أكثــر حســب التركيــز املســتخدم وتتــراوح اجلرعــة اليوميــة‬\n      ‫مــا بــن قــرص واحــد وأربعــة أقــراص يف احلــاالت الشــديدة وقــد تزيــد‬\n      ‫كمــا أحضــر املدعــى عليــه للشــهادة وأدائهــا كل مــن ‪ ........‬مصــري‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم‪ ........‬و ‪ ........‬مصــري مبوجب رخصة إقامة‬\n      ‫رقــم ‪ ........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫ا إننــي أعمــل مــع املدعــى عليــه يف معــرض ‪........‬ألنظمــة‬    ‫مبفــرده قائ ـ ً‬\n      ‫املكاتــب وأشــهد بــاهلل العظيــم بــأن مكتــب املدعــى عليــه يف املعــرض‬\n      ‫يف مــكان مفتــوح ليــس لــه بــاب ويســتطيع جميــع العاملــن يف املعــرض‬\n      ‫مــن موظفــن وعمــال الوصــول إليــه وكثيــر ًا مــن األحيــان يدخلــون‬\n      ‫للمكتــب يف حــال غيبــة املدعــى عليــه ألجــل الفاكــس أو التنظيــف‬\n      ‫ونحــو ذلــك هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا شــهدا‬\n      ‫كمــا حضــر لتعديــل الشــاهدين كل مــن‪ ........‬مصــري مبوجــب رخصــة‬\n      ‫إقامــة رقــم ‪ ........‬و ‪ ........‬مصــري مبوجــب رخصــة إقامــة رقــم‪ ........‬وقــد‬\n      ‫شــهد كل واحــد منهمــا بقولــه إننــي أعــرف الشــاهدين وهمــا عدلــن‬\n\n\n‫‪225‬‬\n\f‫ثقتــن هكــذا شــهدا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى التقريريــن الطبيــن املرصوديــن واللــذان يثبتــان وجــود أعــراض‬\n‫مرضيــة للمدعــى عليــه تســتدعي العــاج بحبــوب الترامــادول املضبوطــة‬\n‫معــه وبنــاء علــى شــهادة الشــاهدين املعدلــن التعديل الشــرعي واملتضمنة‬\n‫أن مكتــب املدعــى عليــه يف مــكان مفتــوح وليــس لــه بــاب ويســتطيع‬\n‫جميــع املوظفــن والعاملــن مــن الوصــول إليــه وأنهــم أحيان ـ ًا يدخلــون‬\n‫فيــه حــال غيبــة املدعــى عليــه وقــد تكــون الفرطــه املمزوجــة باحلشــيش‬\n‫واملضبوطــة داخــل املكتــب عائــدة ألي منهــم وحيــث إن األصــل بــراءة‬\n‫الذمــة وحيــث إن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة لــذا فقــد‬\n‫حكمــت بــرد دعــوى املدعــي العــام وإخــاء ســبيل املدعــى عليــه مــن هــذه‬\n‫الدعــوى وبعــرض ذلــك علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي‬\n‫العــام االعتــراض واالكتفــاء مبــا يف أوراق املعاملــة فأجيــب لطلبه وباهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف ‪1434/3/28‬هــ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/4/30‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة والنصــف وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫برقــم (‪ )34/883408‬وتاريــخ ‪1434/4/27‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام‪ ........‬ضــد ‪ ........‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة‬\n‫الثانيــة برقــم (‪ )34192862‬وتاريــخ ‪1434/4/21‬ه ـ املتضمــن املصادقــة‬\n‫علــى احلكــم لــذا جــرى إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلى‬\n                         ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                                      ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":221,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"53762ad04fe43406c1be4d2d9cc63a941a9d03c0fd86c05cd44d22dbe82b72ce","normalized_text_hash":"f110f2ddea3d92a362df019861027ff33c9386e623314f2926c2e590459b4556","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p221-34173841"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c1b94a0c-8a84-5564-a2be-d657f443d27e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -اصطحاب امرأتن أجنبيتن -كبر الكمية املضبوطة -اإلقرار بالتعاطي - التعزير للشبهة .","document_number":"3438665","case_number":"3476029","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/17","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -اصطحاب امرأتن أجنبيتن -كبر الكمية املضبوطة -اإلقرار بالتعاطي - التعزير للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3438665 :‬تاريخه ‪1434/2/17:‬هـ‬\n                    ‫رقم القضية‪3476029 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3456395‬تاريخه‪1434/03/07:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬اصطحــاب‬\n‫امرأتــن أجنبيتــن ‪ -‬كبــر الكميــة املضبوطــة ‪ -‬اإلقــرار بالتعاطــي ‪-‬‬\n                                                     ‫التعزيــر للشــبهة ‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة الرابعة من القرار الوزاري رقم (‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n                      ‫‪ -2‬قرار وزير الداخلية رقم (‪ )2057‬لعام ‪1404‬هـ ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد الترويــج‬\n‫والتعاطــي واصطحابــه المرأتــن ال متتــان لــه بصلــة شــرعية وطلــب‬\n‫إثبــات مــا أســند إليــه ومعاقبتــه تعزيــر ًا ومنعــه مــن الســفر وفــق األنظمــة‬\n‫والتعليمــات‪ ،‬أثنــاء قيــام الدوريــة األمنيــة بواجبهــا أتــت ســيارة يقودهــا‬\n‫املدعــى عليــه ويرافقــه امرتــان ال متتــان لــه بصلــة شــرعية وبتفتيــش‬\n‫الســيارة عثــر بداخلهــا علــى نبــات القــات وأثبــت التقريــر الكيميائــي‬\n‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى‬\n‫عليــه علــى الدعــوى ماعــدا الترويــج فأنكــره ‪ ،‬وبينــة املدعــي العــام‬\n‫كبــر الكميــة املضبوطــة ومت إثبــات إدانــة املدعــى عليــه بحيــازة‬\n‫القــات بقصــد االســتعمال الشــخصي ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n\n                                                                                        ‫‪176‬‬\n\f      ‫احملكمــة بســجنه تعزيــر ًا وصــرف النظــر عــن طلــب املدعــي العــام لعــدم‬\n      ‫ثبــوت اإلدانــة بالترويــج وتعزيــره لشــبهة الترويــج والصطحابــه احملــرم‬\n      ‫شــرع ًا ولتعــدد ســوابقه بجلــده مائــة وخمســن جلــدة مفرقــة علــى ثــاث‬\n      ‫فتــرات وصــرف النظــر عــن طلــب املدعــي العــام منعــه مــن الســفر و قنــع‬\n      ‫‪،‬وصــدق احلكــم مــن‬‫املدعــى عليــه واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 3476029‬وتاريــخ ‪ 1434/02/16‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 34382111‬وتاريخ ‪ 1434/02/16‬هـ ففي يوم األحد‬\n      ‫املوافق‪ 1434/02/17‬هـ افتتحت اجللسة األولى الساعة ‪ 08 : 30‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم ‪ 9882‬يف ‪1433/3/22‬ه ـ‬\n      ‫وادعــى علــى احلاضــر معــه الســجني ‪(..... /‬ســعودي ) اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪).....‬حيــث إنــه بتاريــخ ‪1433/1/4‬ه ـ وأثنــاء قيــام‬\n      ‫إحــدى دوريــات املجاهديــن بواجبهــا يف املوقــع املســمى ‪ .............‬أتــت‬\n      ‫ســيارة مــن نــوع ‪ ...‬حتمــل اللوحــة رقــم (‪( ).....‬مســتأجره مــن قبــل مؤسســة‬\n      ‫‪.....‬للمقــاوالت) (مضبوطــة حلــن مراجعــة مالكهــا) بقيــادة املدعــي عليــه‬\n      ‫ويرافقــه كل مــن املدعوة‪(...../‬إثيوبيــة اجلنســية) ( لــم يوجــه لهــا االتهــام‬\n      ‫مــع إحالتهــا إلــى جهــة القبــض للنظــر يف قضيــة اخللــوة ) واملدعــوة ‪..... /‬‬\n      ‫(إثيوبيــة اجلنســية) ( لــم يوجــه لهــا االتهــام مــع إحالتهــا إلــى جهــة القبــض‬\n      ‫للنظــر يف قضيــة اخللــوة )(فــرزت أوراق وأحيلــت جلهــة االختصــاص‬\n\n‫‪177‬‬\n\f‫للمدعــي عليــه لقــاء أركابــه مخالفــي نظــام اإلقامــة) وباســتيقاف‬\n‫الســيارة وتفتيشــها عثــر بداخلهــا علــى كميــة مــن نبــات القــات باألمــام‬\n‫وباخللــف وبلــغ وزنهــا (‪ 26‬كجــم) ســتة وعشــرون كيلــو جرام ـ ًا مــن‬\n‫نبــات القــات احملظــور‪ ،‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/1/12‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة والشــرعية بجــازان إيجابيــة العينــة املرســلة منــه‬\n‫لنبــات القــات احملظــور املدرجــة باجلــدول رقــم(‪ )4‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة املرفقــة بالتعميــم البرقــي لصاحــب الســمو‬\n‫امللكــي وزيــر الداخليــة (‪ )89400/19‬يف ‪1426/10/25‬ه ـ والصــادر‬\n‫باملرســوم امللكــي رقــم( م ‪) 39/‬وتاريــخ ‪1426/7/8‬ه ـ أوقــف اســتنادا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪ 1428/7/9‬ه ـ كــون جرميتــه‬\n‫مــن اجلرائــم املوجبــة للتوقيــف‪ .‬وباســتجواب املدعــي عليــه ومواجهتــه‬\n‫بالتهــم املنســوبة إليــه أقــر بحيازتــه للكميــة املضبوطــة وأن غرضــه‬\n‫منهــا االســتخدام الشــخصي وأنــه قــام بشــرائها مــن محافظــة ‪ ........‬مــن‬\n‫شــخص يدعــى‪ .....‬مببلــغ وقــدرة (‪1000‬ريال)وأنــه ينــوي إيصالهــا إلــى‬\n‫منزلــه بقريــة ‪.....‬التابعــة حملافظــة صبيــا وأنــه قــام بــإركاب مرافقتيــه‬\n‫مــن محافظــة ‪ ........‬وينــوي إيصالهمــا حملافظــة صبيــا مببلــغ وقــدرة‬\n   ‫(‪ 500‬ريــال) وأن ليــس لهمــا أي علــم أو عالقــة بالكميــة املضبوطــة‪.‬‬\n‫وقــد أســفر التحقيــق مــع املدعــي عليــه عــن توجيــه االتهــام لــه بحيازتــه‬\n‫مــا وزنــه (‪ 26‬كجــم) ســتة وعشــرون كيلــو جرام ـ ًا مــن نبــات القــات‬\n‫احملظــور بقصــد الترويــج والتعاطــي‪ ،‬واملجــرم مبوجــب الفقــرة الثانيــة‬\n‫مــن املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وقيامــه‬\n\n\n                                                                                    ‫‪178‬‬\n\f                                 ‫باصطحــاب المرأتــن ال متتــان لــه بصلــة شــرعية‪.‬‬\n                                                       ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n               ‫‪ -1‬ما جاء يف إقراره املصدق حتقيق ًا املنوه عنه واملدون لفه (‪)19‬‬\n      ‫‪ -2‬مــا ورد مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n                                                                             ‫رقــم (‪. )5.6‬‬\n                        ‫‪ -3‬ما جاء يف سماع أقواله املنوه عنها واملدونة لفه (‪. )9‬‬\n         ‫‪ -4‬ما ورد بالتقرير الكيميائي الشرعي املنوه عنه املرفق لفه (‪. )25‬‬\n      ‫وبالبحــث عــن ســوابقه عثــر لــه علــى ثــاث ســوابق األولــى ‪ /‬دخــول‬\n      ‫منــازل لغــرض ســيء والثانيــة‪ /‬اســتعمال قــات والثالثــة ‪ /‬نقــل قــات‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــي عليــه فعــل محــرم شــرع ًا و معاقــب‬\n      ‫عليــه نظامـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا‬\n                                                                ‫حلــق بــه مــن تعديــات‪.‬‬\n                                ‫لذا اطلب‪/‬إثبات إدانته مبا أسند إليه واحلكم بـ‪:‬‬\n      ‫‪.1‬تعزيــره يف ضــوء املــادة (الثالثــة والرابعــة) مــن القــرار الــوزاري املشــار‬\n      ‫إليــه أعــاه إنفــاذ ًا لألمــر الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ‬\n                           ‫‪1432/12/9‬هـ‪.‬والتشــديد عليــه لقــاء تعــدد ســوابقه‬\n                            ‫‪.2‬احلكم مبنعه من السفر بعد انقضاء محكوميته‪.‬‬\n                                              ‫‪.3‬تعزيرة لقاء اصطحابه احملرم شرعاً‪.‬‬\n      ‫وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه صــدق علــى‬\n      ‫صحــة مــا جــاء فيهــا و أقــر بحيازتــه للكميــة املضبوطــة وأن غرضــه‬\n      ‫منهــا االســتخدام الشــخصي وأنــه قــام بشــرائها مــن محافظــة الدائــر مــن‬\n      ‫شــخص يدعــى ‪ .....‬مببلــغ وقــدرة (‪1000‬ريــال) وأنــه ينــوي إيصالهــا إلــى‬\n      ‫منزلــه بقريــة ‪.....‬التابعــة حملافظــة صبيــا وأنــه قــام بــإركاب مرافقتيــه‬\n\n\n‫‪179‬‬\n\f‫مــن محافظــة ‪ ............ ....‬وينــوي إيصالهمــا حملافظــة صبيــا مببلــغ وقدرة‬\n‫(‪ 500‬ريــال) وأن ليــس لهمــا أي علــم أو عالقــة بالكمية املضبوطة كما‬\n‫أقــر بالســوابق املذكــورة يف الئحــة الدعــوى وأنــه نــال العقوبــة املقــررة‬\n‫عليهــا هكــذا أجــاب وقــد جــرى ســؤال املدعــي العــام عــن بينتــه علــى أن‬\n‫الكميــة معــدة للترويــج قــال بينتــي كبــر حجــم الكميــه املضبوطــة‬\n‫وال ميكــن أن تكــون لالســتعمال الشــخصي وبعــرض ذلــك علــى املدعــى‬\n‫عليــه قــال الصحيــح مــا ذكــرت وأنهــا لالســتعمال الشــخصي هكــذا‬\n‫أجــاب وباالطــاع علــى محضــر القبــض والتحقيــق وجــد مطابــق ملــا جــاء‬\n‫يف الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي الشــرعي لفــة‬\n‫رقــم (‪ )25‬وجــد إيجابيــة العينــة املرســلة لنبــات القــات وباالطــاع علــى‬\n‫صحيفــة الســوابق عثــر لــه علــى ثــاث ســوابق األولــى ‪ /‬دخــول منــازل‬\n‫ـاء علــى‬\n        ‫لغــرض ســيء والثانيــة‪ /‬اســتعمال قــات والثالثــة ‪ /‬نقــل قــات فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بحيازتــه‬\n‫للكميــة املرصــودة أعــاه لغــرض االســتعمال الشــخصي وحيــث أنكــر‬\n‫قصــد الترويــج وال بينــة للمدعــي العــام ســوى كبــر حجــم الكميــه‬\n‫املضبوطــة وحيــث اعتــرف بخلوتــه ونقلــه للمرأتــن وهمــا ال متتــان لــه‬\n‫بصلــة وحيــث إن مــا أقــدم عليــه فعــل محــرم فقــد ثبــت لــدى إدانــة املدعــى‬\n‫عليــه بحيازتــه ملــا وزنــه (‪ 26‬كجــم) ســتة وعشــرون كيلــو جــرام مــن‬\n‫نبــات القــات لغــرض االســتعمال الشــخصي وحكمــت عليــه تعزيــر ًا‬\n‫بالســجن ملــدة ســنة اعتبــارا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‬\n‫اســتنادا للمــادة الرابعــة مــن القــرار الــوزاري رقــم(‪ )11‬لعام‪1374‬ه ـ‬\n‫واملعــدل بقــراري وزيــر الداخليــة رقــم(‪ )2057‬لعام‪1404‬ه ـ ورقم(‪)3818‬‬\n‫لعام‪1410‬ه ـ وصرفــت النظــر عــن طلــب املدعــي العــام لعــدم وجــود مــا‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫يؤيــد الترويــج ونظــر ًا لكبــر حجــم الكميــة ولوجــود شــبهة الترويــج‬\n      ‫والصطحابــه احملــرم شــرع ًا ولتعــدد ســوابقه فهــو يســتحق التعزيــر‬\n      ‫علــى ذلــك بجلــده ألجــل ذلــك مائــة و خمســون جلــدة مفرقــة علــى ثــاث‬\n      ‫فتــرات بــن كل فتــرة واألخــرى ال يقــل عــن أســبوع وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي العــام منعــه مــن الســفر لعــدم اشــتمال القــرار رقــم ‪ 11‬لعــام‬\n      ‫‪1374‬ه ـ ومــا تبعــه مــن تعديــات علــى منــع ‪ -‬مــن حــاز كميــة مــن القــات‬\n      ‫لالســتعمال ‪ -‬مــن الســفر إذا كان ســعودي ًا ومبــا ســبق حكمــت وبهــذا‬\n      ‫انتهــت هــذه الدعــوى وبعــرض مــا حكمنــا بــه املدعــى عليــه قنــع بــه وقرر‬\n      ‫املدعــي العــام عــدم القناعــة وطلــب رفعهــا إلــى محكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34382111‬‬\n      ‫وتاريــخ ‪1434/2/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪.....‬برقم ‪ 3438665‬وتاريــخ ‪1434/2/17‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .....‬يف قضيــة (قــات) علــى الصفــة املوضحــة‬\n      ‫يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى‬\n      ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":176,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"42c9066ac207b556d8d30adfbda7b284c8b4103f72b6f9d4c24ebf9b8e08525c","normalized_text_hash":"406ecd1dd2e120565cde5c6f0c557d84e6670e297b4222145400d111a089d4b1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p176-3438665"},{"id":"3959d477-bc69-5103-a71b-acdaffea66b7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -شرب مسكر وحيازته بقصد االستعمال -محاولة الهرب من رجال األمن -إقرار -بينة غير موصلة -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة بقصد التعاطي -حد املسكر -تعزير باجللد والسجن واملنع من السفر.","document_number":"342030072","case_number":"3477434","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/04","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج وتعاطيها -شرب مسكر وحيازته بقصد االستعمال -محاولة الهرب من رجال األمن -إقرار -بينة غير موصلة -عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة باحليازة بقصد التعاطي -حد املسكر -تعزير باجللد والسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 342030072:‬تاريخه‪1434/06/04 :‬هـ‬\n                       ‫رقم الدعوى‪3477434:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35112419‬تاريخه‪1434/01/11:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي والترويــج‬\n  ‫وتعاطيهــا‪ -‬شــرب مســكر وحيازتــه بقصــد االســتعمال‪ -‬محاولــة الهــرب‬\n  ‫مــن رجــال األمــن‪ -‬إقــرار‪ -‬بينــة غيــر موصلــة‪ -‬عــدم التقيــد بالوصــف‬\n  ‫الــوارد يف الئحــة الدعــوى‪ -‬إدانــة باحليــازة بقصــد التعاطــي ‪ -‬حــد‬\n                  ‫املســكر ‪ -‬تعزيــر باجللــد والســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n             ‫‪ -1‬قول اهلل تعالى‪(( :‬إمنا اخلمر وامليسر‪ ..‬اآلية)) املائدة‪90:‬‬\n  ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                          ‫حــرام)‪ .‬رواه مســلم‬\n  ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬إن اهلل لعــن اخلمــر وعاصرهــا‪..‬‬\n                                                   ‫احلديــث)‪ .‬رواه احلاكــم‪.‬‬\n                  ‫‪ -4‬قرار هيئة كبار العلماء رقم (‪ )53‬يف ‪1397/4/4‬هـ ‪.‬‬\n           ‫‪ -5‬املواد (‪ )128‬و (‪ )131‬و(‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n  ‫‪ -6‬املــواد (‪ )3‬و(‪ )41‬و(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n\n\n\n\n                                                                                  ‫‪182‬‬\n\f      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهــم تتضمــن طلــب إثبــات إدانــة‬\n      ‫الثانــي بحيــازة حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي والترويــج‬\n      ‫وتعاطيــه لهــا وإدانــة الثالــث بحيــازة املســكر بقصــد االســتعمال وشــربه‬\n      ‫لــه وإدانــة األول مبحاولــة الهــرب مــن رجــال األمــن ومحاولــة مقاومتهــم‬\n      ‫وشــرب املســكر‪ ،‬واحلكم على الثاني بعقوبة الســجن واجللد والغرامة‬\n      ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وبعقوبــة تعزيريــة لــأول والثالــث لقــاء مــا نســب إليهمــا‪ ،‬قبــض عليهــم‬\n      ‫يف مزرعــة بعــد ورود معلومــات عــن اتخاذهــا وكــرا ملروجــي املخــدرات‬\n      ‫فحــاول األول الهــرب مــن رجــال األمــن ومقاومتهــم‪ ،‬وبتفتيــش املزرعــة‬\n      ‫عثــر حتــت ســيارة متوقفــة بجوارهــم مباشــرة علــى حقيبــة بهــا كميــة‬\n      ‫مــن احلبــوب احملظــورة وإثبــات هويــة الثانــي وعثــر بداخــل املزرعــة علــى‬\n      ‫قــارورة مســكر‪ ،‬أثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة‬\n      ‫املرســلة لإلمفيتامــن وللكحــول‪ ،‬أقــر الثانــي أمــام احملكمــة بحيازتــه‬\n      ‫للحبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهــا وأنكــر قصــد‬\n      ‫الترويــج وأقــر األول والثالــث بالتهــم املنســوبة لهمــا ســوى محاولــة األول‬\n      ‫مقاومــة رجــال األمــن‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه‬\n      ‫وقــررت ســماع شــهادة شــهود محضــر القبــض فلــم جتــد فيهــا مــا يثبــت‬\n      ‫مــا أنكــره املدعــى عليهــم ممــا جــاء يف الدعــوى‪ ،‬قضــت احملكمــة‬\n      ‫بإدانــة املدعــى عليــه الثانــي بتعاطــي احلبــوب احملظــورة وحيازتهــا بقصــد‬\n      ‫التعاطــي وقــررت جلــده ســتني جلــدة دفعــة واحــدة وســجنه ملــدة عشــرة‬\n      ‫أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬كمــا قضــت‬\n\n‫‪183‬‬\n\f‫بإدانــة املدعــى عليهمــا األول والثالــث بشــرب املســكر وقــررت جلــد‬\n‫كل واحــد منهمــا حــد شــرب املســكر ثمانــن جلــدة دفعــة واحــدة علنــا‬\n‫وقضــت بإدانــة املدعــى عليــه الثالــث بحيــازة قــارورة مســكر بقصــد‬\n‫االســتعمال وقــررت ســجنه أربــع وعشــرين ســاعة كمــا قضــت ببــراءة‬\n‫املدعــى عليهمــا األول والثانــي مــن باقــي التهــم املنســوبة إليهمــا لعــدم‬\n‫كفايــة األدلــة‪ ،‬قنــع املدعــى عليهمــا األول والثالــث باحلكــم وعــارض‬\n‫املدعــى عليــه الثانــي واملدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n                              ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬رئيــس احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪3477434‬‬\n‫وتاريــخ ‪1434/02/17‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34390233‬وتاريــخ‬\n‫‪1434/02/17‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/03/17‬ه ـ حضــر‬\n‫ال مــن‪ ........-1 :‬ســعودي‬‫املدعــي العــام كمــا حضــر املدعــى عليهــم ك ً‬\n‫رقــم ســجله املدنــي (‪ ).....‬البالــغ مــن العمــر (‪)30‬عامـ ًا ‪ ،‬غيــر محصــن ‪،‬‬\n‫عاطــل عــن العمــل ‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ ‪ ،‬وأفــرج عنــه‬\n‫بتاريــخ ‪1433/11/24‬هــ‪ ........ -2 .‬ســعودي رقــم ســجله املدنــي (‪).....‬‬\n‫البالــغ مــن العمــر (‪)34‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬عاطــل عــن العمــل ‪،‬‬\n‫قبــض عليــه بتاريــخ ‪1433/11/20‬ه ـ ‪ ،‬وأحيــل لســجن محافظــة‬\n‫القطيــف اســتنادا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪.‬‬\n‫‪ ........-3‬ســعودي رقــم ســجله املدنــي (‪ ).....‬البالــغ مــن العمــر (‪)48‬عامـاً‪،‬‬\n‫محصــن ‪ ،‬عاطــل عــن العمــل ‪ ،‬قبــض عليــه بتاريــخ ‪1433/11/20‬هــ‪،‬‬\n\n                                                                                     ‫‪184‬‬\n\f      ‫وافــرج عنــه بتاريــخ ‪1433/11/23‬هــ‪ .‬وقــدم األول الئحــة دعــوى تتضمــن‬\n      ‫بــأن املدعــى عليهــم أنــه بتاريــخ ‪1433/11/19‬ه ـ ورد بــاغ للمديريــة‬\n      ‫العامــة ملكافحــة املخــدرات املتضمــن وجــود مزرعة بـ ـ ‪ ........‬يف القطيف‬\n      ‫يتواجــد بهــا العديــد مــن مروجــي املخــدرات ويتخذونهــا وكــرا لهــم‬\n      ‫وبحوزتهــم أســلحة‪ .‬وباالنتقــال للموقــع والدخــول بطريقــة تكتيكيــة‬\n      ‫والســيطرة علــى جميــع املوجوديــن وهــم خمســة اشــخاص كالتالــي‪:‬‬\n      ‫‪(.........-2 .........-1‬جــرى حفــظ االتهــام بحقــه مبوجــب أمــر احلفــظ رقــم‬\n      ‫‪ 54977‬وتاريــخ ‪1433/11/22‬هــ) ‪(.-3‬جــرى حفــظ االتهــام بحقــه‬\n      ‫مبوجــب أمــر احلفــظ رقــم ‪ 54976‬وتاريــخ ‪1433/11/22‬هــ) ‪.........-4‬‬\n      ‫‪ .........-5‬عندهــا حــاول املدعــو املقاومــة والهــرب فتــم الســيطرة عليــه‬\n      ‫ووجــد داخــل أحــد الســيارات التــي كانــت بجوارهــم مباشــرة علــى‬\n      ‫ســاح رشــاش كالشــنكوف يحمــل الرقــم (‪ ).....‬وبــه عــدد (‪)285‬‬\n      ‫مئتــن وخمســة وثمانــن طلقــة (مت بعثــه مــن قبــل مكافحــة املخــدرات‬\n      ‫لألدلــة اجلنائيــة إلكمــال الــازم) كمــا عثــر حتــت نفــس الســيارة علــى‬\n      ‫حقيبــة علــى شــكل حــزام للبطــن حتتــوي علــى عــدد (‪ )150‬مئــة‬\n      ‫وخمســن مــن حبــوب اإلمفيتامــن احملظــورة وعــدد (‪ )4‬أربــع حبــات‬\n      ‫زرقــاء اللــون مجهولــة كمــا عثــر بداخــل احلقيبــة علــى إثبــات ومحفظــة‬\n      ‫للمدعــو‪ ........‬كانــت داخــل نفــس احلقيبــة وعلــى قــارورة خمــر بنفــس‬\n      ‫املزرعــة مســتورده نــوع ‪ ........‬مملــوءة وجــرى التحفــظ علــى األشــخاص‬\n      ‫ونقلهــم ملكافحــة املخــدرات ‪ ،‬اثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم ‪4143‬وتاريخ‪1433/11/28‬ه ـ املتضمــن ثبــوت إيجابيــة العينــات‬\n      ‫املضبوطــة ملــادة اإلمفيتامــن املنبهــة واحملظــورة واملدرجــة يف اجلــدول‬\n      ‫الثانــي فئــة (ب) واملرفــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n\n\n‫‪185‬‬\n\f‫كمــا اثبــت التقريــر ذاتــه إيجابيــة قــارورة املســكر املضبوطــة ملــادة‬\n‫الكحــول اإليثيلــي وبنســبة مســكرة‪ .‬وبســماع أقــوال املدعــى عليــه‬\n‫األوليــة أقــر بحيازتــه للحبــوب احملظــورة بقصد االســتعمال وأنــه يتعاطى‬\n‫احلبــوب احملظــورة وأنــه ال عالقــة لباقــي املدعــى عليهــم‪ .‬وبســماع أقــوال‬\n‫املدعــى عليــه األوليــة أقــر بحيازتــه للمســكر املضبــوط وأفــاد بــأن‬\n‫الســاح املضبــوط يعــود لشــقيقه‪ .‬وبســماع أقــوال املدعــى عليــه أقــر‬\n‫بشــربه املســكر‪ .‬وباســتجواب املدعــى عليــه أقــر بحيازتــه حلبــوب‬\n‫اإلمفيتامــن املنبهــة واحملظــورة بقصــد التعاطــي وتعاطــي نوعهــا‪.‬‬\n‫وباســتجواب املدعــى عليــه أقــر بحيازتــه لقــارورة املســكر بقصــد‬\n‫الشــرب وشــرب املســكر‪ .‬وباســتجواب املدعــى عليــه أقــر بشــربه‬\n‫املســكر ومحاولتــه الهــرب خوفــا مــن رجــال الضبــط عنــد القبــض‬\n‫عليهــم كونــه ال يعلــم أنهــم رجــال أمــن وأنــه لــم يتعــد مــن املــكان ســوى‬\n‫املتريــن فقــط‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫الثاني (‪ )........‬بحيازة عدد (‪ )150‬مئة وخمســن من حبوب اإلمفيتامني‬\n‫احملظــورة بقصــد التعاطــي والترويــج وتعاطــي نوعهــا واتهــام املدعــى‬\n‫عليــه الثالــث (‪ )........‬بحيــازة قــارورة مســكر مــن نــوع ‪ ........‬بقصــد‬\n‫الشــرب وشــربه لــه واتهــام املدعــى عليــه األول (‪ )........‬مبحاولــة الهــروب‬\n‫مــن رجــال الضبــط اجلنائــي ومحاولتــه مقاومتهــم وشــرب املســكر ‪،‬‬\n‫وذلــك لألدلــة والقرائــن املوضحــة بالالئحــة وبالبحــث عــن ســوابقهم لــم‬\n‫يعثــر للمدعــى عليــه األول (‪ )........‬علــى ســوابق جنائيــة مســجلة وعثــر‬\n‫للمدعــى عليــه الثانــي (‪ )........‬ســابقة واحــدة وهــي اعتــداء وعثــر للمدعى‬\n‫عليــه الثالــث (‪ )........‬ســابقة واحــدة وهــي مضاربــة‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املذكــوران وهــم بكامــل أهليتهــم املعتبــرة شــرعا فعــل محــرم‬\n\n\n                                                                                      ‫‪186‬‬\n\f      ‫ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب مــا يلــي‪ :‬أوال‪ :‬بإثبــات مــا أســند‬\n      ‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬‫إلــى املدعــى عليــه ً‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪-1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )38‬مــن النظــام مــع مراعــاة مقتضــى املــادة ‪ 62‬مــن ذات النظــام‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إعمــاال ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )56‬مــن النظــام‪ .‬ثانيــا‪ :‬احلكــم علــى املدعــى عليــه (‪ ).....‬واملدعــى عليــه‬\n      ‫(‪ ).....‬بحــد شــرب املســكر لقــاء إقرارهمــا بشــرب املســكر‪ .‬ثالثــا‪:‬‬\n      ‫احلكــم علــى املدعــى عليهمــا (بعقوبــة تعزيرية تزجرهما وتــردع غيرهما‬\n      ‫لقــاء حيــازة املدعــى عليــه (‪ ).....‬للمســكر بقصــد الشــرب ولقــاء محاولة‬\n      ‫املدعــى عليــه الهــرب مــن رجــال الضبــط ومحاولتــه مقاومتهــم‪ .‬هــذه‬\n      ‫ا‬\n      ‫دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب املدعــى عليــه (‪ ).....‬قائ ـ ً‬\n      ‫مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ املذكــور داخــل‬\n      ‫مزرعــة يف (‪ ).....‬وإقــراري بشــرب املســكر ومحاولــة الهــرب مــن رجــال‬\n      ‫الضبــط اجلنائــي كل ذلــك صحيــح وحاولــت الهــرب لتفاجئــي بدخولهــم‬\n      ‫أمــا مــا ذكــره مــن محاولــة مقاومتهــم فغيــر صحيــح هكــذا أجــاب‬\n      ‫ا مــا ذكــره املدعــي العــام مــن القبــض‬     ‫كمــا أجــاب املدعــى عليــه قائـ ً‬\n      ‫علــي يف التاريــخ املذكــور داخــل مزرعــة يف (‪ ).....‬وأنــه عثــر بحوزتــي‬\n      ‫علــى (‪ )150‬مئــة وخمســن حبــة مــن حبــوب اإلمفيتامــن احملظــورة وأن‬\n      ‫قصــدي مــن حيازتهــا التعاطــي وأننــي أتعاطــى هــذه احلبــوب صحيــح أمــا‬\n      ‫قصــد الترويــج فإنــه غيــر صحيــح هكــذا أجــاب كمــا أجــاب املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ‬             ‫عليــه قائ ـ ً‬\n      ‫املذكــور داخــل مزرعــة يف (‪ ).....‬وأنــه عثــر بحوزتــي علــى قــارورة‬\n\n\n‫‪187‬‬\n\f‫مســكر مــن نــوع ســكواتش بقصــد الشــرب وشــربي لــه كل ذلــك‬\n‫صحيــح هكــذا أجــاب فجــرى ســؤال املدعــي العــام عــن حقيقــة محاولــة‬\n‫املدعــى عليــه مقاومــة رجــال الضبــط اجلنائــي وهــل شــرع يف ذلــك قــال‬\n‫أطلــب ســماع شــهادة رجــال الضبــط اجلنائــي فجــرى ســؤاله عــن بينتــه‬\n‫علــى وجــود قصــد الترويــج لــدى املدعــى عليــه قــال بينتي هي مــا تضمنته‬\n‫الالئحــة وهــو اآلتــي‪-1 :‬إقرارهــم حتقيقــا املنــوه عنــه واملــدون علــى‬\n‫الصفحــة رقم‪1.2‬واملرفــق لفــات رقــم (‪-2 )26-21‬إقــرار املدعــى عليــه‬\n‫مبحضــر ســماع األقــوال األوليــة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقم‪21‬واملرفــق لفــة رقــم (‪-3 )2‬إقــرار املدعــى عليــه مبحضــر ســماع‬\n‫األقــوال األوليــة املنــوه عنــه واملــدون علــى الصفحــة رقم‪23‬واملرفــق لفــة‬\n‫رقــم(‪-4 )3‬إقــرار املدعــى عليــه مبحضــر ســماع األقــوال األوليــة املنــوه‬\n‫عنــه واملــدون علــى الصفحــة رقم‪6‬واملرفــق لفــة رقــم(‪-5 )1‬مــا ورد يف‬\n‫محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى الصفحــة‬\n‫رقم‪2‬واملرفــق لفــة رقــم(‪-6 )2‬مــا ورد يف محضــر القبــض مــن وقائع املنوه‬\n‫عنهــا واملدونــة علــى الصفحــة رقم‪12‬واملرفقــة لفــة رقــم(‪-7 )1‬مــا ورد يف‬\n‫التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪-8 )49‬مــا‬\n‫ورد يف محضــر البــاغ املنــوه عنــه مبحضــر االســتدالل واملــدون علــى‬\n‫الصفحــة رقم(‪)2‬واملرفــق لفــة رقــم(‪-9 )2‬مــا ورد يف محضــر القبــض مــن‬\n‫وقائــع املنــوه عنهــا واملدونــة علــى الصفحــة رقــم(‪ )12‬واملرفقــة لفــة‬\n‫رقــم(‪ )1‬فأفهمــت املدعــي العــام بإبــاغ معــدي محضــر القبــض باحلضــور‬\n‫يف اجللســة القادمــة لــإدالء بشــهادتهم ويف جلســة أخــرى‬\n‫بتاريخ‪1434/05/20‬ه ـ حضــر املدعــي العــام واملدعــى عليهــم و كمــا‬\n‫حضــر للشــهادة ‪ ........‬وباستشــهاده قــال أشــهد بــاهلل أننــي حضــرت رفــق‬\n\n\n                                                                                   ‫‪188‬‬\n\f      ‫أعضــاء الفرقــة وقمنــا مبداهمــة مزرعــة يف (‪ ).....‬وقــد باغتنــا املدعــى‬\n      ‫عليهــم احلاضريــن وهــم جلــوس رفــق شــخص أو اثنــن آخريــن وفــور‬\n      ‫مشــاهدتنا قــام املدعــى عليــه وأشــار إلــى متحفــز ًا للمقاومــة وفــور علمــه‬\n      ‫بأننــا رجــال أمــن لــم يبــد أي مقاومــة ومتــت الســيطرة علــى املوجوديــن‬\n      ‫وبتفتيــش املوقــع عثــر علــى ســاح رشــاش داخــل ســيارة قدميــة كمــا عثــر‬\n      ‫علــى حقيبــة بهــا كميــة مــن احلبــوب واثبــات حتــت الســيارة وعثــر علــى‬\n      ‫قــارورة مســكر يف مســتودع هــذه شــهادتي فجــرى ســؤاله هــل قــام أي‬\n      ‫مــن املدعــى عليهــم مبحاولــة املقاومــة قــال ال واضــاف بــأن بقيــة زمالئــي‬\n      ‫أعضــاء الفرقــة ال تخــرج شــهادتهم عمــا ذكــرت وقــد انتقــل اثنــان منهــم‬\n      ‫خــارج املنطقــة وتعــذر حضــور البقيــة لظــروف العمــل وبعــرض الشــاهد‬\n      ‫وشــهادته علــى املدعــى عليهــم قــال كل واحــد منهــم بأننــي ال أقــول يف‬\n      ‫الشــاهد والشــهادة شــيئا واضــاف املدعــى عليــه بأننــي يف البدايــة لــم‬\n      ‫أكــن أعلــم أنهــم رجــال أمــن ويف جلســة أخــرى بتاريــخ ‪1434/06/04‬ه ـ‬\n      ‫حضــر املدعــي العــام وحضــر املدعــى عليهــم ‪ ........‬و ‪ ........‬و ‪........‬‬\n      ‫وبدراســة املعاملــة جــرى االطــاع علــى محضــر بــاغ يتضمــن وجــود‬\n      ‫مزرعــة بالــ(‪ ).....‬يتواجــد بهــا العديــد مــن مروجــي املخــدرات‬\n      ‫ويســتخدمونها وكــر ًا لهــم كمــا جــرى االطــاع علــى محضــر القبــض‬\n      ‫املــدون علــى صفحة(‪)12‬ملــف مرفــق لفــة (‪)1‬فوجدتــه موافقـ ًا ملــا جــاء يف‬\n      ‫دعــوى املدعــي العــام‪ .‬كمــا جــرى االطــاع علــى محضــر حتريــز مــدون‬\n      ‫علــى صحيفــة(‪ )13‬ملــف مرفــق لفــة (‪ )2‬واملتضمن ضبط مائة وخمســن‬\n      ‫حبــة وزجاجــة خمــر خارجــي كمــا جــرى االطــاع علــى محضــر ســماع‬\n      ‫أقــوال املدعــى عليــه (‪ ).....‬املــدون علــى صفحــة (‪ )21‬مــن ذات امللــف‬\n      ‫فوجدتهــا تتضمــن أن قصــده مــن احليــازة االســتعمال‪ ،‬كمــا جــرى‬\n\n\n‫‪189‬‬\n\f‫االطــاع علــى محاضــر ســماع أقــوال املدعــى عليهمــا األوليــة فلــم أجــد‬\n‫بهــا مــا يديــن املدعــى عليــه (‪ ).....‬باملقاومــة وال مــا يــدل علــى قصــد‬\n‫الترويــج لــدى املدعــى عليــه عمــاد ‪،‬كمــا جــرى االطــاع علــى محاضــر‬\n‫اســتجواب املدعــى عليهــم أمــام هيئــة التحقيــق املرفقــة علــى‬\n‫اللفات(‪)26-21‬فلــم أجــد يف اســتجواب املدعــى عليــه (‪ ).....‬مــا يفيــد‬\n‫اإلقــرار مبحاولــة املقاومــة كمــا تضمنــت إجابــة املدعــى عليــه (‪ ).....‬أن‬\n‫غرضــه مــن حيــازة احلبــوب االســتعمال الشــخصي ‪،‬كمــا جــرى االطالع‬\n‫علــى التقريــر الكيمــاوي الشــرعي املشــار لــه يف الئحــة الدعــوى العامــة‬\n‫فوجدتهــا كمــا ذكــر املدعــي العــام‪ .‬وبعــرض ذلــك علــى اجلميــع قــرر‬\n‫املدعــي العــام اكتفــاءه مبــا قــدم كمــا قــرر املدعــى عليهــم أنهــم ليــس‬\n‫لديهــم مــا يضيفــون‪ .‬فبنــاء علــى مــا تقــدم وحيــث تتلخــص دعــوى املدعــي‬\n‫العــام يف اتهــام املدعــى عليــه األول (‪ )........‬بشــرب املســكر ومحاولــة‬\n‫الهــروب مــن رجــال الضبــط اجلنائــي ومحاولــة مقاومتهــم‪ ،‬واتهــام املدعى‬\n‫عليــه الثانــي (‪ )........‬بحيــازة (‪ )150‬مئــة وخمســن حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي والترويــج وتعاطــي نوعهــا‪،‬‬\n‫واتهــام املدعــى عليــه الثالــث (‪ )........‬بشــرب املســكر وحيــازة قــارورة‬\n‫مســكر بقصــد الشــرب ‪،‬ويطلــب إثبــات مــا أســند إليهــم ومعاقبتهــم‬\n‫عليــه‪ .‬وألن هــذه احملكمــة مختصــة بنظــر الدعــوى بنــاء علــى املــواد‬\n‫(‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار املدعــى عليــه (‪).....‬‬\n‫بشــرب املســكر ومحاولــة الهــروب مــن رجــال الضبــط اجلنائــي ‪،‬وإلقرار‬\n‫املدعــى عليــه (‪ ).....‬بتعاطــي حبــوب اإلمفيتامــن احملظــورة وحيــازة‬\n‫(‪ )150‬مئــة وخمســن حبــة منهــا بقصــد التعاطــي ‪،‬وإلقــرار املدعــى عليه‬\n‫علــي بشــرب املســكر وحيــازة قــارورة مســكر بقصــد الشــرب ‪،‬وألن‬\n\n\n                                                                                   ‫‪190‬‬\n\f      ‫مــا أقدمــوا عليــه أفعــال محرمــة شــرع ًا لقولــه تعالــى (( يــا أيهــا الذيــن‬\n      ‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n      ‫فاجتنبــوه )) املائــدة‪ 90 :‬ولقولــه صلــى اهلل عليــه وســلم ((كل مس ــكر‬\n      ‫خمــر وكل خمــر حــرام )) رواه مســلم ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫((إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرها وشــاربها وحاملها واحملمولة‬\n      ‫إليــه )) رواه احلاكــم ‪،‬كمــا أن حيــازة وتعاطــي حبــوب اإلمفيتامــن‬\n      ‫احملظــورة أفعــال مجرمــة نظام ـ ًا وفق ـ ًا للفقــرة ( ‪ ) 2‬مــن املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وإلنــكار املدعــى عليــه‬\n      ‫(‪ ).....‬تهمــة محاولــة مقاومــة رجــال الضبــط اجلنائــي ولعــدم إقامــة املدعي‬\n      ‫العــام بينــة موصلــة علــى شــروع املدعــى عليــه يف الهــرب مــن رجــال‬\n      ‫ا‬\n      ‫الضبــط اجلنائــي أو مقاومتهــم وألن مجــرد محاولــة الهــرب ال يعــد فعـ ً‬\n      ‫موجبــا للتجــرمي خاصــة واملدعــى عليــه دفــع بأنــه لــم يكــن يعلــم أنهــم مــن‬\n      ‫رجــال األمــن بــل إن شــهادة رجــل الضبــط تضمنــت أن املدعــى عليــه فــور‬\n      ‫علمــه أننــا رجــال أمــن لــم يبــد أي مقاومــة ‪،‬وإلنــكار املدعــى عليــه أن‬\n      ‫قصــده مــن حيــازة احلبــوب احملظــورة الترويــج ولعــدم إقامــة املدعــي العــام‬\n      ‫بينــة موصلــة علــى قصــد االجتــار ‪ ،‬و الكميــة املضبوطــة مــن احلبــوب‬\n      ‫وإن كانــت كبيــرة إلــى حــد مــا لكنهــا تبقــى قرينــة لــم يوجــد مــا‬\n      ‫يســندها مــن شــهادة شــهود أو قبــض املدعــى عليــه وهــو يف حالــة تنبــئ‬\n      ‫بالترويــج أو العثــور علــى احلبــوب وهــي يف وضــع مهيــأ للبيــع أو العثــور‬\n      ‫علــى مبالــغ نقديــة ملفتــة مــع املدعــى عليــه وملــا لــم يحصــل شــيء مــن ذلــك‬\n      ‫وألن األصــل بــراءة املتهــم حتــى تثبــت إدانتــه وملــا تضمنتــه املــادة (‪ )3‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة مــن أنــه ال يجــوز توقيــع‬\n      ‫عقوبــة جزائيــة علــى أي شــخص إال بعــد ثبــوت إدانتــه ‪ ،‬ممــا يــدل علــى‬\n\n\n‫‪191‬‬\n\f‫أنــه ال مســوغ للعقوبــة ملجــرد وجــود التهمــة ‪ ،‬و ملــا نصــت عليــه املــادة‬\n‫(‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة مــن أن احملكمــة ال تتقيــد‬\n‫بالوصــف الــوارد يف الئحــة الدعــوى و أن عليهــا أن تعطــي الفعــل الوصــف‬\n‫الــذي يســتحقه لهــذا كلــه وبعــد االطــاع علــى املــواد (‪ )56،41‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة و ملــا قــرره جماهيــر أهــل‬\n‫العلــم مــن أن حــد شــرب املســكر ثمانــن جلــدة وهــو مــا انتهــى إليــه‬\n‫قــرار هيئــة كبــار العلمــاء باململكــة ذي الرقــم ‪ 53‬يف ‪1397/4/4‬ه ـ‬\n‫فقــد حكمــت باآلتــي ‪ :‬أو ًال ‪ :‬إدانــة املدعــى عليــه‪ ........‬بشــرب املســكر‬\n‫ومعاقبتــه علــى ذلــك بجلــده حــد شــرب املســكر ثمانــن جلــدة دفعــة‬\n‫واحــدة علن ـاً‪ .‬ثاني ـاً‪ :‬إدانــة املدعــى عليــه‪ ........‬بتعاطــي احلبــوب املنبهــة‬\n‫احملظــورة وحيــازة (‪ )150‬مئــة وخمســن حبــة مــن حبــوب اإلمفيتامــن‬\n‫احملظــورة بقصــد التعاطــي ومعاقبتــه علــى ذلــك بســجنه ســتة أشــهر‬\n‫وجلــده ســتني جلــدة دفعــة واحــدة ومنعــه مــن الســفر خــارج اململكــة مــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن‪ .‬ثالثـاً‪ :‬إدانــة املدعــى عليــه‬\n‫‪ ........‬بشــرب املســكر وحيازة قارورة مســكر بقصد الشــرب ومعاقبته‬\n‫علــى ذلــك بجلــده حــد شــرب املســكر ثمانــن جلــدة دفعــة واحــدة علنـ ًا‬\n‫و وســجنه أربعــة وعشــرين ســاعة حتتســب مــن مــدة إيقافــه تعزيــر ًا علــى‬\n‫احليــازة‪ .‬رابع ـاً‪ :‬بــراءة املدعــى عليــه ‪:‬مــن تهمــة محاولــة مقاومــة رجــال‬\n‫األمــن وبــراءة املدعــى عليــه مــن تهمــة حيــازة حبــوب اإلمفيتامــن‬\n‫احملظــورة بقصــد الترويــج لعــدم كفايــة األدلــة وبإعــان احلكــم قنــع بــه‬\n‫املدعــى عليهــم وقــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة‬\n‫حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n\n\n                                                                                          ‫‪192‬‬\n\f      ‫الســبت املوافــق ‪1434/07/15‬ه ـ حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫وبرفقهــا القــرار رقــم‪ 34252410‬يف‪1434/6/26‬ه ـ واملتضمــن‪ :‬لوحــظ‬\n      ‫أوالً‪ :‬أن املدعــى عليــه ‪ ........‬لديــه حيــازة مائــة وخمســن حبــة مــن حبــوب‬\n      ‫الكبتاجــون ومــا حكــم بــه فضيلتــه لقــاء ذلــك قليــل لكثــرة الكميــة‪.‬‬\n      ‫ثاني ـاً‪ :‬ورد ثالث ـ ًا يف احلكــم إدانــة املدعــى عليــه ‪ ........‬ولعــل صحتهــا‬\n      ‫التعديــل ذلــك يف موقعــة يف الضبــط والقــرار أ‪.‬ه ـ واســتجابة ملــا ذكــره‬\n      ‫أصحــاب الفضيلــة فقــد رجعــت عمــا حكمــت بــه يف الفقــرة ثاني ـ ًا مــن‬\n      ‫عقوبــة الســجن بحــق املدعــى عليــه وحكمــت بســجنه ســبعة أشــهر مــع‬\n      ‫بقــاء عقوبتــي اجللــد واملنــع مــن الســفر كمــا هــي‪ ،‬كمــا روعــي مــا جــاء‬\n      ‫يف املالحظــة الثانيــة وبإعــان احلكــم قنــع بــه املدعــى عليه وقــرر املدعي‬\n      ‫العــام أنــه ال يــزال علــى اعتراضــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                    ‫آله وصحبه وسلم‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/09/22‬ه ـ‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار رقــم ‪ 34288189‬يف‬\n      ‫‪1434/8/6‬ه ـ املتضمــن لوحــظ اوال‪ :‬ان مــا حكــم بــه فضيلتــه لقــاء‬\n      ‫احليــازة ال يــزال قليــل جــدا ثانيــا‪ :‬املالحظــة الثانيــة لــم يتــم التصحيــح‬\n      ‫كمــا اشــار فضيلتــه يف صــورة الضبــط أ‪.‬هــ‪ .‬واســتجابة ملــا ذكــره‬\n      ‫أصحــاب الفضيلــة يف املالحظــة األولــى فقــد رجعــت عمــا حكمــت‬\n      ‫بــه يف الفقــرة ثاني ـ ًا مــن عقوبــة الســجن بحــق املدعــى عليــه وحكمــت‬\n      ‫بســجنه عشــرة أشــهر مــع بقــاء عقوبتــي اجللــد واملنــع مــن الســفر كمــا‬\n      ‫هــي‪ ،‬كمــا روعــي مــا جــاء يف املالحظــة الثانيــة وبإعــان احلكــم قــرر‬\n\n\n‫‪193‬‬\n\f‫املدعــى عليــه اعتراضــه وطلــب رفــع املعاملــة دون تقــدمي الئحــة اعتراضية‬\n‫كمــا قــرر املدعــي العــام أنــه ال يــزال علــى اعتراضــه ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد‬\n‫فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف فقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫رقــم ‪ 35112419‬يف ‪1435/1/11‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n                                        ‫وللبيــان أحلــق يف ‪1435/1/18‬هــ‪.‬‬\n\n\n\n\n                                                                                 ‫‪194‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":182,"source_page_end":194,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1d6a28ee0733120ff017be3d200db5bda841566e726f99c2f01fba1b8e29c3ad","normalized_text_hash":"cf1786215cb5e3b13091145277f074ff16483da65e38f67f0e4f7fae1a3e2cbb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p182-342030072"},{"id":"12811dde-df4c-5738-82ff-30cbe841f8aa","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -قيادة السيارة حتت تأثير املخدر -مقاومة رجال األمن والهروب منهم -إدانة -تطبيق حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر .","document_number":"34252576","case_number":"3481135","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -قيادة السيارة حتت تأثير املخدر -مقاومة رجال األمن والهروب منهم -إدانة -تطبيق حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34252576 :‬تاريخه‪1434/06/26 :‬هـ‬\n                            ‫رقم الدعوى‪3481135:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34272982‬تاريخه‪1435/07/18:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬قيــادة الســيارة‬\n       ‫حتــت تأثيــر املخــدر ‪ -‬مقاومــة رجــال األمــن والهــروب منهــم ‪ -‬إدانــة‬\n       ‫‪ -‬تطبيــق حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن‬\n                                                     ‫واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول رســول اهلل صلــى اهلل عليــه وســلم‪( :‬كل مســكر خمــر وكل‬\n                                                                        ‫خمــر حــرام)‪.‬‬\n       ‫‪ -2‬جــاء يف مجمــوع الفتــاوى( ‪« :)358/23‬الــذي عليــه جمهــور األئمــة‬\n                     ‫أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا يحــد»‪.‬‬\n                                       ‫‪ -3‬اإلقرار حجة على صاحبه ومؤاخذ به‪.‬‬\n       ‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                          ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطيــه لــه وقيادتــه الســيارة‬\n       ‫حتــت تأثيــره ومقاومتــه لرجــال األمــن وهروبــه مــن الفرقــة القابضــة‪،‬‬\n       ‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحة‬\n\n‫‪195‬‬\n\f‫املخــدرات واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبته لقاء قيادة الســيارة‬\n‫حتــت تأثيــر املخــدر تقــرر مــن اجلهــة املختصــة واحلكــم عليــه بعقوبــة‬\n‫تعزيريــة لقــاء باقــي التهــم‪ ،‬حيــث إنــه مت اســتيقاف املدعــى عليــه بعــد‬\n‫مالحظتــه يخفــي شــيئ ًا حتــت مقعــد الســائق فعثــر علــى عقــب ســيجارة‬\n‫مخلــوط باحلشــيش املخــدر وبتفتيشــه شــخصيا عثــر علــى قطعــة مــن‬\n‫ا فتمــت الســيطرة عليــه‬    ‫احلشــيش املخــدر بعدهــا قــام بالهــرب مترج ـ ً‬\n‫وأثنــاء ذلــك قــام باالشــتباك مــع أفــراد الفرقــة ومقاومتهــم‪ ،‬وأثبــت‬\n‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة للحشــيش املخــدر‪ ،‬كمــا‬\n‫أقــر أمــام احملكمــة بتعاطــي احلشــيش وحيازة القطعــة املضبوطة بقصد‬\n‫التعاطي وبالهرب من الفرقة القابضة وأنكر حيازة ســيجارة احلشــيش‬\n‫والتعاطــي منهــا ‪ ،‬مــن املقــرر شــرع ًا أن اإلقــرار حجــة علــى صاحبــه‬\n‫ومؤاخــذ بــه والقرائــن القويــة ال تتــرك مجــاال لعــدم إثبــات إدانتــه بحيــازة‬\n‫ســيجارة احلشــيش لقصــد التعاطــي باإلضافــة إلــى شــهادة الشــهود التــي‬\n‫أكــدت اإلدانــة مبــا هــو مدعــى عليــه بــه‪ ،‬وحيــث إن املدعــى عليــه مــن‬\n‫أربــاب الســوابق‪ ،‬فقضــت احملكمــة بجلــده حــد املســكر ثمانــن جلــدة‬\n‫دفعــة واحــدة وســجنه ملــدة اثنــي عشــر شــهر ًا ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني كمــا قــررت تعزيــره لقــاء باقــي التهــم بســجنه‬\n‫ســبعة أشــهر وجلــده ثالثــن جلــدة تكــرر عليــه ثــاث مــرات وأفهمــت‬\n‫املدعــى عليــه بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر املخــدر تقــرر‬\n‫مــن اجلهــة املختصــة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n             ‫عليــه وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                       ‫‪196‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك بنــاء علــى قــرار النــدب الصــادر مــن املجلــس األعلــى للقضــاء‬\n      ‫برقــم ‪ 34/3863‬وتاريــخ ‪ 1434 / 3 / 8‬ه ـ ـ وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبوك‪/‬املكلــف برقــم‬\n      ‫‪ 3481135‬وتاريــخ ‪ 1434/02/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 34409273‬وتاريــخ ‪ 1434/02/18‬ه ـ ففــي يــوم االثنــن املوافــق‬\n      ‫‪ 1434/03/23‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا‬\n      ‫حضــر املدعــي العــام ‪ ........‬املكلــف باالدعــاء العــام مــن قبــل فــرع هيئــة‬\n      ‫التحقيــق واالدعــاء العــام مبنطقــة تبــوك مبوجــب اخلطــاب رقــم ‪........‬‬\n      ‫بتاريــخ ‪ 1433 / 9/ 5‬هـ ـ وحضــر حلضــوره املدعــى عليــه ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬فادعــى قائــا يف حتريــر‬\n      ‫دعــواه‪ :‬أنــه بتاريــخ ‪1434/01/ 8‬ه ـ توافــرت معلومــات لديهــم مــن أحــد‬\n      ‫املصــادر الســرية عــن املدعــى عليــه أنــه يحتــاز علــى مواد مخدرة ويســتقل‬\n      ‫ســيارة مــن نــوع (‪ ).....‬حتمــل لوحــة رقــم (‪ )............‬ومت مشــاهدته بجــوار‬\n      ‫محطــة (‪ )........‬علــى طريــق عمــان وبتوجــه الدوريــة الرســمية اتضــح أن‬\n      ‫الشــخص الــذي بداخــل الســيارة هــو املدعى عليه ولوحــظ عليه االرتباك‬\n      ‫ونــزل مــن الســيارة وقــام بإخفــاء شــيء مــا حتــت مقعــد الســائق وبالتقــاط‬\n      ‫مــا قــام برميــه اتضــح أنــه عبــارة عــن عقــب ســيجارة يشــتبه أن يكــون‬\n      ‫مخلــوط باحلشــيش املخــدر بلــغ وزنه (‪ )420‬أربعمائة وعشــرين مليجرام ًا‬\n      ‫وبطلــب الهويــة الوطنيــة ذكــر أنــه ال يحملهــا وذكــر أنــه وبتفتيشــه‬\n      ‫شــخصيا عثــر بداخــل جيــب جاكيتــه علــى قطعــة صغيــره يشــتبه أن‬\n\n‫‪197‬‬\n\f‫تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ 30‬ملــج) ثالثــن مليجرام ـ ًا‬\n‫بعدهــا أبــدى املذكــور النــدم واســتعد بالتعــاون للقبــض علــى أحــد‬\n‫ا‬ ‫مروجــي املخــدرات وأثنــاء حديثــه بالهاتــف النقــال قــام بالهــرب مترجـ ً‬\n‫ومت مالحقتــه مــن قبــل الفرقــة وبعــد حوالــي مائــة متــر مــن موقــع القبــض‬\n‫مت الســيطرة عليــه وأثنــاء ذلــك قــام باالشــتباك مــع أفــراد الفرقــة‬\n‫ومقاومتهــم بدفعهــم باأليــدي ونتــج عنهــا إصابــة الفــرد رقــم (‪ )........‬ومت‬\n‫نقلــه للمستشــفى فتــم إحالــة املذكــور ملقــر إدارة مكافحــة املخــدرات‬\n‫بتبــوك جــرى ضبــط إفــادة أفــراد الفرقــة القابضــة الســتيضاح بعــض‬\n‫النقــاط الــواردة يف احملضــر املعــد مــن قبلهــم وأفــادوا أن املذكــور‬\n‫شــاهده الفــرد ‪ ........‬و ‪ .........‬رقيــب رقــم (‪ .)........‬وهــو يقــوم بإطفــاء‬\n‫الســيجارة ورميهــا حتــت مقعــد الســائق وكان يتعاطــى منهــا قبــل‬\n‫القبــض عليــه ورائحتهــا متــأ املركبــة ‪ ،‬وأن ســبب هروبــه هــو ادعــاؤه‬\n‫التعــاون معهــم لكــن غافــل الفرقــة وقــام بالهــرب جــرى إيقــاف املدعــى‬\n‫عليــه اســتناد ًا للفقــرة (‪ )11‬مــن القــرار الــوزاري رقم (‪ ، )1900‬واســتناد ًا‬\n‫لتعميــم وزيــر الداخليــة رقــم (‪ )45781‬وتاريــخ ‪1431/7/22‬ه ـ لوجــود‬\n‫ســابقة مخــدرات وباســتجواب املدعــى عليــه ‪ /‬أقــر بأنــه قــام بالهــرب مــن‬\n‫الفرقــة القابضــة وذلــك بعــد محادثتــه لوالدتــه‪ .‬صــدر بحــق رجــل األمــن‬\n‫اجلنــدي رقــم (‪ )........‬التقريــر الطبــي النهائــي الصــادر مــن مستشــفى ‪.....‬‬\n‫بتبــوك املتضمــن (ادعــاء مضاربــة ‪ ،‬وجــود ســحجات علــى اليــد اليمنــى‬\n‫و القــدم اليمنــى واليســرى والركبــة اليســرى وباجلانــب األميــن يف البطــن‬\n‫‪ ،‬واألداة املســتخدمة صلبــة غيــر حــادة ‪ ،‬ومــدة الشــفاء أربعــة أيــام مــا لــم‬\n‫حتــدث مضاعفــات)‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‬\n‫‪ )........‬الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n\n\n                                                                                       ‫‪198‬‬\n\f      ‫الشــرعية بصحــة تبــوك إيجابيــة مســتخلص العينــة لعقــب ســيجارة‬\n      ‫للحشــيش املخــدر ‪ ،‬وايجابيــة العينــة للحشــيش املخــدر كمــا أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم ‪ ........‬الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بصحــة تبــوك ‪ ،‬إيجابيــة عينــة‬\n      ‫الــدم للمتهــم أليــض املــادة الفعالــة للحشــيش املخــدر وهــو مــن املــواد‬\n      ‫احملظــورة اخلاضعــة للرقابــة واملنــوه عنهــا باجلــداول امللحقــة بالنظــام يف‬\n      ‫تعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء‬\n      ‫وزيــر الداخليــة رقــم (‪ )89400/19‬وتاريــخ ‪1426/10/25‬ه ـ وقــد أســفر‬\n      ‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بحيــازة عقــب ســيجارة‬\n      ‫مخلــوط باحلشــيش املخــدر بلــغ وزنهــا (‪ )420‬أربعمائــة وعشــرون جرامـ ًا‬\n      ‫وقطعــة مــن احلشــيش املخــدر بلــغ وزنهمــا اإلجمالــي (‪ )30‬ثالثــون‬\n      ‫مليجــرام بقصــد التعاطــي ‪ ،‬وتعاطيــه مــن ذات الكميــة ‪،‬ولنوعهــا يف‬\n      ‫الســابق ‪ ،‬ومقاومتــه رجــال األمــن أثنــاء تأديــة مهــام وظيفتهــم ‪ ،‬وهروبــه‬\n      ‫مــن الفرقــة القابضــة ‪ ،‬وقيادتــه للســيارة حتــت تأثيــر املخــدر وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -.1 :‬اعترافــه بالهــرب مــن الفرقــة القابضــة ‪،‬‬\n      ‫املنــوه عنــه‪ -‬املرفقــة برقــم( ‪ - 2 )16-15-14‬مــا ورد مبحضــر البــاغ‬\n      ‫والقبــض والتفتيــش املرفــق بالصفحــة رقــم(‪ )1‬مــن ملــف االســتدالل‬\n      ‫املرفــق برقــم(‪ -3 )1‬مــا ورد يف محضــر االســتيضاح الــوارد علــى محضــر‬\n      ‫القبــض ‪ -‬املنــوه‪ -‬عنــه املرفــق لفة رقم (‪ -4 )19‬التقريرين الكيميائيني‬\n      ‫الشــرعيني املرفقــن لفــة رقــم(‪ -5 .)31-30‬التقريــر الطبــي النهائــي‬\n      ‫الصــادر بحــق رجــل األمــن املرفــق لفــة رقــم (‪ )20‬وحيــث أن مــا أقــدم‬\n      ‫عليــه املذكــور فعــل محــرم شــرع ًا ومجــرم ومعاقــب عليــه نظام ـ ًا ‪،‬‬\n      ‫اســتناد ًا للفقــرة (الثانيــة) مــن املــادة( الثالثــة) مــن نظــام مكافحــة‬\n\n\n‫‪199‬‬\n\f‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم ( م‪)39/‬‬\n‫وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلب‪-1:‬إثبــات مــا أســند إليه‪-2.‬احلكــم‬\n‫عليــه بعقوبــة تعزيريــة لقــاء مقاومتــه رجــال األمــن وهروبــه مــن الفرقــة‬\n‫القابضة‪-3.‬احلكــم عليــه بالســجن‪ ،‬لقــاء مــا أســند إليــه اســتناد ًا للفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليه‪-4.‬احلكــم عليــه مبنعــه مــن الســفر خارج اململكة ‪ ،‬اســتناد ًا‬\n‫للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املشــار إليــه أعــاه‪ -5.‬تشــديد العقوبــة بحقــه ‪ ،‬اســتناد ًا لتعميــم‬\n‫وزيــر الداخليــة رقــم (‪ )36717/2/5/1‬وتاريخ ‪1431/6/11‬هـ العتدائه‬\n‫علــى رجــل أمــن أثنــاء تأديــة عملــه‪ -6.‬إفهــام املذكــور بــأن عقوبتــه لقــاء‬\n‫قيادتــه الســيارة حتــت تأثيــر املســكر عائــد للجهــة املختصــة هــذه‬\n‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح كلــه جملــة وتفصيــا‬\n‫هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــك بينــه علــى دعــواك‬\n‫اجــاب بقولــه نعــم لــدي واطلــب مهلــة إلحضارهــا هكــذا أجــاب ويف‬\n‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام‬\n‫عــن البينــة التــي وعــد بإحضارهــا أجــاب بقولــه لقــد أحضــرت للشــهادة‬\n‫أطلــب ســماع مــا لديــه هكــذا أجــاب ويف هــذه اجللســة حضــر ‪........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬واملولــود عــام‬\n‫‪1405‬هـ ـ ويعمــل لــدى إدارة مكافحــة املخــدرات مبنطقــة تبــوك وليــس‬\n‫بينــه وبــن املدعــى عليــه أي عالقــة كمــا أفــاد وبســؤاله عمــا لديــه مــن‬\n‫شــهادة أجــاب بقولــه أشــهد هلل تعالــى أنــه جــاءت لــإدارة إخباريــة عــن‬\n‫وجــود ســيارة لونهــا أبيــض وأنــه يوجــد بهــا شــخص يحــوز مــواد مخــدرة‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫ومتجــه إلــى طريــق عمــان وحيــث أنــي كنــت ضمــن الفرقــة القابضــة‬\n      ‫املكلفــة يف امليــدان جاءنــا البــاغ عنهــا فتوجهنــا لطريــق ‪ ........‬فوجدنــا‬\n      ‫الســيارة متوقفــة يف محطــة ‪........‬ويقــوم ســائقها بتعبئــة الســيارة بالوقــود‬\n      ‫طبعــا البــاغ يأتــي بلــون الســيارة ونوعهــا ورقــم لوحتهــا والــذي يتلقــى‬\n      ‫البــاغ رئيــس الفرقــة كذلــك لــم أعــرف نــوع الســيارة ألنــه ليــس لــدي‬\n      ‫معرفــة باألنــواع اجلديــدة مــن الســيارات وعنــد توقفــه لتعبئــة الوقــود‬\n      ‫ذهبــت أنــا والرقيــب ‪ .....‬للســيارة وعنــد اقترابنــا منــه قــام بإخفــاء شــيء‬\n      ‫حتــت مقعــده الــذي يجلــس عليــه وقــد رأيــت ذلــك ألننــي أتيــت مــن جهــة‬\n      ‫الراكــب ثــم أتينــا لــه مــن جهــة بــاب الســائق وطلبنــا منــه النــزول فنــزل‬\n      ‫وقــام زميلــي الرقيــب ‪........‬بإخــراج مــا قــام بإخفائــه حتت مقعــده فوجدنا‬\n      ‫أنــه عقــب ســيجارة ويشــتبه أنهــا مخلوطــة باحلشــيش وهــي ســيجارة‬\n      ‫ملفوفــة بــورق اللــف املســتخدم يف تعاطــي احلشــيش وقــام أحــد الزمــاء‬\n      ‫من الدورية األخرى بتفتيشــه تفتيشــا شــخصيا وعثر يف جيب اجلاكيت‬\n      ‫علــى قطعــة ســوداء صغيــرة يشــتبه أنهــا مــن احلشــيش وعندمــا اجتمــع‬\n      ‫النــاس قمنــا بأخــذه لــإدارة وعندمــا كنــا يف احلــوش التابــع لــإدارة قــال‬\n      ‫إن جميــع مــا ضبــط معــي عائــد لــي وأنــا نــادم علــى مــا فعلــت وأريــد أن‬\n      ‫أتعــاون معكــم لإلطاحــة بأحــد املروجــن وقمنــا بفــك القيــود عنــه‬\n      ‫وطلــب منــا أن يواعــد املــروج داخــل حــي ‪........‬لكننــا رفضنــا وطلبنــا منــه‬\n      ‫أن يواعــده عنــد مــكان عــام كأن يكــون بجانــب محطــة أو مــا شــابه‬\n      ‫ذلــك فقــام باالتصــال وأثنــاء اتصالــه اســتغفلنا وهــرب وقمنــا باللحــاق بــه‬\n      ‫وهــرب ملســافة بعيــدة ونحــن جنــري خلفــه وحلــق بــه زميلنــا ‪ .....‬وقــام‬\n      ‫املدعــى عليــه بالتشــابك معــه باأليــدي وعلــى أثــر ذلك حصلــت اإلصابات‬\n      ‫بزميلــي ‪ ........‬واســتطعنا بعــد ذلــك القبــض عليــه وإيداعــه التوقيــف‬\n\n\n‫‪201‬‬\n\f‫هكــذا أشــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه أجــاب‬\n‫بقولــه الشــاهد ال أعرفــه وال أقــدح فيــه ومــا ذكــره مــن أنهــم عثــروا علــى‬\n‫عقــب ســيجارة مخلوطــة باحلشــيش حتــت مقعــد الســائق الــذي أجلــس‬\n‫عليــه صحيــح لكنهــا ليســت لــي ألن الســيارة مــن مكتــب تأجيــر ومــا‬\n‫ذكــره مــن أنهــم عثــروا علــى قطعــة ســوداء داخــل اجلاكيــت فصحيــح‬\n‫أيضــا واجلاكيــت يعــود لــي وال أعلــم هــل هــي حشــيش أم ال واجلاكيــت‬\n‫لــه ثــاث ســنوات عنــدي وصحيــح أننــي هربــت منهــم عنــد اإلدارة وقامــوا‬\n‫باللحــاق بــي ولــم أتشــابك باأليــدي مــع العســكري الــذي حلــق بــي بــل هــو‬\n‫مســكني وســقط علــي ولــم أقــم مبقاومتــه هكــذا أجــاب وبســؤال‬\n‫املدعــي العــام هــل لديــك مزيــد بينــة أجــاب بقولــه نعــم أطلــب مهلــة ثانيــة‬\n‫إلحضارهــا هكــذا أجــاب وبســؤاله عــن املعدلــن للشــاهد أســتعد‬\n‫بإحضارهــم يف اجللســة القادمــة ويف جلســة أخــرى حضــر املدعــي العــام‬\n‫واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة التــي وعــد بهــا أجــاب‬\n‫بقولــه أحضــرت للشــهادة أطلــب ســماع مــا لديــه هكــذا أجــاب ويف هــذه‬\n‫اجللســة حضــر الشــاهد ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم ‪ ........‬واملولــود عــام ‪ 1408‬هـ ـ ويســكن حــي ‪ .......‬بتبــوك ويعمــل‬\n‫لــدى إدارة مكافحــة املخــدرات مبنطقــة تبــوك وليــس بينــه وبــن املدعــى‬\n‫عليــه أي عالقــة كمــا أفــاد وبســؤاله عمــا لديــه من شــهادة أجــاب بقوله‪:‬‬\n‫أشــهد هلل تعالــى أننــا قبضنــا علــى املدعــى عليــه يف محطــة علــى طريــق‬\n‫‪ ........‬وكان بحوزتــه مؤثــرات عقليــة ال أعــرف مــا هــي لكونــي لــم‬\n‫أشــاهدها وكان دوري هــو أخــذ املدعــى عليــه مــع بقيــه الفرقــة ملقــر‬\n‫اإلدارة وهنــاك يف احلــوش التابــع لــإدارة قــام املدعــى عليــه بالبــكاء‬\n‫ويقــول أنــه نــادم علــى مــا فعــل وتائــب هلل وأن والدتــه مريضــة ويطلــب أن‬\n\n\n                                                                                        ‫‪202‬‬\n\f      ‫يكــون متعاونــا معنــا لإلطاحــة باملروجــن وبنــاء علــى ذلــك جــرى فــك‬\n      ‫قيــوده وقــال لنــا أنــا مســتعد لإلطاحــة باملــروج والــذي يســكن حــي ‪........‬‬\n      ‫وطلــب أن يذهــب معــه أحــد أعضــاء الفرقــة فرفضنــا لكــون املــكان‬\n      ‫داخــل اإلحيــاء وهــذا قــد يعرضنــا للخطــر فطلبنــا منــه أن يواعــده خــارج‬\n      ‫احلــي عنــد مــكان عــام إمــا محطــة أو أنــه يف شــارع رئيســي واســتغفلنا‬\n      ‫وهــو يكلــم باجلــوال وهــرب وحلقتــه أنــا ومســكته عنــد شــارع ‪........‬‬\n      ‫وكان يقاومنــي كل مــا حاولــت اإلمســاك بــه حتــى أمســكته فتشــابك‬\n      ‫معــي باأليــدي ليفلــت منــي لكنــي متكنــت مــن اإلمســاك بــه وحصلــت‬\n      ‫بــي إصابــة عنــد محاولــة اإلمســاك بــه حيــث ســقطت علــى االزفلــت‬\n      ‫وحصــل بــي كشــط يف يــدي والســقوط كان منــي أنــا ولــم يقــم هــو‬\n      ‫بدفعــي هــذا مــا لــدي هكــذا شــهد وبعــرض الشــاهد وشــهادته علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه الشــاهد ال أعرفــه وال أقــدح فيــه ومــا ذكــره‬\n      ‫أنــه ضبــط معــي مؤثــرات عقليــة فقــد أجبــت عــن صحــة ذلــك يف جوابــي‬\n      ‫علــى شــهادة الشــاهد األول ولكنهــا ليســت لــي والســيارة باســم وهــو‬\n      ‫جــاري يف ‪........‬أخذتهــا منــه ألقــوم بإيصــال أهلــي حلــي ‪........‬وضبطــت يف‬\n      ‫الســيارة عقــب ســيجارة ذكــروا أنهــا مخلوطــة باحلشــيش كمــا عثــروا‬\n      ‫يف جيــب اجلاكيــت علــى قطعــة صغيــرة و فعــا هــذه القطعــة الصغيــرة‬\n      ‫عائــدة لــي بقصــد التعاطــي وصحيــح أننــي هربــت منهــم وأمســك بــي‬\n      ‫هــذا الشــاهد ولكنــي لــم أتشــابك معــه يف األيــدي وهــم مــن قالــوا لــي‬\n      ‫نريــد أن تطيــح لنــا بــ‪ ........‬ألنهــم وجــدوا أن الســيارة مســجلة باســمه‬\n      ‫والــذي أعرفــه أنــه شــخص ليــس لــه يف هــذه األمــور ولــم أقتــرح عليهــم أن‬\n      ‫أتعــاون معهــم لإلطاحــة باملروجــن ولــم يحصــل منــي بــكاء أو أنــي قلــت‬\n      ‫لهــم نــادم وإمنــا قلــت لهــم فكونــي وأن الســيارة ليســت لــي وصحيــح أننــي‬\n\n\n‫‪203‬‬\n\f‫كنــت أتعاطــى احلشــيش املخــدر يف الســابق ولــم أتعاطــى ممــا ضبــط‬\n‫بحوزتــي ألنــي تركــت تعاطــي احلشــيش منــذ زمــن هكــذا أجــاب‬\n‫وبســؤال املدعــي العــام هــل لديــك مزيــد بينــة أجــاب بقولــه ليــس لــدي‬\n‫ســوى مــا قدمــت هكــذا أجــاب وبســؤاله عــن املعدلــن لبينتــه أجــاب‬\n‫بقولــه أن الشــاهد أفادنــي بأنهــم ال يســتطيعون احلضــور لهــذا اليــوم‬\n‫لكونهــم يف مهمــة ميدانيــة وأطلــب مهلــة أخيــرة إلحضــار املعدلــن‬\n‫للبينــة هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبســؤال املدعــي العــام عــن املعدلــن للبينــه أجــاب بقولــه أحضــرت‬\n‫ألجــل ذلــك كال مــن ‪........‬ســعودي مبوجــب الهويــة الوطنيــة رقــم ‪........‬‬\n‫و‪ ........‬ســعودي مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬أطلــب ســماع مــا‬\n‫لديهــم هكــذا أجــاب وحضــر يف هــذه اجللســة و املبينــة بياناتهمــا بعاليــه‬\n‫والتــي تأكــدت منهــا وبســؤالهما عــن عدالــة الشــاهدين أجابــا بقولهمــا‬\n‫أنهمــا زمــاء يف العمــل وهمــا أهــل ثقــة وعدالــة هكــذا أجابــا فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أقــر بــه املدعــى عليــه مــن حيازتــه‬\n‫لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا اإلجمالــي ( ‪ ) 30‬ثالثــن‬\n‫مليجرامــا بقصــد التعاطــي كمــا أقــر باســتخدامه للحشــيش املخــدر‬\n‫وحيــث إن اإلقــرار حجــة علــى صاحبــه ومؤاخــذ بــه وحيــث أنكــر‬\n‫حيازتــه عقــب ســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا ( ‪) 420‬‬\n‫أربعمائــة وعشــرين مليجرام ـ ًا وحيــث أقــر بوجودهــا بالســيارة وأقــام‬\n‫املدعــي العــام البينــة علــى وجودهــا بالســيارة التــي كان يركبهــا إال أنــه‬\n‫لــم يــأت بهــذه البينــة أنــه قــام برميهــا حتــت مقعدتــه إال مــا جــاء يف شــهادة‬\n‫أنــه رأى املدعــى عليــه وهــو يرمــي بشــيء حتــت مقعده وأنه عنــد التفتيش‬\n‫حتــت مقعــده وجــدوا عقــب الســيجارة وأنــه أقــر لديهــم بــأن مــا ضبــط‬\n\n\n                                                                                           ‫‪204‬‬\n\f      ‫كان لــه وهــذه قرينــة قويــة جــدا ويقويهــا مــا شــهد بــه مــن بــكاءه وندمــه‬\n      ‫وإبــداءه الرغبــة بالتعــاون معهــم يف اإلطاحــة باملروجــن كمــا يقويهــا‬\n      ‫هروبــه مــن رجــال األمــن بــل إن مــن أقــوى القرائــن التحليــل الــذي عمــل‬\n      ‫لعينــة مــن البــول للمدعــى عليــه وثبــت إيجابيتهــا أليــض املــادة الفاعلــة‬\n      ‫للحشــيش املخــدر واملرصــود علــى اللفــة (‪ )28‬مــن لفــات املعاملــة كمــا‬\n      ‫أنــه يزيــد مــن قوتهــا ذكــره أن الســيارة وعنــد هيئــة التحقيــق كمــا يف‬\n      ‫اللفــة (‪ )15‬مــن املعاملــة ذكــر أن الســيارة باســم ‪........‬ومجمــوع هــذه‬\n      ‫القرائــن مــع مــا عليــه مــن ســابقة مــن جنــس هــذه الدعوى وإقــراره بحيازة‬\n      ‫نوعهــا وتعاطيــه لنوعهــا كل ذلــك ال يتــرك مجــاال لعــدم إثبــات إدانتــه‬\n      ‫بحيــازة عقــب الســيجارة املوصوفــة بعاليــه بقصــد التعاطــي ألن هــذه‬\n      ‫الكميــة القليلــة وكونهــا عقــب ســيجارة دل علــى أن حيازتهــا للتعاطــي‬\n      ‫ليــس إال ويــدل عليــه أيضــا التحليــل الــذي أشــير إليــه بعاليــه ممــا يــدل‬\n      ‫علــى قيادتــه أيضــا للســيارة حتــت تأثيــر املخــدر وملــا روى ابــن عمــر رضــي‬\n      ‫اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم قــال (كل مســكر‬\n      ‫خمــر وكل خمــر حــرام) قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف‬\n      ‫احلشيشــة (الــذي عليــه جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل‬\n      ‫ـاء علــى‬‫الصــواب أن آكلهــا يحــد) مجمــوع الفتــاوى ‪ 358/23‬وبنـ ً‬\n      ‫املــادة(‪ )41‬الفقــرة (‪ )1‬واملــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة و لوجــود ســابقة مخــدرات علــى املدعــى‬\n      ‫عليــه بتاريــخ ‪ 1433 / 4 / 6‬هـ ـ كمــا هــو مرصــود بــأوراق املعاملــة وهــذا‬\n      ‫ممــا يوجــب التشــديد عليــه يف العقوبــة وألن هروبــه مــن رجــال األمــن فيــه‬\n      ‫تأمــن الســبل وحتفــظ احلقــوق‬  ‫متــرد علــى قــوة الســلطان وهيبتــه التــي بهــا ّ‬\n      ‫ويعــم االســتقرار وألن مــن هيبــة الســلطان هيبــة نوابه وعســكره فهروبه‬\n\n\n‫‪205‬‬\n\f‫هــذا يســتحق بــه التعزيــر ردعــا لــه وزجــرا لغيــره مــن التجــرؤ علــى رجــال‬\n‫ـدي إدانــة‬\n         ‫األمــن بعــدم االنصيــاع لهــم والهــروب منهــم لــذا فقــد ثبــت لـ َّ‬\n‫املدعــى عليــه بحيازتــه قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا اإلجمالــي‬\n‫( ‪ ) 30‬ثالثــون مليجــرام وحيازتــه لعقــب ســيجارة مخلوطــة باحلشــيش‬\n‫املخــدر بلــغ وزنهــا ( ‪ ) 420‬أربعمائــة وعشــرون جرام ـ ًا بقصــد التعاطــي‬\n‫وتعاطيــه للحشــيش املخــدر كمــا ثبــت لــدي إدانتــه مبقاومتــه لرجــال‬\n‫األمــن وهروبــه منهــم وقيادتــه للســيارة حتــت تأثيــر املخــدر وقــررت مايلي‬\n‫أوال‪ :‬جلــد املدعــى عليــه احلــد ثمانــن جلــدة دفعــة واحــدة لقــاء تعاطــي‬\n‫احلشــيش املخــدر ثانيــا‪ :‬تعزيــر املدعــى عليــه بســجنه مــدة اثنــي عشــر‬\n‫شــهرا يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة لقــاء حيازتــه‬\n‫ملــا أشــير إليــه بعاليــه مــن احلشــيش املخــدر ثالثــا‪ :‬منــع املدعــى عليــه مــن‬\n‫الســفر خــارج اململكــة مــدة ســنتني رابعــا‪ :‬تعزيــر املدعــى عليــه بســجنه‬\n‫ســبعة أشــهر تبــدأ بعــد ماحكــم بــه ثانيــا لقــاء مقاومتــه لرجــال األمــن‬\n‫وهروبــه منهــم خامســا‪ :‬تعزيــر املدعــى عليــه بجلــده ثالثني جلــدة تتكرر‬\n‫عليــه ثــاث مــرات بــن كل إيقــاع واآلخــر خمســة عشــر يومــا لقــاء‬\n‫هروبــه مــن رجــال األمــن ومقاومتهــم وأفهمــت املدعــى عليــه بــأن عقوبتــه‬\n‫لقــاء مخالفتــه نظــام املــرور عائــد للجهــة املختصــة وبذلــك حكمــت‬\n‫وبعــرض حكمــي هــذا علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫باحلكــم وأمــا املدعــي العــام فقــد قــرر اعتراضــه مكتفيـ ًا مبــا جــاء يف‬\n‫أوراق املعاملــة عــن تقــدمي الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                   ‫على نبينا و آله وصحبه وسلم‪ .‬حرر يف ‪ 1434/06/20‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة‬\n‫يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة مــن‬\n\n\n                                                                                          ‫‪206‬‬\n\f      ‫فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪ 34409273‬وتاريــخ‬\n      ‫‪1434/07/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫يف احملكمــة الشــيخ ‪ ....‬برقــم ‪ 34252576‬وتاريــخ ‪1434/06/26‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد املدعــي يف قضيــة مخــدرات‬\n      ‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬قررنــا املصادقــة علــى احلكــم‬\n      ‫مــع تنبيــه فضيلتــه علــى تعديــل وزن عقــب الســيجارة يف احلكــم إلــى‬\n      ‫مليجــرام بــد ًال مــن جــرام ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                             ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":195,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ba2c07b31084e20f27f0109d1f0d577addb5152454fa1992f87cac36043fc67","normalized_text_hash":"c59861343d1365f6e73cb97c4f9fe6e481683975f5aa73f3acc3782c566fd51e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p195-34252576"},{"id":"3515b73d-5b4d-502b-bb62-8e546e4f5847","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -قيادة السيارة حتت تأثيرها -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"34167139","case_number":"3483974","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/21","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -قيادة السيارة حتت تأثيرها -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34167139 :‬تاريخه‪1434/03/21 :‬هـ‬\n                       ‫رقم الدعوى‪3483974:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34254934‬تاريخه‪1434/6/28:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا ‪ -‬قيــادة‬\n  ‫الســيارة حتــت تأثيرهــا‪ -‬إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‬\n                            ‫‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n      ‫‪ -1‬قول اهلل تعالى‪ (( :‬وال تلقوا بأيديكم إلى التهلكة )) البقرة‪195:‬‬\n                                              ‫‪ -2‬اإلقرار حجة على املقر‪.‬‬\n                   ‫‪ -3‬املواد (‪ )128‬و (‪ )131‬من نظام اإلجراءات اجلزائية‪.‬‬\n  ‫‪ -4‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬واملــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام‬\n                                ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n        ‫‪ -5‬الفقرة (‪ )8‬من جدول املخالفات رقم (‪ )1‬امللحق بنظام املرور‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة حبــوب‬\n  ‫اإلمفيتامــن بقصــد التعاطــي وتعاطيــه لهــا وقيادتــه الســيارة حتــت‬\n  ‫تأثيرهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقـ ًا لنظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة مــع إفهامــه بــأن عقوبتــه لقــاء‬\n  ‫القيــادة حتــت تأثيــر احلبــوب احملظــورة تقــرر مــن اجلهــة املختصة‪،‬وحيــث‬\n  ‫إنــه مت تفتيــش منــزل املدعــى عليــه بعــد ورود بــاغ مفاده أنــه يقوم بحيازة‬\n\n                                                                                       ‫‪208‬‬\n\f      ‫وتعاطــي املخــدرات داخــل املنــزل فعثــر فيــه علــى حبــوب اإلمفيتامــن‪،‬‬\n      ‫وأثبــت التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة‬\n      ‫لإلمفيتامــن‪ ،‬كمــا أقــر املدعــي العــام أمــام احملكمــة مبــا أســنده إليــه‬\n      ‫املدعــي العــام‪ ،‬وكمــا كان مــا تقــدم فــإن اإلقــرار حجــة علــى املقــر‪،‬‬\n      ‫وحيــث إن املدعــى عليــه أبــدى التوبــة وال يوجــد لــه ســوابق والكميــة‬\n      ‫احملــازة قليلــة‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب‬\n      ‫إليــه وقــررت جلــده ســتني جلــدة دفعــة واحــدة وســجنه مــدة ســتني يوم ـ ًا‬\n      ‫ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني وأفهمــت املدعــى عليــه‬\n      ‫بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر احلبــوب احملظــورة تقــرر‬\n      ‫مــن اجلهــة املختصــة‪ -‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                 ‫عليــه‪ -‬وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 3483974‬وتاريــخ‬\n      ‫‪1434/02/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34424915‬وتاريــخ‬\n      ‫‪1434/02/19‬ه ـ ففــي يــوم الســبت املوافق‪1434/03/21‬ه ـ حضــر‬\n      ‫املدعــي العــام كمــا حضــر املدعــى عليــه‪ ........ ،‬ســعودي رقــم ســجله‬\n      ‫املدنــي (‪ ).................‬وقــدم األول الئحــة دعــوى تتضمــن بــأن املدعــى‬\n      ‫عليــه البالــغ مــن العمــر (‪ )24‬ســنة غيــر محصــن ‪ ،‬موظــف أهلــي ‪،‬‬\n      ‫أوقــف بتاريــخ ‪1433/12/27‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/12/28‬هــ‪.‬‬\n      ‫وأنــه بتاريــخ ‪1433/12/25‬ه ـ تقــدم أحــد األشــخاص ببــاغ ملكافحــة‬\n      ‫املخــدرات مفــاده أن أخــاه يقــوم بحيــازة وتعاطــي املخــدرات داخــل‬\n\n‫‪209‬‬\n\f‫املنــزل وباالنتقــال إلــى املنــزل مت القبــض علــى املدعــى عليــه وبتفتيــش‬\n‫املنــزل عثــر علــى شــنطة تعــود للمدعــى عليــه بهــا إثباتــه ومحفظتــه‬\n‫وهواتفــه النقالــة وعثــر علــى عــدد (‪ )25‬خمســة وعشــرين حبــة أثبــت‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬لعــام ‪1433‬ه ـ الصــادر مــن‬\n‫املركــز االقليمــي ملراقبــة الســموم باملنطقــة الشــرقية إيجابيــة العينــة‬\n‫املرســلة ملــادة اإلمفيتامــن‪ .‬وبســماع أقــوال املدعــى عليــه أقــر بحيازتــه‬\n‫للكميــة املضبوطــة مــن حبــوب الكبتاجــون وأنهــا تعــود لــه وغرضــه‬\n‫منهــا االســتخدام الشــخصي وأنــه يقــود الســيارة أثنــاء تعاطيــه احلبــوب‪.‬‬\n‫وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام إليــه بحيازتــه مــا عــدده‬\n‫(‪ )25‬خمســة وعشــرين حبــة مــن حبــوب اإلمفيتامــن بقصــد التعاطــي‬\n‫وتعاطيــه لهــا وقيادتــه الســيارة حتــت تأثيرهــا ‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫املوضحــة بالالئحــة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n‫علــى أي ســوابق جنائيــة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫ونظامــا لــذا أطلب‪-:‬إثبــات مــا أســند إليــه وفــق الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪ -1‬بعقوبــة الســجن وفــق الفقــرة (‪)1‬مــن املــادة (‪)41‬مــن النظــام‪2 .‬ـ منعــه‬\n‫مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املادة(‪)56‬مــن النظــام ‪-3‬إثبــات‬\n‫قيادتــه للســيارة حتــت تأثيــر احلبــوب احملظــورة وفقــا للفقــرة رقــم (‪)8‬‬\n‫مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة‬\n‫املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف‬\n‫‪1429/10/24‬هــ‪ .‬هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n\n\n                                                                                        ‫‪210‬‬\n\f      ‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ املذكــور‬     ‫قائ ـ ً‬\n      ‫وأنــه عثــر بحوزتــي علــى عــدده (‪ )25‬خمســة وعشــرين حبــة مــن حبــوب‬\n      ‫اإلمفيتامــن احملظــورة وأن قصــدي مــن حيازتهــا التعاطــي وأننــي‬\n      ‫أتعاطــى هــذه احلبــوب وقــدت الســيارة حتــت تأثيرهــا كل ذلــك صحيــح‬\n      ‫لكننــي تبــت عــن هــذا العمــل هكــذا أجــاب وبدراســة املعاملــة جــرى‬\n      ‫االطــاع علــى التقريــر الكيمــاوي وصحيفــة الســوابق املشــار لهمــا‬\n      ‫ـاء علــى مــا تقــدم وحيــث‬‫أعــاه فوجدتهــا كمــا ذكــر املدعــي العــام فبنـ ً‬\n      ‫تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى عليــه بتعاطــي حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة وقيــادة الســيارة حتــت تأثيرهــا وحيــازة‬\n      ‫(‪ )25‬خمســة وعشــرين حبــة مــن حبــوب اإلمفيتامــن بقصــد التعاطــي‬\n      ‫ويطلــب معاقبتــه علــى ذلــك وألن هــذه احملكمــة مختصــة بنظــر الدعــوى‬\n      ‫بنــاء علــى املــواد (‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار‬\n      ‫املدعــى عليــه وهــو بكامــل أهليتــه بجميــع مــا جــاء يف دعــوى املدعــي‬\n      ‫العــام وألن اإلقــرار حجــة علــى املقــر وألن مــا أقــدم عليــه أفعــال محرمــة‬\n      ‫شــرع ًا ملــا يف تعاطــي هــذه احلبــوب مــن أضــرار صحيــة بالغــة واهلل تعالــى‬\n      ‫يقــول (( وال تلقــوا بأيديكــم إلــى التهلكــة )) البقــرة‪ 195:‬كمــا أن‬\n      ‫حيــازة وتعاطــي احلبــوب املنبهــة احملظــورة مجــرم نظامـ ًا وفقـ ًا للفقــرة (‪)2‬‬\n      ‫مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات كمــا أن قيــادة الســيارة‬\n      ‫حتــت تأثيــر املؤثــرات العقليــة فعــل مجــرم نظام ـ ًا وفق ـ ًا للفقرة(‪)8‬مــن‬\n      ‫جــدول املخالفــات رقــم (‪)1‬امللحــق بنظــام املــرور‪ .‬لهــذا كلــه فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه احلاضــر ‪........‬باآلتــي‪ :‬أوالً‪ :‬تعاطــي حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة‪ .‬ثاني ـاً‪ :‬حيــازة (‪ )25‬خمســة وعشــرين‬\n      ‫حبــة مــن حبــوب اإلمفيتامــن املنبهــة واحملظــورة بقصــد التعاطــي‪ .‬ثالثـاً‪:‬‬\n\n\n‫‪211‬‬\n\f‫قيــادة الســيارة حتــت تأثيــر احلبــوب املنبهــة احملظــورة‪ .‬وبعــد االطــاع‬\n‫علــى املــواد(‪ )60،56،41‬مــن نظــام مكافحــة املخــدرات ونظــر ًا لقلــة‬\n‫الكميــة احملــازة وعــدم وجــود ســوابق علــى املدعــى عليــه وملــا أبــداه مــن‬\n‫التوبــة فقــد حكمــت بتعزيــر املدعــى عليــه للحــق العــام بجلــده ســتني‬\n‫جلــدة دفعــة واحــدة و ســجنه مــدة ثالثــن يومـ ًا ومنعــه مــن الســفر خــارج‬\n‫اململكــة مــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن وبإعــان‬\n‫احلكــم قنــع بــه املدعــى عليــه وقــرر املدعــي العــام اعتراضــه وطلــب رفــع‬\n‫املعاملــة حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده وبعــد ففــي‬\n‫هــذا اليــوم األربعاء‪1434/6/7‬ه ـ حضــر املدعــي العــام واملدعــى عليــه‬\n‫‪........‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫وبرفقهــا القــرار برقــم ‪ 34210844‬يف ‪1434/5/11‬ه ـ املتضمــن‪ :‬لوحظ‬\n‫أوالً‪ :‬أن مــا حكــم بــه فضيلتــه مــن ســجن علــى املدعــى عليــه قليــل جــداً‪.‬‬\n‫ثاني ـاً‪ :‬لــم ُيفهــم فضيلتــه بعــد ثبــوت إدانــة املدعــى عليــه بقيــادة الســيارة‬\n‫حتــت تأثيــر احلبــوب احملظــورة أن تقريــر اجلــزاء راجــع للجهــة املختصــة‬\n‫أ‪.‬هــ‪ .‬واســتجابة لوجهــة نظــر أصحــاب الفضيلــة فقــد قــررت الرجــوع عما‬\n‫حكمــت بــه مــن عقوبــة الســجن فقــط وحكمــت بتعزيــر املدعــى عليــه‬\n‫بســجنه ســتني يوم ـ ًا إضافــة لعقوبــة اجللــد واملنــع مــن الســفر الســابقتني‬\n‫كمــا أفهمتــه بــأن عقوبتــه علــى قيــادة الســيارة حتــت تأثيــر احلبــوب‬\n‫املنبهــة احملظــورة تقــرر مــن اجلهــة املختصــة وبإعــان احلكــم قنــع بــه‬\n‫املدعــى عليــه وقــرر املدعــي العــام أنــه ال يــزال علــى اعتراضــه احلمــد هلل‬\n‫وحــده وبعــد فلــدي أنــا رئيس احملكمة اجلزائيــة مبحافظة القطيف فقد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n\n\n                                                                                          ‫‪212‬‬\n\f      ‫القــرار رقــم ‪ 34254934‬يف ‪1434/6/28‬ه ـ املتضمــن املصادقــة علــى‬\n            ‫احلكــم بعــد اإلجــراء األخيــر و للبيــان أحلــق يف ‪1434/7/10‬هــ‪.‬‬\n\n\n\n\n‫‪213‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":208,"source_page_end":213,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e3875c0f1eca56d78114f56fb041934e33ad1665782a45ed0ada39e144e4188e","normalized_text_hash":"d98a4adfbe1beecddd778579d07d215b2a90cd14bcaca17a877f32d309d9c221","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p208-34167139"},{"id":"c5984374-e7ab-5b0b-a1d8-b8fe7f075555","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازه احلشيش املخدر -تستر على الغير -إنكار املدعى عليه -اخلطأ يف العفو خير من اخلطأ يف العقوبة -توجه الشبهة (تهمة ) املوجبة للتعزير -عدم وجود سوابق قضائية -التعزير بالسجن واجللد.","document_number":"34184286","case_number":"3485847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية اخلامسة مبحكمة اإلستئناف يف منطقة مكة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/20","year":"1434","subject":"مخدرات -حيازه احلشيش املخدر -تستر على الغير -إنكار املدعى عليه -اخلطأ يف العفو خير من اخلطأ يف العقوبة -توجه الشبهة (تهمة ) املوجبة للتعزير -عدم وجود سوابق قضائية -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34184286:‬تاريخه‪1434/02/20 :‬هـ‬\n                      ‫رقم الدعوى‪3485847:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34246391‬تاريخه‪1434/06/20:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازه احلشــيش املخــدر ‪ -‬تســتر علــى الغيــر ‪ -‬إنــكار املدعــى‬\n ‫عليــه ‪ -‬اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة ‪ -‬توجــه الشــبهة‬\n ‫(تهمــة ) املوجبــة للتعزيــر ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬التعزيــر‬\n                                                            ‫بالســجن واجللــد‪.‬‬\n\n\n\n\n                                             ‫ما أشير له يف تسبيب احلكم ‪.‬‬\n\n\n\n ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالتســتر علــى‬\n ‫حائــز مخــدرات وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n ‫تعزيريــة ‪ ،‬الحظــت الدوريــات األمنيــة شــخصا يقــود دراجــة ناريــة‬\n ‫بــدون لوحــة فجــرى محاولــة إيقافــه إال أنــه الذ بالفــرار وبالقبــض عليــه‬\n ‫وتفتيــش الدراجــة وجــد بهــا مــادة أثبــت التقريــر الكيميائــي إيجابيتهــا‬\n ‫للحشــيش املخــدر‪ ،‬بالرجــوع للنهايــة الطرفيــة تبــن أنهــا تعــود لشــخص‬\n ‫وباســتجوابه أجــاب بأنــه بــاع الدراجــة للمدعــى عليــه ‪ ،‬وبعرضهمــا علــى‬\n ‫أفــراد الدوريــة القابضــة قــررا بــأن قائــد الدراجــة لــم يكــن أحدهمــا ‪،‬‬\n ‫أنكــر املدعــى عليــه التهمــة فطلــب مــن املدعــي العــام البينــة ‪ ،‬أحضــر‬\n ‫املدعــي العــام شــاهدين شــهدا بقيــام املدعــى عليــه بشــراء الدراجــة مــن‬\n\n                                                                                   ‫‪214‬‬\n\f      ‫املســجلة باســمه ‪ ،‬بعــرض شــهادتهما علــى املدعــى عليــه أنكرهــا ‪،‬‬\n      ‫أحضــر املدعــي العــام البينــة علــى عدالــة الشــاهدين ‪ ،‬طلــب مــن املدعــي‬\n      ‫العــام البينــة علــى وجــود املــادة املخــدرة يف الدراجــة فأحضــر رجلــي‬\n      ‫الدوريــة وشــهدا بذلــك وجــرى تعديلهمــا شــرعا ‪ ،‬وإلنــكار املدعــى‬\n      ‫عليــه وبنــاء علــى شــهادة الشــاهدين املعدلــن شــرعا وألن األمــر يــرد‬\n      ‫عليــه االحتمــال فيوجــب توجيــه الشــبهة ولعــدم وجــود ســوابق مســجلة ‪،‬‬\n      ‫وألن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة ‪ ،‬لذلــك كلــه قــررت‬\n      ‫احملكمــة توجــه التهمــة عليــه بالتســتر علــى حائــز مخــدرات وحكمــت‬\n      ‫عليــه بســجنه أســبوعا ابتــداء مــن إيقافــه وجلــده عشــرين جلــدة دفعــة‬\n      ‫واحــدة ‪ ،‬قــرر املدعــي العــام واملدعــى عليــه عــدم القناعــة فأفهمــا‬\n           ‫بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ ‪1434/02/20‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/02/20‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/02/26‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 15‬وفيهــا‬\n      ‫حضــر املدعــي العام‪..........‬ســعودي اجلنســية املكلــف برقــم ‪..........‬يف‬\n      ‫ا أدعــي علــى ‪.......... :‬ســعودي اجلنســية‬   ‫‪1433 / 1/1‬ه ـ وادعــى قائ ـ ً‬\n      ‫مبوجــب الســجل رقــم‪ ..........‬بتاريــخ ‪1433/12/14‬ه ـ مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل دوريــات األمــن الســرية بعــد أن الحــظ أفــراد‬\n      ‫الدوريــة شــخص ميتطــي دراجــة ناريــة بــدون لوحــة فأشــتبه بــه وعنــد‬\n\n‫‪215‬‬\n\f‫محاولــة اســتيقافه قــام برمــي الدراجــة والذ بالفــرار وبتفتيــش الدراجــة‬\n‫وجــدت مــادة بنيــة اللــون يشــتبه بــأن تكــون مــن مــادة احلشــيش وزنهــا‬\n‫(‪ )0.50‬خمســن يف املئــة مــن اجلــرام ووجــدت اللوحــة مخبــأة وبالرجــوع‬\n‫للنهايــة الطرفيــة تبــن أن ملكيتهــا تعــود لشــخص يدعى‪..........‬وبعــرض‬\n‫املدعــو‪ ..........‬واملدعــى عليــه علــى أفــراد دوريــات األمــن الســرية ذكــروا‬\n‫بــأن الشــخص املطلــوب والــذي كان يقــود الدراجــة الناريــة ليــس‬\n‫منهمــا ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي ‪..........‬إيجابيــة املــادة‬\n‫املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر واحتوائهــا للمــادة‬\n‫الفعالــة لــه واملدرجــة بجــدول رقــم(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة‪ .‬بســماع أقــوال املدعــو ‪ :..........‬أفــاد بأنــه‬\n‫قــام ببيــع الدراجــة الناريــة علــى املدعــى عليــه منــذ بدايــة عــام ‪1433‬ه ـ‬\n‫وال يوجــد لديــه أي إثبــات وذكــر بــان لديــه شــهود علــى ذلــك ‪ .‬بســماع‬\n‫شــهادة كل مــن ‪ ،..........‬و‪ ..........‬حيــث أفــادا بــأن الدراجــة الناريــة تعــود‬\n‫ملكيتهــا لــ‪ ،..........‬وأنــه قــد قــام ببيعهــا للمدعــى عليــه مببلــغ (‪)3000‬‬\n‫ثالثــة آالف ريــال وذلــك قبــل ســنة تقريب ـ ًا وأنهمــا شــهدا املبايعــة‪ .‬وقــد‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه ‪ :‬بالتســتر علــى‬\n‫حائــز املخــدرات ‪ .‬وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرعا لــذا أطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء تســتره علــى حائــز مخــدرات ‪.‬‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه أنكــر مــا جــاء يف الدعــوى هكــذا‬\n‫أجــاب وبســؤال املدعــي العــام عــن البينــة فقــال أطلــب إمهالــي إلحظارهــا‬\n‫يــوم االثنــن ‪1434 /3 /2‬ه ـ الســاعة التاســعة صباح ـ ًا وأقفلــت اجللســة‬\n‫الســاعة الثانيــة عشــر والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                         ‫‪216‬‬\n\f                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/03/02‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي‬\n      ‫العــام واملدعــى عليــه وبســؤال املدعــي العــام عمــا طلــب االمهــال ألجلــه‬\n      ‫قــال حضــرت البينــة وأطلــب ســماعها وعليــه حضــر كل مــن ‪..........‬‬\n      ‫ســعودي اجلنســية ســجل رقــم ‪..........‬و‪ ..........‬ســعودي اجلنســية ســجل رقــم‬\n      ‫‪ ..........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫منفــردا قائــا أشــهد هلل بــأن املدعــى عليــه اشــترى دبابــا مــن ‪..........‬‬\n      ‫وحضرنــا املبايعــة بينهمــا واشــتراه مببلــغ ثالثــة آالف ريــال يف حــج‬\n      ‫عــام ‪1432‬ه ـ وكانــت املبايعــة يف اســتراحة والدنــا ب‪ ..........‬وكان‬\n      ‫ذلــك يف املســاء وذلــك بحضــور الطرفــن هكــذا شــهدا وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه أنكــر مــا جــاء يف الشــهادة هكــذا أجــاب وعليــه‬\n      ‫جــرى رفــع اجللســة إلحضــار مزكــن ورفعــت اجللســة إلــى يــوم االثنــن‬\n      ‫‪1434/3/16‬ه ـ الســاعة العاشــرة صباحــا وأقفلــت اجللســة الســاعة‬\n      ‫الثانيــة عشــر ظهــرا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/02‬هــ‪.‬‬\n      ‫احلمد هلل وحده وبعد ففي يوم اإلثنني املوافق‪ 1434/03/16‬هـ افتتحت‬\n      ‫اجللســة الســاعة وفيهــا حضــر املدعــي العــام واملدعــى عليــه وحضــر‬\n      ‫املزكــن وهــم ‪..........‬و ‪..........‬وشــهدا بعدالــة الشــاهدين املذكوريــن‬\n      ‫ســابق ًا وبســؤال املدعــي العــام البينــة علــى وجــود املخــدرات يف الدراجــة‬\n      ‫الناريــة العائــدة ملكيتهــا للمدعــى عليــه فأجــاب أطلــب املهلــة لذلــك‬\n      ‫عليــه رفعــت اجللســة يف يــوم اإلثنــن ‪1434 /3 /23‬ه ـ الســاعة التاســعة‬\n      ‫صباحـ ًا وأقفلــت اجللســة الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n‫‪217‬‬\n\f‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/03/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12.30‬وفيهــا حضــر املدعــي العــام ولــم يحضــر‬\n‫املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة فقــال لــم حتضــر وأطلــب‬\n‫إمهالــي إلحضارهــا يف يــوم اإلثنــن ‪1434 / 4 /1‬ه ـ الســاعة التاســعة‬\n‫صباحـ ًا وعليــه أقفلــت اجللســة الســاعة الواحــدة ظهــر ًا وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/03/23‬ه ـ‬\n‫ا حلمــد هلل وحــده وبعــد ف ففــي يــوم اإلثنــن املوافق‪1434/04/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وبســؤال املدعــي العــام عمــا طلــب االمهــال‬\n‫ألجلــه قــال حضــرت البينــة وأطلــب ســماعها وعليــه حضــر كل مــن‬\n‫‪..........‬ســعودي اجلنســية ســجل رقــم ‪..........‬و‪ ..........‬ســعودي اجلنســية‬\n‫ســجل رقــم ‪..........‬وبســؤالهم عمــا لديهــم مــن شــهادة شــهد كل‬\n‫واحــد منهمــا قائــا أشــهد هلل بأننــا كنــا يف مهمــة ووجدنــا شــخصا‬\n‫يقــود دراجــة ناريــة فشــككنا يف أمــره وعليــه أثــر االرتبــاك ثــم قمنــا‬\n‫مبتابعتــه فرمــى الدراجــة وهــرب وقمنــا بتفتيــش الدراجــة فوجدنــا بهــا‬\n‫قطعــة مــن احلشــيش املخــدر وحــن عــرض املدعــى عليــه علينــا يف إدارة‬\n‫مكافحــة املخــدرات تبــن لنــا أنــه ليــس هــو الــذي كان يقــود الدراجــة‬\n‫وليــس البائــع األول هكــذا شــهدا وجــرى تعديــل الشــهود مــن قبــل‪..........‬‬\n‫و‪..........‬ورفعــت اجللســة إلحضــار املدعــى عليــه وأجلــت إلــى يــوم االثنــن‬\n‫‪1434/4/8‬ه ـ الســاعة التاســعة صباحــا وأقفلــت اجللســة الســاعة‬\n‫العاشــرة والنصــف صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n                                                                                     ‫‪218‬‬\n\f      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/01‬ه ـ احلمــد‬\n      ‫هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه فبنــاء علــى مــا تقــدم وإلنــكار املدعــى عليــه مبــا جــاء يف الدعــوى‬\n      ‫ولشــهادة الشــهود املعدلــة شــرعا وألن األمــر يــرد عليــه االحتمــال فيوجب‬\n      ‫توجيــه الشــبهة ولعــدم ســوابقه وألن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف‬\n      ‫العقوبــة لذلــك كلــه فــإن الشــبهة تتوجــه بقيــام املدعــى عليــه بالتســتر‬\n      ‫علــى حائــز املخــدرات وعليــه فقــد حكمــت عليــه مبــا يلــي ‪ -1 :‬بســجنه‬\n      ‫أســبوعا ابتــداء مــن تاريــخ إيقافــه‪ -2 .‬بجلــده عشــرين جلــدة دفعــة‬\n      ‫واحــدة وبعــرض احلكــم علــى املدعــي العــام قــرر االعتــراض بالئحــة‬\n      ‫وجــرى تســليمه نســخة مــن القــرار الشــرعي وأفهــم بنظــام االســتئناف‬\n      ‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة‬\n      ‫وأفهــم بنظــام االســتئناف وأقفلــت اجللســة الســاعة العاشــرة والنصــف‬\n      ‫صباحــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/08‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n      ‫يــوم اإلثنــن املوافــق‪ 1434/07/10‬ه ـ افتتحــت اجللســة وفيهــا عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا قرارهــا رقــم ‪34246391‬‬\n      ‫وتاريــخ ‪1434/6/20‬ه ـ املتضمــن املوافقــة علــى احلكــم الصــادر منــا‬\n      ‫برقــم ‪ 34184286‬وتاريــخ ‪1434/4/10‬ه ـ لــذا أمــرت باحلــاق ذلــك‬\n      ‫لضبطــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/10‬ه ـ احلمــد هلل وحــده والصــاة‬\n      ‫والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد جــرى منــا نحــن قضــاة‬\n      ‫الدائــرة اجلزائيــة اخلامســة مبحكمــة اإلســتئناف يف منطقــة مكــة‬\n\n\n‫‪219‬‬\n\f‫املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪34435749‬وتاريــخ ‪1434/5/25‬ه ـ‬\n‫املرفــق بهــا القــرار رقــم ‪34184286‬وتاريخ‪1434/4/10‬ه ـ الصــادر مــن‬\n‫فضيلــة الشــيخ‪ ..........‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ..........‬ســعودي اجلنســية املتهــم يف‬\n‫مخــدرات احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                 ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":214,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f843e726c481baffb74e0f67e2913740b69f1c549877531be7662e49b5d39138","normalized_text_hash":"7bb889d788a6a7584d5f9ae8dde25578c83f6c266a6938cf15ab29ec0b7ddc56","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p214-34184286"},{"id":"7b989df5-6d5d-5ce3-82ee-39fc6e2ff1ab","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة ألجل التداوي مبوجب تقرير طبي -رد دعوى","document_number":"34173841","case_number":"3492036","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/28","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي وتعاطيها -حيازة ألجل التداوي مبوجب تقرير طبي -رد دعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34173841 :‬تاريخه‪1434/03/28 :‬هـ‬\n                            ‫رقم الدعوى‪3492036 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3488340‬تاريخه‪1434/4/27:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n       ‫وتعاطيهــا ‪ -‬حيــازة ألجــل التــداوي مبوجــب تقريــر طبــي ‪ -‬رد دعــوى‬\n                                                             ‫‪ -‬إخــاء ســبيل‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬األصل براءة الذمة‪.‬‬\n                                 ‫‪ -2‬اخلطأ يف العفو خير من اخلطأ يف العقوبة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإثبــات إدانتــه بحيــازة احلشــيش‬\n       ‫املخــدر وحبــوب الترامــادول احملظــورة بقصــد التعاطــي وتعاطيــه لهــا‪،‬‬\n       ‫واحلكــم عليــه بعقوبــة الســجن واإلبعــاد عــن البــاد طبقــا لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث أنــه مت تفتيــش مكتــب‬\n       ‫املدعــى عليــه بعــد ورود معلومــات عنــه فعثــر فيــه علــى حبــوب الترامادول‬\n       ‫احملظــورة وقطعــة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر الكيميائــي‬\n       ‫الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر ولعقــار الترامــادول‪،‬‬\n       ‫كمــا أنــه أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن حيــازة‬\n       ‫حبــوب الترامــادول لالســتخدام الشــخصي وتعاطيــه لهــا ودفــع بأنــه‬\n       ‫يســتخدمها كعــاج مســكن بوصفــة طبيــة وأنكــر حيازتــه وتعاطيــه‬\n\n‫‪221‬‬\n\f‫للحشــيش املخــدر بنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد دعــوى‬\n‫املدعــي العــام وإخــاء ســبيل املدعــى عليــه مــن هــذه الدعــوى‪ ،‬وقنــع‬\n‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة‬\n                                    ‫االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يوم األربعــاء املوافق ‪1434/3/25‬هـ لدي أنا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                            ‫‪ ........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )3492036‬وتاريــخ ‪1434/2/25‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر ‪ ........‬مصــري اجلنســية مبوجــب رخصــة‬\n‫إقامــة رقــم (‪ )........‬وقــدم املدعــي العــام ‪........‬الئحــة االدعــاء املتضمنــة‬\n‫بصفتي مدعي ًا عام ًا بدائرة االدعاء العام لفرع الهيئة باملنطقة الشرقية‬\n‫أدعــي علــى املذكــور أعــاه حيــث إنــه باالطــاع علــى محضــر البــاغ‬\n‫والضبــط والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة‬\n‫املخــدرات بالدمــام تبــن أنــه يف يــوم األحــد املوافــق ‪1434/1/17‬ه ـ ورد‬\n‫معلومــات عــن شــخص مصــري اجلنســية يدعــى‪ ........‬احلشــيش املخــدر و‬\n‫حبــوب الترامــادول احملظــورة و يعمــل بـ‪........‬بالشــارع ‪........‬بالدمــام وبنــاء‬\n‫علــى مــا ذكــر مت االنتقــال للموقــع إذ لوحــظ شــخص بجــوار احملــل‬\n‫تنطبــق عليــه نقــس املواصفــات وبعــد أخبــاره بــأن الفرقــة رجــال أمــن‬\n‫جــرى تفتيــش املذكــور شــخصيا و تفتيــش ســيارته ولــم يعثــر معــه علــى‬\n‫أي ممنوعــات وبنــاء علــى املــادة ( ‪ ) 43‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫جــرى تفتيــش مكتــب املذكــور وعثــر علــى عــدد ( ‪ ) 28‬حبــة حمــراء‬\n‫اللــون يشــتبه أن تكــون مــن حبــوب الترامــادول احملظــورة كمــا عثــر‬\n\n                                                                                        ‫‪222‬‬\n\f      ‫علــى فرطــه داخــل أدراج املكتــب يشــتبه أن تكــون ممزوجــة مبــادة‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا ( ‪ ) 0.2‬اثنــان مــن العشــرة مــن اجلــرام وقــد‬\n      ‫ورد التقريــر الكيمــاوي الشــرعي رقــم ( ‪ )........‬وتاريــخ ‪1434/2 /2‬ه ـ‬\n      ‫املتضمــن ايجابيــة احلبــوب املضبوطــة لعقــار الترامــادول و املــدرج يف‬\n      ‫اجلــدول األول فئــة (هــ) امللحــق بنظــام مكافحــة املخــدرات ومــا أثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي املشــار إليــه احتــواء التبــغ املضبــوط علــى‬\n      ‫مــادة احلشــيش املخــدر و املــدرج يف اجلــدول األول فئــة (أ) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات وبســماع أقوالــه األوليــة مــن قبــل رجــال الضبــط‬\n      ‫اجلنائــي أقــر بحيازتــه حلبــوب الترامــادول لقصــد االســتخدام الشــخصي‬\n      ‫كعــاج مســكن وأنــه تعاطــى احلبــوب احملظــورة قبــل القبــض عليــه‬\n      ‫بثالثــة أســابيع وأنكــر حيازتــه للحشــيش املخــدر وقــد انتهــى التحقيــق‬\n      ‫إلى توجيه االتهام لـ‪ ........‬باآلتي‪ -1 :‬بحيازة (‪ )28‬ثمانية وعشــرون حبة‬\n      ‫مــن حبــوب الترامــادول احملظــورة بقصــد التعاطــي ‪ -2‬تعاطــي احلبــوب‬\n      ‫احملظــورة‪ -3 .‬حيــازة تبــغ بلــغ وزنــه ( ‪ ) 0.2‬اثنــان مــن العشــرة مــن‬\n      ‫اجلــرام يحتــوي علــى مــادة احلشــيش املخــدر بقصــد التعاطي وذلــك لألدلة‬\n      ‫والقرائــن التاليــة‪ -1 :‬إقــرار املدعــى عليــه واملــدون علــى الصفحتــن رقــم‬\n      ‫(‪ )19.18‬مــن ملــف ضبــط إجــراءات االســتدالل‪ -2 .‬محضــر البــاغ‬\n      ‫والضبــط والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي واملــدون علــى‬\n      ‫الصفحــة رقــم (‪ )11‬مــن ملــف ضبــط إجــراءات االســتدالل ‪ -3‬التقريــر‬\n      ‫الكيمــاوي املشــار إليــه واملرفــق علــى اللفــة رقــم (‪ )11‬وحيــث إن مــا‬\n      ‫أقــدم عليــه املدعــى عليه‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرعا‪ -‬فعــل‬\n      ‫وفقــا‬\n         ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا أســند إليــه ً‬\n      ‫للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n\n\n‫‪223‬‬\n\f‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة الســجن الــواردة‬\n‫بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬مــن النظــام‪ -2 .‬إبعــاده عــن البــاد‬\n‫إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن النظــام وبــاهلل‬\n‫التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العام من‬\n‫حيازتــي لعــدد ثمــان وعشــرين حبــة من حبــوب الترامــادول وأنني أتعاطى‬\n‫منهــا فهــذا صحيــح وذلــك ألننــي مريــض ومصاب بــآالم يف فقرات الظهر‬\n‫وأســتخدم هــذه احلبــوب بوصفــة طبيــة لتســكني آالم الظهــر ومــا ذكــره‬\n‫مــن ضبــط فرطــة التبــغ احملتــوي علــى احلشــيش املخــدر يف مكتبي فهذا‬\n‫صحيــح ولكــن ال عالقــة لــي بهــا ألن املكتــب مفتــوح وليــس لــه بــاب‬\n‫ويوجــد فيــه أربعــة عشــر موظفــا تقريبــا وقــد تكــون الفرطــة ألحدهــم‬\n‫هــذه إجابتــي ثــم أبــرز التقريــر طبــي الصــادر مــن مستشــفى تــداوي العام‬\n‫بتاريــخ ‪1434/1/26‬ه ـ املتضمــن أنــه بالكشــف علــى املدعــى عليــه‬\n‫تبــن وجــود تغيــرات تنكســية للعمــود الفقــري القطنــي وبعــد مراجعــة‬\n‫ملــف املريــض لوحــظ وجــود عــدة زيــارات لعيــادة العظــام بعــدة تواريــخ‬\n‫آخرهــا بتاريــخ ‪2010/3/7‬م وزيارتــان أخريــان بتاريــخ ‪2008/8/26‬م‬\n‫وبتاريــخ ‪2008/1/26‬م مــع األدويــة املناســبة وإعطــاء وصفــات عقــار‬\n‫الترامــادول يف املــرات الســابقة املذكــورة وبنــاء علــى طلبــه أعطــي هــذا‬\n‫التقريــر وبتأمــل التقريــر الحظــت أنــه صــدر بعــد القبــض علــى املدعــى‬\n‫عليــه بأســبوع كمــا تضمــن أن آخــر زيــارة لــه للمستشــفى كانــت قبــل‬\n‫هــذه القضيــة بثــاث ســنوات تقريبـ ًا وعليــه قــررت الكتابــة للمستشــفى‬\n‫للتأكــد مــن صحــة هــذا التقريــر وهــل التوصيــة باســتخدام هــذه احلبــوب‬\n‫مســتمر طيلــة هــذه املــدة ورفعــت اجللســة وتأجلــت إلــى حــن ورود اإلجابــة‬\n‫ويف يــوم الســبت املوافــق ‪1434/3/28‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫املدعــى عليــه املــدون هويتــه ســابق ًا وقــد وردنــا التقريــر الطبــي الصــادر‬\n      ‫مــن مستشــفى تــداوي العــام برقــم ( ‪ )6/2/13‬وتاريــخ ‪1434/3/25‬ه ـ‬\n      ‫واملتضمــن أنــه بالكشــف علــى املدعــى عليــه تبــن وجــود تغيــرات‬\n      ‫تنكســية للعمــود الفقــري القطنــي وبعــد مراجعــه ملــف املريــض كانــت‬\n      ‫آخــر زيــارة بتاريــخ ‪2012/3/7‬م وتعــد الشــكايات التــي لــدى املريــض‬\n      ‫مزمنــة وهــي مرشــحة للتفاقــم تدريجي ـ ًا مــع الوقــت وخاصــة يف حــال‬\n      ‫اســتمرار اجلهــد والتعــب وهــي شــكايات شــديدة أحيان ـ ًا وال تســتجيب‬\n      ‫للمســكنات واألدويــة التقليديــة ممــا يســتدعي صرف األدوية املســكنة‬\n      ‫القويــة جــد ًا وغيــر التقليديــة وعــادة يتــم يف كل مــرة صــرف عشــرين‬\n      ‫قرص ـ ًا أو أكثــر حســب التركيــز املســتخدم وتتــراوح اجلرعــة اليوميــة‬\n      ‫مــا بــن قــرص واحــد وأربعــة أقــراص يف احلــاالت الشــديدة وقــد تزيــد‬\n      ‫كمــا أحضــر املدعــى عليــه للشــهادة وأدائهــا كل مــن ‪ ........‬مصــري‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم‪ ........‬و ‪ ........‬مصــري مبوجب رخصة إقامة‬\n      ‫رقــم ‪ ........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا‬\n      ‫ا إننــي أعمــل مــع املدعــى عليــه يف معــرض ‪........‬ألنظمــة‬    ‫مبفــرده قائ ـ ً‬\n      ‫املكاتــب وأشــهد بــاهلل العظيــم بــأن مكتــب املدعــى عليــه يف املعــرض‬\n      ‫يف مــكان مفتــوح ليــس لــه بــاب ويســتطيع جميــع العاملــن يف املعــرض‬\n      ‫مــن موظفــن وعمــال الوصــول إليــه وكثيــر ًا مــن األحيــان يدخلــون‬\n      ‫للمكتــب يف حــال غيبــة املدعــى عليــه ألجــل الفاكــس أو التنظيــف‬\n      ‫ونحــو ذلــك هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد هكــذا شــهدا‬\n      ‫كمــا حضــر لتعديــل الشــاهدين كل مــن‪ ........‬مصــري مبوجــب رخصــة‬\n      ‫إقامــة رقــم ‪ ........‬و ‪ ........‬مصــري مبوجــب رخصــة إقامــة رقــم‪ ........‬وقــد‬\n      ‫شــهد كل واحــد منهمــا بقولــه إننــي أعــرف الشــاهدين وهمــا عدلــن‬\n\n\n‫‪225‬‬\n\f‫ثقتــن هكــذا شــهدا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء‬\n‫علــى التقريريــن الطبيــن املرصوديــن واللــذان يثبتــان وجــود أعــراض‬\n‫مرضيــة للمدعــى عليــه تســتدعي العــاج بحبــوب الترامــادول املضبوطــة‬\n‫معــه وبنــاء علــى شــهادة الشــاهدين املعدلــن التعديل الشــرعي واملتضمنة‬\n‫أن مكتــب املدعــى عليــه يف مــكان مفتــوح وليــس لــه بــاب ويســتطيع‬\n‫جميــع املوظفــن والعاملــن مــن الوصــول إليــه وأنهــم أحيان ـ ًا يدخلــون‬\n‫فيــه حــال غيبــة املدعــى عليــه وقــد تكــون الفرطــه املمزوجــة باحلشــيش‬\n‫واملضبوطــة داخــل املكتــب عائــدة ألي منهــم وحيــث إن األصــل بــراءة‬\n‫الذمــة وحيــث إن اخلطــأ يف العفــو خيــر مــن اخلطــأ يف العقوبــة لــذا فقــد‬\n‫حكمــت بــرد دعــوى املدعــي العــام وإخــاء ســبيل املدعــى عليــه مــن هــذه‬\n‫الدعــوى وبعــرض ذلــك علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي‬\n‫العــام االعتــراض واالكتفــاء مبــا يف أوراق املعاملــة فأجيــب لطلبه وباهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف ‪1434/3/28‬هــ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/4/30‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الثانيــة عشــرة والنصــف وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫برقــم (‪ )34/883408‬وتاريــخ ‪1434/4/27‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام‪ ........‬ضــد ‪ ........‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة‬\n‫الثانيــة برقــم (‪ )34192862‬وتاريــخ ‪1434/4/21‬ه ـ املتضمــن املصادقــة‬\n‫علــى احلكــم لــذا جــرى إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلى‬\n                         ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                                      ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":221,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"53762ad04fe43406c1be4d2d9cc63a941a9d03c0fd86c05cd44d22dbe82b72ce","normalized_text_hash":"f110f2ddea3d92a362df019861027ff33c9386e623314f2926c2e590459b4556","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p221-34173841"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
